// Generated & curated comprehensive multi-language details translator for RapidEFI
// Supports 19 languages for Hackintosh architectures, BIOS settings, SMBIOS models, Kext functions, Boot arguments, Quirks, and UI details.

import 'package:flutter/material.dart';

class HackintoshDetailsTranslator {
  static String _currentLocale = 'en';

  static void setLocale(String locale) {
    _currentLocale = locale;
  }

  static String get currentLocale => _currentLocale;

  static String _resolveLocale(BuildContext? context, [String? locale]) {
    if (locale != null && locale.isNotEmpty) return locale;
    if (context != null) {
      final loc = Localizations.maybeLocaleOf(context);
      if (loc != null) {
        if (loc.languageCode == 'zh') {
          if (loc.scriptCode == 'Hant' || loc.countryCode == 'TW' || loc.countryCode == 'HK') {
            return 'zh_Hant';
          }
          return 'zh';
        }
        return loc.languageCode;
      }
    }
    return _currentLocale;
  }

  /// Central universal translator for any detail text, sentence, or description.
  static String translate(String text, {BuildContext? context, String? locale}) {
    final trimmed = text.trim();
    if (trimmed.isEmpty) return text;
    final lang = _resolveLocale(context, locale);
    if (lang == 'en') return text;

    // Check direct dictionary match
    final map = _generalDetails[trimmed];
    if (map != null && map.containsKey(lang) && map[lang]!.isNotEmpty) {
      return map[lang]!;
    }

    // Check CPU note match
    final cpuNote = _cpuNotes[trimmed];
    if (cpuNote != null && cpuNote.containsKey(lang) && cpuNote[lang]!.isNotEmpty) {
      return cpuNote[lang]!;
    }

    // Check BIOS item match
    final bios = _biosItems[trimmed];
    if (bios != null && bios.containsKey(lang) && bios[lang]!.isNotEmpty) {
      return bios[lang]!;
    }

    return text;
  }

  /// Convenience methods for specific components
  static String translateKextFunction(String function, {BuildContext? context, String? locale}) =>
      translate(function, context: context, locale: locale);

  static String translateKextNote(String note, {BuildContext? context, String? locale}) =>
      translate(note, context: context, locale: locale);

  static String translateBootArg(String argDescription, {BuildContext? context, String? locale}) =>
      translate(argDescription, context: context, locale: locale);

  static String translateQuirk(String quirkDescription, {BuildContext? context, String? locale}) =>
      translate(quirkDescription, context: context, locale: locale);

  static String translateCpuNote(String cpu, {BuildContext? context, String? locale}) {
    final lang = _resolveLocale(context, locale);
    return _cpuNotes[cpu]?[lang] ?? _cpuNotes[cpu]?['en'] ?? cpu;
  }

  static String translateBiosItem(String item, {BuildContext? context, String? locale}) {
    final lang = _resolveLocale(context, locale);
    return _biosItems[item]?[lang] ?? _biosItems[item]?['en'] ?? item;
  }

  static String translateSmbiosSummary(String model, {BuildContext? context, String? locale}) {
    final lang = _resolveLocale(context, locale);
    return _smbiosSummaries[model]?[lang] ?? _smbiosSummaries[model]?['en'] ?? '';
  }

  static List<String> translateNotes(
    List<String> notes, [
    dynamic contextOrLocale,
  ]) {
    if (contextOrLocale is BuildContext) {
      return notes.map((n) => translate(n, context: contextOrLocale)).toList();
    } else if (contextOrLocale is String) {
      return notes.map((n) => translate(n, locale: contextOrLocale)).toList();
    }
    return notes.map((n) => translate(n)).toList();
  }

  static List<String> translateBiosList(
    List<String> biosList, [
    dynamic contextOrLocale,
  ]) {
    if (contextOrLocale is BuildContext) {
      return biosList.map((b) => translate(b, context: contextOrLocale)).toList();
    } else if (contextOrLocale is String) {
      return biosList.map((b) => translate(b, locale: contextOrLocale)).toList();
    }
    return biosList.map((b) => translate(b)).toList();
  }

  static String translateSmbiosDescription(
    String model, [
    dynamic contextOrLocale,
    dynamic fallback,
  ]) {
    String? locale;
    BuildContext? context;
    if (contextOrLocale is BuildContext) {
      context = contextOrLocale;
    } else if (contextOrLocale is String) {
      locale = contextOrLocale;
    }
    final summary = translateSmbiosSummary(model, context: context, locale: locale);
    if (summary.isNotEmpty) return summary;
    return model;
  }

  static String translateOsVersionSnippet([dynamic contextOrLocale]) {
    if (contextOrLocale is BuildContext) {
      return translate(
        'Selecting the target macOS version ensures compatible Kexts, boot-args, and kernel patches are generated.',
        context: contextOrLocale,
      );
    } else if (contextOrLocale is String) {
      return translate(
        'Selecting the target macOS version ensures compatible Kexts, boot-args, and kernel patches are generated.',
        locale: contextOrLocale,
      );
    }
    return translate(
      'Selecting the target macOS version ensures compatible Kexts, boot-args, and kernel patches are generated.',
    );
  }

