      'ru': '1. Система APFS выполняет TRIM на основе тайм-аута по умолчанию в macOS, что подходит для большинства твердотельных накопителей с поддержкой TRIM.',
      'ja': '1. APFS システムは、ほとんどの TRIM 対応 SSD に適した macOS のデフォルトのタイムアウトに基づいて TRIM を実行します。',
      'ko': '1. APFS 시스템은 대부분의 TRIM 지원 SSD에 적합한 macOS 기본 시간 초과를 기반으로 TRIM을 실행합니다.',
      'it': '1. Il sistema APFS esegue TRIM in base al timeout predefinito di macOS, adatto per la maggior parte degli SSD compatibili con TRIM',
      'tr': '1. APFS sistemi, çoğu TRIM özellikli SSD için uygun olan macOS varsayılan zaman aşımına göre TRIM\'i çalıştırır',
      'vi': '1. Hệ thống APFS thực thi TRIM dựa trên thời gian chờ mặc định của macOS, phù hợp với hầu hết các ổ SSD có khả năng TRIM',
      'pl': '1. System APFS wykonuje TRIM w oparciu o domyślny limit czasu macOS, odpowiedni dla większości dysków SSD obsługujących TRIM',
      'uk': '1. Система APFS виконує TRIM на основі тайм-ауту macOS за замовчуванням, підходить для більшості твердотільних накопичувачів із підтримкою TRIM',
      'nl': '1. APFS-systeem voert TRIM uit op basis van de standaard macOS-time-out, geschikt voor de meeste TRIM-compatibele SSD\'s',
      'hi': '1. APFS प्रणाली macOS डिफ़ॉल्ट टाइमआउट के आधार पर TRIM निष्पादित करती है, जो अधिकांश TRIM-सक्षम SSDs के लिए उपयुक्त है',
      'ar': '1. يقوم نظام APFS بتنفيذ TRIM بناءً على المهلة الافتراضية لنظام التشغيل macOS، وهو مناسب لمعظم محركات أقراص SSD التي تدعم TRIM',
      'id': '1. Sistem APFS menjalankan TRIM berdasarkan batas waktu default macOS, cocok untuk sebagian besar SSD berkemampuan TRIM',
    },
    '1. Improves boot speed for SSDs with buggy TRIM implementations by eliminating TRIM timeout delays at boot': {
      'pt': '1. Melhora a velocidade de inicialização para SSDs com implementações TRIM com bugs, eliminando atrasos de tempo limite do TRIM na inicialização',
      'zh': '1. 通过消除启动时的 TRIM 超时延迟，提高了存在缺陷 TRIM 实现的 SSD 的启动速度',
      'zh_Hant': '1. 透過消除啟動時的 TRIM 逾時延遲，提高了缺陷 TRIM 實現的 SSD 的啟動速度',
      'es': '1. Mejora la velocidad de arranque para SSD con implementaciones TRIM defectuosas al eliminar los retrasos en el tiempo de espera de TRIM en el arranque.',
      'de': '1. Verbessert die Startgeschwindigkeit für SSDs mit fehlerhaften TRIM-Implementierungen durch Eliminierung von TRIM-Timeout-Verzögerungen beim Start',
      'fr': '1. Améliore la vitesse de démarrage des SSD avec des implémentations boguées de TRIM en éliminant les délais d\'expiration de TRIM au démarrage',
      'ru': '1. Улучшает скорость загрузки твердотельных накопителей с ошибочными реализациями TRIM за счет устранения задержек тайм-аута TRIM при загрузке.',
      'ja': '1. 起動時の TRIM タイムアウト遅延を排除することで、バグのある TRIM 実装を備えた SSD の起動速度を向上させます。',
      'ko': '1. 부팅 시 TRIM 시간 초과 지연을 제거하여 버그가 있는 TRIM 구현으로 SSD의 부팅 속도를 향상합니다.',
      'it': '1. Migliora la velocità di avvio per gli SSD con implementazioni TRIM difettose eliminando i ritardi di timeout TRIM all\'avvio',
      'tr': '1. Önyükleme sırasında TRIM zaman aşımı gecikmelerini ortadan kaldırarak hatalı TRIM uygulamalarına sahip SSD\'ler için önyükleme hızını artırır',
      'vi': '1. Cải thiện tốc độ khởi động cho SSD khi triển khai TRIM bị lỗi bằng cách loại bỏ độ trễ thời gian chờ TRIM khi khởi động',
      'pl': '1. Poprawia prędkość rozruchu dysków SSD z błędnymi implementacjami TRIM, eliminując opóźnienia limitu czasu TRIM podczas rozruchu',
      'uk': '1. Покращує швидкість завантаження для твердотільних накопичувачів із помилковими реалізаціями TRIM шляхом усунення затримок очікування TRIM під час завантаження',
      'nl': '1. Verbetert de opstartsnelheid voor SSD\'s met TRIM-implementaties met fouten door TRIM-time-outvertragingen bij het opstarten te elimineren',
      'hi': '1. बूट पर टीआरआईएम टाइमआउट देरी को समाप्त करके खराब टीआरआईएम कार्यान्वयन के साथ एसएसडी के लिए बूट गति में सुधार करता है',
      'ar': '1. يعمل على تحسين سرعة التمهيد لمحركات أقراص SSD مع تطبيقات TRIM التي بها أخطاء عن طريق القضاء على تأخيرات مهلة TRIM عند التمهيد',
      'id': '1. Meningkatkan kecepatan boot untuk SSD dengan implementasi TRIM yang bermasalah dengan menghilangkan penundaan batas waktu TRIM saat boot',
    },
    '1. Slower sustained write performance over time due to lack of block reclamation': {
      'pt': '1. Desempenho de gravação sustentado mais lento ao longo do tempo devido à falta de recuperação de bloco',
      'zh': '1. 由于缺乏块回收，随着时间的推移，持续写入性能会变慢',
      'zh_Hant': '1. 由於缺乏區塊回收，隨著時間的推移，持續寫入效能會變慢',
      'es': '1. Rendimiento de escritura sostenido más lento a lo largo del tiempo debido a la falta de recuperación de bloques',
      'de': '1. Langsamere Schreibleistung im Laufe der Zeit aufgrund fehlender Blockrückgewinnung',
      'fr': '1. Performances d\'écriture soutenues plus lentes au fil du temps en raison du manque de récupération de bloc',
      'ru': '1. Устойчивое снижение производительности записи с течением времени из-за отсутствия восстановления блоков.',
      'ja': '1. ブロック再利用がないため、時間の経過とともに持続的な書き込みパフォーマンスが低下する',
      'ko': '1. 블록 회수 부족으로 인해 시간이 지남에 따라 지속 쓰기 성능이 느려집니다.',
      'it': '1. Prestazioni di scrittura sostenute più lente nel tempo a causa della mancanza di recupero dei blocchi',
      'tr': '1. Blok iyileştirme eksikliği nedeniyle zaman içinde daha yavaş sürekli yazma performansı',
      'vi': '1. Hiệu suất ghi được duy trì chậm hơn theo thời gian do thiếu khả năng khôi phục khối',
      'pl': '1. Niższa, utrzymująca się z biegiem czasu wydajność zapisu z powodu braku odzyskiwania bloków',
      'uk': '1. Повільніша стійка продуктивність запису з часом через відсутність відновлення блоків',
      'nl': '1. Langzamere aanhoudende schrijfprestaties in de loop van de tijd vanwege het ontbreken van blokterugwinning',
      'hi': '1. ब्लॉक पुनर्ग्रहण की कमी के कारण समय के साथ धीमा निरंतर लेखन प्रदर्शन',
      'ar': '1. أداء كتابة أبطأ بشكل مستمر مع مرور الوقت بسبب عدم وجود عملية استعادة الكتل',
      'id': '1. Performa penulisan berkelanjutan yang lebih lambat seiring berjalannya waktu karena kurangnya reklamasi blok',
    },
    '1. Used to fix black screen / no signal issues on Intel 6th~10th Gen iGPUs (where caps lock key responds but display has no signal).\n  2. 500-series desktop motherboards (H510/B560/H570/Q570/Z590/W580) using iGPU HDMI output MUST inject a real display EDID, otherwise black screen often occurs.\n  3. How to obtain display EDID:\n     In Windows, use RapidEFI or hdinfo to acquire display EDID:\n     1). Open RapidEFI, go to "Configure EFI" -> "Auto EFI Config" -> "Details".\n     2). Once hardware scanning completes, click the EDID text next to the display to copy it.\n     3). Return to this page and paste the EDID into the input box below.\n  4. Before injecting EDID, check the AAPL0X port to inject in "Advanced Config".\n  5. EDID data is usually 128 bytes (256 hex chars) or 256 bytes (512 hex chars). Please verify before submitting!': {
      'pt': '1. Usado para corrigir problemas de tela preta/sem sinal em iGPUs Intel de 6ª a 10ª geração (onde a tecla Caps Lock responde, mas a tela não tem sinal).\n  2. Placas-mãe de desktop da série 500 (H510/B560/H570/Q570/Z590/W580) usando saída iGPU HDMI DEVEM injetar um EDID de exibição real, caso contrário, tela preta geralmente ocorre.\n  3. Como obter o EDID de exibição:\n     No Windows, use RapidEFI ou hdinfo para adquirir o EDID do display:\n     1). Abra o RapidEFI, vá em "Configurar EFI" -> "Configuração automática de EFI" -> "Detalhes".\n     2). Assim que a verificação do hardware for concluída, clique no texto EDID próximo ao display para copiá-lo.\n     3). Retorne a esta página e cole o EDID na caixa de entrada abaixo.\n  4. Antes de injetar EDID, verifique a porta AAPL0X para injetar em "Configuração Avançada".\n  5. Os dados EDID geralmente têm 128 bytes (256 caracteres hexadecimais) ou 256 bytes (512 caracteres hexadecimais). Verifique antes de enviar!',
      'zh': '1. 用于修复 Intel 第 6~10 代 iGPU 上的黑屏/无信号问题（大写锁定键有响应但显示屏无信号）。\n  2.使用iGPU HDMI输出的500系列台式机主板（H510/B560/H570/Q570/Z590/W580）必须注入真实的显示EDID，否则经常出现黑屏。\n  3. 如何获取显示器EDID：\n     在Windows中，使用RapidEFI或hdinfo获取显示器EDID：\n     1）。打开RapidEFI，进入“配置EFI”->“自动EFI配置”->“详细信息”。\n     2）。硬件扫描完成后，单击显示屏旁边的 EDID 文本进行复制。\n     3）。返回此页面并将 EDID 粘贴到下面的输入框中。\n  4、注入EDID前，在“Advanced Config”中勾选要注入的AAPL0X端口。\n  5. EDID 数据通常为 128 字节（256 个十六进制字符）或 256 字节（512 个十六进制字符）。提交前请先核实！',
      'zh_Hant': '1. 用於修復 Intel 第 6~10 代 iGPU 上的黑屏/無訊號問題（大寫鎖定鍵有響應但顯示無訊號）。\n  2.使用iGPU HDMI輸出的500系列桌上型電腦主機板（H510/B560/H570/Q570/Z590/W580）必須注入真實的顯示EDID，否則經常出現黑畫面。\n  3. 如何取得顯示器EDID：\n     在Windows中，使用RapidEFI或hdinfo取得顯示器EDID：\n     1）。開啟RapidEFI，進入「配置EFI」->「自動EFI配置」->「詳細資料」。\n     2）。硬體掃描完成後，按一下顯示器旁的 EDID 文字進行複製。\n     3）。返回此頁面並將 EDID 貼到下面的輸入框中。\n  4.注入EDID前，在「Advanced Config」中勾選要注入的AAPL0X埠。\n  5. EDID 資料通常為 128 位元組（256 個十六進位字元）或 256 位元組（512 個十六進位字元）。提交前請先確認！',
      'es': '1. Se utiliza para solucionar problemas de pantalla negra o falta de señal en iGPU Intel de 6.ª a 10.ª generación (donde la tecla de bloqueo de mayúsculas responde pero la pantalla no tiene señal).\n  2. Las placas base de escritorio de la serie 500 (H510/B560/H570/Q570/Z590/W580) que utilizan salida HDMI iGPU DEBEN inyectar una pantalla EDID real; de lo contrario, a menudo aparece una pantalla negra.\n  3. Cómo obtener el EDID de visualización:\n     En Windows, utilice RapidEFI o hdinfo para adquirir el EDID de pantalla:\n     1). Abra RapidEFI, vaya a "Configurar EFI" -> "Configuración automática de EFI" -> "Detalles".\n     2). Una vez que se complete el escaneo de hardware, haga clic en el texto EDID al lado de la pantalla para copiarlo.\n     3). Regrese a esta página y pegue el EDID en el cuadro de entrada a continuación.\n  4. Antes de inyectar EDID, verifique el puerto AAPL0X para inyectar en "Configuración avanzada".\n  5. Los datos EDID suelen tener 128 bytes (256 caracteres hexadecimales) o 256 bytes (512 caracteres hexadecimales). ¡Por favor verifique antes de enviar!',
      'de': '1. Wird zur Behebung von Problemen mit schwarzem Bildschirm oder fehlendem Signal auf Intel iGPUs der 6. bis 10. Generation verwendet (bei denen die Feststelltaste reagiert, das Display jedoch kein Signal hat).\n  2. Desktop-Motherboards der 500er-Serie (H510/B560/H570/Q570/Z590/W580) mit iGPU-HDMI-Ausgang MÜSSEN eine echte Display-EDID einspeisen, da sonst häufig ein schwarzer Bildschirm auftritt.\n  3. So erhalten Sie die EDID für die Anzeige:\n     Verwenden Sie unter Windows RapidEFI oder hdinfo, um die Anzeige-EDID abzurufen:\n     1). Öffnen Sie RapidEFI, gehen Sie zu „EFI konfigurieren“ -> „Auto EFI Config“ -> „Details“.\n     2). Sobald der Hardware-Scan abgeschlossen ist, klicken Sie auf den EDID-Text neben der Anzeige, um ihn zu kopieren.\n     3). Kehren Sie zu dieser Seite zurück und fügen Sie die EDID in das Eingabefeld unten ein.\n  4. Bevor Sie EDID einfügen, überprüfen Sie den AAPL0X-Port, der in „Erweiterte Konfiguration“ eingefügt werden soll.\n  5. EDID-Daten sind normalerweise 128 Byte (256 Hex-Zeichen) oder 256 Byte (512 Hex-Zeichen) groß. Bitte vor dem Absenden überprüfen!',
      'fr': '1. Utilisé pour résoudre les problèmes d\'écran noir/absence de signal sur les iGPU Intel de 6e à 10e génération (où la touche de verrouillage des majuscules répond mais l\'affichage n\'a aucun signal).\n  2. Les cartes mères de bureau de la série 500 (H510/B560/H570/Q570/Z590/W580) utilisant la sortie HDMI iGPU DOIVENT injecter un véritable affichage EDID, sinon un écran noir se produit souvent.\n  3. Comment obtenir l\'affichage EDID :\n     Sous Windows, utilisez RapidEFI ou hdinfo pour acquérir l\'affichage EDID :\n     1). Ouvrez RapidEFI, allez dans « Configurer EFI » -> « Auto EFI Config » -> « Détails ».\n     2). Une fois l\'analyse du matériel terminée, cliquez sur le texte EDID à côté de l\'écran pour le copier.\n     3). Revenez à cette page et collez l\'EDID dans la zone de saisie ci-dessous.\n  4. Avant d\'injecter EDID, vérifiez le port AAPL0X à injecter dans « Advanced Config ».\n  5. Les données EDID font généralement 128 octets (256 caractères hexadécimaux) ou 256 octets (512 caractères hexadécimaux). Veuillez vérifier avant de soumettre !',
      'ru': '1. Используется для устранения проблем с черным экраном или отсутствием сигнала на iGPU Intel 6-10-го поколения (когда клавиша блокировки верхнего регистра реагирует, но на дисплее нет сигнала).\n  2. Материнские платы серии 500 для настольных ПК (H510/B560/H570/Q570/Z590/W580), использующие выход HDMI iGPU, ДОЛЖНЫ вводить реальный EDID дисплея, в противном случае часто возникает черный экран.\n  3. Как получить EDID дисплея:\n     В Windows используйте RapidEFI или hdinfo для получения EDID дисплея:\n     1). Откройте RapidEFI, перейдите в «Настроить EFI» -> «Автоматическая настройка EFI» -> «Подробнее».\n     2). После завершения сканирования оборудования щелкните текст EDID рядом с дисплеем, чтобы скопировать его.\n     3). Вернитесь на эту страницу и вставьте EDID в поле ввода ниже.\n  4. Прежде чем вводить EDID, проверьте порт AAPL0X для добавления в «Расширенную конфигурацию».\n  5. Данные EDID обычно имеют размер 128 байт (256 шестнадцатеричных символов) или 256 байтов (512 шестнадцатеричных символов). Пожалуйста, проверьте перед отправкой!',
      'ja': '1. Intel 第 6 ～ 10 世代 iGPU での黒い画面/信号なしの問題 (Caps Lock キーは反応するが、ディスプレイに信号がない場合) を修正するために使用されます。\n  2. iGPU HDMI 出力を使用する 500 シリーズ デスクトップ マザーボード (H510/B560/H570/Q570/Z590/W580) は実際のディスプレイ EDID を挿入する必要があります。挿入しないと黒い画面が頻繁に発生します。\n  3. ディスプレイ EDID の取得方法:\n     Windows では、RapidEFI または hdinfo を使用してディスプレイ EDID を取得します。\n     1)。 RapidEFIを開き、「EFIの構成」→「自動EFI構成」→「詳細」に進みます。\n     2)。ハードウェアのスキャンが完了したら、ディスプレイの横にある EDID テキストをクリックしてコピーします。\n     3)。このページに戻り、下の入力ボックスに EDID を貼り付けます。\n  4. EDIDを導入する前に、「Advanced Config」で導入するAAPL0Xポートを確認してください。\n  5. EDID データは通常、128 バイト (256 の 16 進文字) または 256 バイト (512 の 16 進文字) です。送信する前に必ずご確認ください。',
      'ko': '1. Intel 6~10세대 iGPU(Caps Lock 키는 반응하지만 디스플레이에 신호가 없는 경우)의 검은색 화면/신호 없음 문제를 해결하는 데 사용됩니다.\n  2. iGPU HDMI 출력을 사용하는 500 시리즈 데스크탑 마더보드(H510/B560/H570/Q570/Z590/W580)는 실제 디스플레이 EDID를 삽입해야 합니다. 그렇지 않으면 검은색 화면이 자주 발생합니다.\n  3. 디스플레이 EDID를 얻는 방법:\n     Windows에서는 RapidEFI 또는 hdinfo를 사용하여 디스플레이 EDID를 획득합니다.\n     1). RapidEFI를 열고 "EFI 구성" -> "자동 EFI 구성" -> "세부 정보"로 이동합니다.\n     2). 하드웨어 검색이 완료되면 디스플레이 옆에 있는 EDID 텍스트를 클릭하여 복사하세요.\n     3). 이 페이지로 돌아와서 아래 입력 상자에 EDID를 붙여넣습니다.\n  4. EDID를 삽입하기 전, "Advanced Config"에서 삽입할 AAPL0X 포트를 확인하세요.\n  5. EDID 데이터는 일반적으로 128바이트(256개의 16진수 문자) 또는 256바이트(512개의 16진수 문자)입니다. 제출 전 꼭 확인해주세요!',
      'it': '1. Utilizzato per risolvere problemi di schermata nera/assenza di segnale sulle iGPU Intel di sesta e decima generazione (dove il tasto BLOC MAIUSC risponde ma il display non ha segnale).\n  2. Le schede madri desktop serie 500 (H510/B560/H570/Q570/Z590/W580) che utilizzano l\'uscita HDMI iGPU DEVONO inserire un EDID del display reale, altrimenti spesso si verifica una schermata nera.\n  3. Come ottenere l\'EDID di visualizzazione:\n     In Windows, utilizza RapidEFI o hdinfo per acquisire l\'EDID di visualizzazione:\n     1). Apri RapidEFI, vai su "Configura EFI" -> "Auto EFI Config" -> "Dettagli".\n     2). Una volta completata la scansione dell\'hardware, fare clic sul testo EDID accanto al display per copiarlo.\n     3). Torna a questa pagina e incolla l\'EDID nella casella di input sottostante.\n  4. Prima di inserire EDID, controllare la porta AAPL0X da inserire in "Configurazione avanzata".\n  5. I dati EDID sono generalmente di 128 byte (256 caratteri esadecimali) o 256 byte (512 caratteri esadecimali). Si prega di verificare prima di inviare!',
      'tr': '1. Intel 6.~10. Nesil iGPU\'larda (büyük harf kilidi tuşunun yanıt verdiği ancak ekranda sinyal olmadığı) siyah ekran / sinyal yok sorunlarını düzeltmek için kullanılır.\n  2. iGPU HDMI çıkışı kullanan 500 serisi masaüstü anakartların (H510/B560/H570/Q570/Z590/W580) gerçek bir ekran EDID\'si enjekte etmesi GEREKLİdir, aksi takdirde sıklıkla siyah ekran oluşur.\n  3. Ekran EDID\'si nasıl elde edilir:\n     Windows\'ta, ekran EDID\'sini almak için RapidEFI veya hdinfo\'yu kullanın:\n     1). RapidEFI\'yi açın, "EFI\'yi Yapılandır" -> "Otomatik EFI Yapılandırması" -> "Ayrıntılar" seçeneğine gidin.\n     2). Donanım taraması tamamlandığında kopyalamak için ekranın yanındaki EDID metnine tıklayın.\n     3). Bu sayfaya dönün ve EDID\'yi aşağıdaki giriş kutusuna yapıştırın.\n  4. EDID\'yi enjekte etmeden önce, "Gelişmiş Yapılandırma"ya enjekte etmek için AAPL0X bağlantı noktasını kontrol edin.\n  5. EDID verileri genellikle 128 bayt (256 hex karakter) veya 256 bayttır (512 hex karakter). Lütfen göndermeden önce doğrulayın!',
      'vi': '1. Được sử dụng để khắc phục sự cố màn hình đen/không có tín hiệu trên iGPU Intel thế hệ thứ 6~10 (trong đó phím Caps Lock phản hồi nhưng màn hình không có tín hiệu).\n  2. Bo mạch chủ máy tính để bàn dòng 500 (H510/B560/H570/Q570/Z590/W580) sử dụng đầu ra HDMI iGPU PHẢI đưa EDID màn hình thực, nếu không, màn hình đen thường xảy ra.\n  3. Cách lấy EDID hiển thị:\n     Trong Windows, sử dụng RapidEFI hoặc hdinfo để thu được EDID hiển thị:\n     1). Mở RapidEFI, đi tới "Định cấu hình EFI" -> "Cấu hình EFI tự động" -> "Chi tiết".\n     2). Sau khi quá trình quét phần cứng hoàn tất, hãy nhấp vào văn bản EDID bên cạnh màn hình để sao chép nó.\n     3). Quay lại trang này và dán EDID vào hộp nhập bên dưới.\n  4. Trước khi đưa EDID vào, hãy kiểm tra cổng AAPL0X để đưa vào "Cấu hình nâng cao".\n  5. Dữ liệu EDID thường là 128 byte (256 ký tự hex) hoặc 256 byte (512 ký tự hex). Vui lòng xác minh trước khi gửi!',
      'pl': '1. Służy do rozwiązywania problemów z czarnym ekranem/brakiem sygnału w procesorach iGPU Intel 6.–10. generacji (gdzie klawisz Caps Lock reaguje, ale wyświetlacz nie ma sygnału).\n  2. Płyty główne do komputerów stacjonarnych z serii 500 (H510/B560/H570/Q570/Z590/W580) korzystające z wyjścia iGPU HDMI MUSZĄ wprowadzić prawdziwy kod EDID wyświetlacza, w przeciwnym razie często pojawia się czarny ekran.\n  3. Jak uzyskać wyświetlacz EDID:\n     W systemie Windows użyj RapidEFI lub hdinfo, aby uzyskać identyfikator EDID wyświetlacza:\n     1). Otwórz RapidEFI, przejdź do „Konfiguruj EFI” -> „Automatyczna konfiguracja EFI” -> „Szczegóły”.\n     2). Po zakończeniu skanowania sprzętu kliknij tekst EDID obok wyświetlacza, aby go skopiować.\n     3). Wróć na tę stronę i wklej EDID w polu wejściowym poniżej.\n  4. Przed wstrzyknięciem EDID sprawdź port AAPL0X do wstrzyknięcia w „Advanced Config”.\n  5. Dane EDID mają zwykle 128 bajtów (256 znaków szesnastkowych) lub 256 bajtów (512 znaków szesnastkowych). Sprawdź przed przesłaniem!',
      'uk': '1. Використовується для усунення проблем із чорним екраном/відсутністю сигналу на графічних процесорах Intel 6-10 поколінь (де реагує клавіша Caps Lock, але на дисплеї немає сигналу).\n  2. Материнські плати серії 500 для настільних комп’ютерів (H510/B560/H570/Q570/Z590/W580), що використовують вихід HDMI iGPU, ПОВИННІ вводити реальний EDID дисплея, інакше часто виникає чорний екран.\n  3. Як отримати дисплей EDID:\n     У Windows використовуйте RapidEFI або hdinfo, щоб отримати EDID дисплея:\n     1). Відкрийте RapidEFI, перейдіть до «Налаштувати EFI» -> «Автоматична конфігурація EFI» -> «Деталі».\n     2). Після завершення сканування апаратного забезпечення натисніть текст EDID поруч із дисплеєм, щоб скопіювати його.\n     3). Поверніться на цю сторінку та вставте EDID у поле введення нижче.\n  4. Перед введенням EDID перевірте порт AAPL0X для введення в «Advanced Config».\n  5. Дані EDID зазвичай складають 128 байт (256 шістнадцяткових символів) або 256 байт (512 шістнадцяткових символів). Перевірте перед надсиланням!',
      'nl': '1. Wordt gebruikt om problemen met een zwart scherm/geen signaal op te lossen op Intel 6e-10e generatie iGPU\'s (waarbij de Caps Lock-toets reageert maar het scherm geen signaal heeft).\n  2. Desktop-moederborden uit de 500-serie (H510/B560/H570/Q570/Z590/W580) die gebruikmaken van iGPU HDMI-uitgang MOETEN een echte display-EDID injecteren, anders ontstaat er vaak een zwart scherm.\n  3. Zo verkrijgt u een EDID-weergave:\n     Gebruik in Windows RapidEFI of hdinfo om display-EDID te verkrijgen:\n     1). Open RapidEFI, ga naar "EFI configureren" -> "Auto EFI Config" -> "Details".\n     2). Zodra het scannen van de hardware is voltooid, klikt u op de EDID-tekst naast het scherm om deze te kopiëren.\n     3). Keer terug naar deze pagina en plak de EDID in het onderstaande invoervak.\n  4. Controleer voordat u EDID injecteert de AAPL0X-poort om te injecteren in "Advanced Config".\n  5. EDID-gegevens zijn gewoonlijk 128 bytes (256 hexadecimale tekens) of 256 bytes (512 hexadecimale tekens). Controleer dit voordat u het verzendt!',
      'hi': '1. Intel 6th~10th Gen iGPUs (जहां कैप्स लॉक कुंजी प्रतिक्रिया करता है लेकिन डिस्प्ले में कोई सिग्नल नहीं होता है) पर काली स्क्रीन/कोई सिग्नल की समस्या को ठीक करने के लिए उपयोग किया जाता है।\n  2. 500-श्रृंखला डेस्कटॉप मदरबोर्ड (H510/B560/H570/Q570/Z590/W580) iGPU HDMI आउटपुट का उपयोग करके एक वास्तविक डिस्प्ले EDID इंजेक्ट करना होगा, अन्यथा अक्सर काली स्क्रीन होती है।\n  3. डिस्प्ले ईडीआईडी कैसे प्राप्त करें:\n     विंडोज़ में, डिस्प्ले EDID प्राप्त करने के लिए RapidEFI या hdinfo का उपयोग करें:\n     1). रैपिडईएफआई खोलें, "कॉन्फिगर ईएफआई" -> "ऑटो ईएफआई कॉन्फिग" -> "विवरण" पर जाएं।\n     2). एक बार हार्डवेयर स्कैनिंग पूरी हो जाने पर, इसे कॉपी करने के लिए डिस्प्ले के बगल में EDID टेक्स्ट पर क्लिक करें।\n     3). इस पृष्ठ पर वापस लौटें और ईडीआईडी ​​को नीचे इनपुट बॉक्स में पेस्ट करें।\n  4. EDID इंजेक्ट करने से पहले, "उन्नत कॉन्फ़िगरेशन" में इंजेक्ट करने के लिए AAPL0X पोर्ट की जाँच करें।\n  5. EDID डेटा आमतौर पर 128 बाइट्स (256 हेक्स वर्ण) या 256 बाइट्स (512 हेक्स वर्ण) होता है। कृपया सबमिट करने से पहले सत्यापित करें!',
      'ar': '1. يستخدم لإصلاح الشاشة السوداء / عدم وجود مشكلات في الإشارة على وحدات معالجة الرسوميات Intel من الجيل السادس إلى العاشر (حيث يستجيب مفتاح caps lock ولكن لا تحتوي الشاشة على إشارة).\n  2. يجب أن تقوم اللوحات الأم لسطح المكتب من سلسلة 500 (H510/B560/H570/Q570/Z590/W580) باستخدام مخرج iGPU HDMI بإدخال شاشة EDID حقيقية، وإلا فغالبًا ما تحدث شاشة سوداء.\n  3. كيفية الحصول على EDID للعرض:\n     في نظام التشغيل Windows، استخدم RapidEFI أو hdinfo للحصول على EDID للعرض:\n     1). افتح RapidEFI، وانتقل إلى "تكوين EFI" -> "تكوين EFI التلقائي" -> "التفاصيل".\n     2). بمجرد اكتمال فحص الأجهزة، انقر فوق نص EDID بجوار الشاشة لنسخه.\n     3). ارجع إلى هذه الصفحة والصق EDID في مربع الإدخال أدناه.\n  4. قبل حقن EDID، تحقق من منفذ AAPL0X للحقن في "التكوين المتقدم".\n  5. عادةً ما تكون بيانات EDID 128 بايت (256 حرفًا سداسيًا عشريًا) أو 256 بايت (512 حرفًا سداسيًا عشريًا). يرجى التحقق قبل التقديم!',
      'id': '1. Digunakan untuk memperbaiki masalah layar hitam / tidak ada sinyal pada iGPU Intel Generasi ke-6~10 (di mana tombol caps lock merespons tetapi tampilan tidak memiliki sinyal).\n  2. Motherboard desktop seri 500 (H510/B560/H570/Q570/Z590/W580) yang menggunakan output iGPU HDMI HARUS memasukkan EDID tampilan nyata, jika tidak, layar hitam sering terjadi.\n  3. Cara mendapatkan tampilan EDID:\n     Di Windows, gunakan RapidEFI atau hdinfo untuk memperoleh tampilan EDID:\n     1). Buka RapidEFI, buka "Konfigurasi EFI" -> "Konfigurasi EFI Otomatis" -> "Detail".\n     2). Setelah pemindaian perangkat keras selesai, klik teks EDID di sebelah layar untuk menyalinnya.\n     3). Kembali ke halaman ini dan tempel EDID ke kotak masukan di bawah.\n  4. Sebelum menginjeksi EDID, periksa port AAPL0X yang akan diinjeksi di "Advanced Config".\n  5. Data EDID biasanya 128 byte (256 hex chars) atau 256 byte (512 hex chars). Harap verifikasi sebelum mengirimkan!',
    },
