    },
    '2. On TRIM-capable SSDs, macOS automatically manages TRIM to clean deleted blocks and improve write efficiency': {
      'pt': '2. Em SSDs compatíveis com TRIM, o macOS gerencia automaticamente o TRIM para limpar blocos excluídos e melhorar a eficiência de gravação',
      'zh': '2. 在支持 TRIM 的 SSD 上，macOS 自动管理 TRIM 以清理已删除的块并提高写入效率',
      'zh_Hant': '2. 在支援 TRIM 的 SSD 上，macOS 會自動管理 TRIM 以清理已刪除的區塊並提高寫入效率',
      'es': '2. En SSD compatibles con TRIM, macOS administra automáticamente TRIM para limpiar bloques eliminados y mejorar la eficiencia de escritura',
      'de': '2. Auf TRIM-fähigen SSDs verwaltet macOS TRIM automatisch, um gelöschte Blöcke zu bereinigen und die Schreibeffizienz zu verbessern',
      'fr': '2. Sur les SSD compatibles TRIM, macOS gère automatiquement TRIM pour nettoyer les blocs supprimés et améliorer l\'efficacité d\'écriture.',
      'ru': '2. На твердотельных накопителях с поддержкой TRIM macOS автоматически управляет TRIM для очистки удаленных блоков и повышения эффективности записи.',
      'ja': '2. TRIM 対応 SSD では、macOS が TRIM を自動的に管理して、削除されたブロックをクリーンアップし、書き込み効率を向上させます。',
      'ko': '2. TRIM 지원 SSD에서 macOS는 TRIM을 자동으로 관리하여 삭제된 블록을 정리하고 쓰기 효율성을 향상시킵니다.',
      'it': '2. Sugli SSD compatibili con TRIM, macOS gestisce automaticamente TRIM per pulire i blocchi eliminati e migliorare l\'efficienza di scrittura',
      'tr': '2. TRIM özellikli SSD\'lerde macOS, silinen blokları temizlemek ve yazma verimliliğini artırmak için TRIM\'i otomatik olarak yönetir',
      'vi': '2. Trên các ổ SSD hỗ trợ TRIM, macOS tự động quản lý TRIM để xóa các khối đã xóa và cải thiện hiệu quả ghi',
      'pl': '2. Na dyskach SSD obsługujących TRIM macOS automatycznie zarządza TRIM, aby wyczyścić usunięte bloki i poprawić wydajność zapisu',
      'uk': '2. На твердотільних накопичувачах із підтримкою TRIM macOS автоматично керує TRIM для очищення видалених блоків і підвищення ефективності запису',
      'nl': '2. Op TRIM-compatibele SSD\'s beheert macOS automatisch TRIM om verwijderde blokken op te schonen en de schrijfefficiëntie te verbeteren',
      'hi': '2. TRIM-सक्षम SSDs पर, macOS हटाए गए ब्लॉकों को साफ़ करने और लेखन दक्षता में सुधार करने के लिए स्वचालित रूप से TRIM का प्रबंधन करता है',
      'ar': '2. في محركات أقراص SSD التي تدعم TRIM، يقوم macOS تلقائيًا بإدارة TRIM لتنظيف الكتل المحذوفة وتحسين كفاءة الكتابة',
      'id': '2. Pada SSD berkemampuan TRIM, macOS secara otomatis mengelola TRIM untuk membersihkan blok yang terhapus dan meningkatkan efisiensi penulisan',
    },
    '2. SSD controller requires more background overhead for garbage collection': {
      'pt': '2. O controlador SSD requer mais sobrecarga de fundo para coleta de lixo',
      'zh': '2. SSD控制器需要更多的后台开销来进行垃圾收集',
      'zh_Hant': '2. SSD控制器需要更多的後台開銷來進行垃圾收集',
      'es': '2. El controlador SSD requiere más sobrecarga en segundo plano para la recolección de basura',
      'de': '2. Der SSD-Controller erfordert mehr Hintergrundaufwand für die Speicherbereinigung',
      'fr': '2. Le contrôleur SSD nécessite plus de temps système en arrière-plan pour le garbage collection',
