    '3. Extends lifespan on non-TRIM SSDs where forcing TRIM causes premature wear': {
      'pt': '3. Prolonga a vida útil de SSDs não TRIM, onde forçar o TRIM causa desgaste prematuro',
      'zh': '3. 延长非 TRIM SSD 的使用寿命，因为强制 TRIM 会导致过早磨损',
      'zh_Hant': '3. 延長非 TRIM SSD 的使用壽命，因為強制 TRIM 會導致過早磨損',
      'es': '3. Extiende la vida útil de los SSD que no son TRIM donde forzar TRIM provoca un desgaste prematuro',
      'de': '3. Verlängert die Lebensdauer von Nicht-TRIM-SSDs, bei denen das Erzwingen von TRIM zu vorzeitigem Verschleiß führt',
      'fr': '3. Prolonge la durée de vie des SSD non-TRIM où forcer TRIM provoque une usure prématurée',
      'ru': '3. Продлевает срок службы твердотельных накопителей без TRIM, где принудительное использование TRIM приводит к преждевременному износу.',
      'ja': '3. TRIM を強制すると早期摩耗が発生する非 TRIM SSD の寿命を延ばします。',
      'ko': '3. TRIM을 강제로 적용하면 조기 마모가 발생하는 비 TRIM SSD의 수명이 연장됩니다.',
      'it': '3. Estende la durata degli SSD non TRIM dove forzare il TRIM provoca un\'usura prematura',
      'tr': '3. TRIM\'i zorlamanın erken aşınmaya neden olduğu TRIM olmayan SSD\'lerin ömrünü uzatır',
      'vi': '3. Kéo dài tuổi thọ trên các ổ SSD không phải TRIM trong đó việc buộc TRIM gây ra tình trạng hao mòn sớm',
      'pl': '3. Wydłuża żywotność dysków SSD innych niż TRIM, gdzie wymuszanie TRIM powoduje przedwczesne zużycie',
      'uk': '3. Подовжує термін служби SSD без TRIM, де примусове використання TRIM спричиняє передчасний знос',
      'nl': '3. Verlengt de levensduur van niet-TRIM SSD\'s waarbij het forceren van TRIM voortijdige slijtage veroorzaakt',
      'hi': '3. गैर-टीआरआईएम एसएसडी पर जीवनकाल बढ़ाता है जहां टीआरआईएम को मजबूर करने से समय से पहले घिसाव होता है',
      'ar': '3. يطيل عمر محركات أقراص SSD غير TRIM حيث يؤدي فرض TRIM إلى التآكل المبكر',
      'id': '3. Memperpanjang masa pakai SSD non-TRIM yang memaksa TRIM menyebabkan keausan dini',
    },
    '3. Increases write amplification on TRIM-supported SSDs': {
      'pt': '3. Aumenta a amplificação de gravação em SSDs com suporte para TRIM',
      'zh': '3. 增加支持 TRIM 的 SSD 的写入放大',
      'zh_Hant': '3. 增加支援 TRIM 的 SSD 的寫入放大',
      'es': '3. Aumenta la amplificación de escritura en SSD compatibles con TRIM',
      'de': '3. Erhöht die Schreibverstärkung auf TRIM-unterstützten SSDs',
      'fr': '3. Augmente l\'amplification d\'écriture sur les SSD pris en charge par TRIM',
      'ru': '3. Увеличивает усиление записи на твердотельных накопителях с поддержкой TRIM.',
      'ja': '3. TRIM 対応 SSD での書き込み増幅を増加します。',
      'ko': '3. TRIM 지원 SSD의 쓰기 증폭 증가',
      'it': '3. Aumenta l\'amplificazione della scrittura sugli SSD supportati da TRIM',
      'tr': '3. TRIM destekli SSD\'lerde yazma amplifikasyonunu artırır',
      'vi': '3. Tăng khả năng khuếch đại ghi trên ổ SSD hỗ trợ TRIM',
      'pl': '3. Zwiększa wzmocnienie zapisu na dyskach SSD obsługiwanych przez TRIM',
      'uk': '3. Збільшує швидкість запису на твердотільних накопичувачах із підтримкою TRIM',
      'nl': '3. Verhoogt de schrijfversterking op TRIM-ondersteunde SSD\'s',
      'hi': '3. TRIM-समर्थित SSDs पर लेखन प्रवर्धन बढ़ाता है',
      'ar': '3. يزيد من تضخيم الكتابة على محركات أقراص SSD المدعومة بـ TRIM',
      'id': '3. Meningkatkan amplifikasi tulis pada SSD yang didukung TRIM',
    },
    '3. TRIM periodically clears unused blocks to reduce SSD wear and extend lifespan': {
      'pt': '3. O TRIM limpa periodicamente os blocos não utilizados para reduzir o desgaste do SSD e prolongar a vida útil',
      'zh': '3. TRIM定期清除未使用的块，以减少SSD磨损并延长使用寿命',
      'zh_Hant': '3. TRIM定期清除未使用的塊，以減少SSD磨損並延長使用壽命',
      'es': '3. TRIM limpia periódicamente los bloques no utilizados para reducir el desgaste de la SSD y prolongar su vida útil',
      'de': '3. TRIM löscht regelmäßig ungenutzte Blöcke, um den SSD-Verschleiß zu reduzieren und die Lebensdauer zu verlängern',
      'fr': '3. TRIM efface périodiquement les blocs inutilisés pour réduire l\'usure du SSD et prolonger la durée de vie',
      'ru': '3. TRIM периодически очищает неиспользуемые блоки, чтобы уменьшить износ SSD и продлить срок службы.',
      'ja': '3. TRIM は未使用のブロックを定期的にクリアして、SSD の磨耗を軽減し、寿命を延ばします。',
      'ko': '3. TRIM은 사용하지 않는 블록을 주기적으로 지워 SSD 마모를 줄이고 수명을 연장합니다.',
      'it': '3. TRIM cancella periodicamente i blocchi inutilizzati per ridurre l\'usura dell\'SSD e prolungarne la durata',
      'tr': '3. TRIM, SSD aşınmasını azaltmak ve kullanım ömrünü uzatmak için kullanılmayan blokları periyodik olarak temizler',
      'vi': '3. TRIM định kỳ xóa các khối không sử dụng để giảm hao mòn SSD và kéo dài tuổi thọ',
      'pl': '3. TRIM okresowo usuwa nieużywane bloki, aby zmniejszyć zużycie dysku SSD i wydłużyć jego żywotność',
      'uk': '3. TRIM періодично очищає невикористані блоки, щоб зменшити знос SSD і подовжити термін служби',
      'nl': '3. TRIM ruimt periodiek ongebruikte blokken op om SSD-slijtage te verminderen en de levensduur te verlengen',
      'hi': '3. TRIM समय-समय पर SSD की टूट-फूट को कम करने और जीवनकाल बढ़ाने के लिए अप्रयुक्त ब्लॉकों को साफ करता है',
      'ar': '3. يقوم TRIM بمسح الكتل غير المستخدمة بشكل دوري لتقليل تآكل SSD وإطالة العمر الافتراضي',
      'id': '3. TRIM secara berkala membersihkan blok yang tidak digunakan untuk mengurangi keausan SSD dan memperpanjang masa pakai',
    },
