    '4. Some third-party SSDs without full TRIM support may experience boot delays or stalls during TRIM': {
      'pt': '4. Alguns SSDs de terceiros sem suporte total ao TRIM podem sofrer atrasos na inicialização ou travamentos durante o TRIM',
      'zh': '4. 某些不完全支持 TRIM 的第三方 SSD 在 TRIM 期间可能会遇到启动延迟或停止的情况',
      'zh_Hant': '4. 某些不完全支援 TRIM 的第三方 SSD 在 TRIM 期間可能會遇到啟動延遲或停止的情況',
      'es': '4. Algunos SSD de terceros sin compatibilidad total con TRIM pueden experimentar retrasos en el arranque o bloqueos durante TRIM',
      'de': '4. Bei einigen SSDs von Drittanbietern ohne vollständige TRIM-Unterstützung kann es während TRIM zu Startverzögerungen oder Abstürzen kommen',
