      'ru': '4. Некоторые твердотельные накопители сторонних производителей без полной поддержки TRIM могут испытывать задержки при загрузке или зависания во время TRIM.',
      'ja': '4. TRIM を完全にサポートしていない一部のサードパーティ製 SSD では、TRIM 中に起動の遅延や停止が発生する場合があります。',
      'ko': '4. TRIM을 완벽하게 지원하지 않는 일부 타사 SSD에서는 TRIM 중에 부팅 지연이나 정지가 발생할 수 있습니다.',
      'it': '4. Alcuni SSD di terze parti senza supporto TRIM completo potrebbero riscontrare ritardi o blocchi di avvio durante TRIM',
      'tr': '4. Tam TRIM desteği olmayan bazı üçüncü taraf SSD\'lerde, TRIM sırasında önyükleme gecikmeleri veya takılmalar yaşanabilir',
      'vi': '4. Một số ổ SSD của bên thứ ba không hỗ trợ TRIM đầy đủ có thể gặp phải tình trạng khởi động chậm hoặc ngừng hoạt động trong TRIM',
      'pl': '4. W przypadku niektórych dysków SSD innych firm bez pełnej obsługi TRIM mogą wystąpić opóźnienia w rozruchu lub przestoje podczas TRIM',
      'uk': '4. Деякі SSD сторонніх виробників без повної підтримки TRIM можуть мати затримки завантаження або зупинки під час TRIM',
      'nl': '4. Bij sommige SSD\'s van derden zonder volledige TRIM-ondersteuning kunnen tijdens TRIM opstartvertragingen optreden of vastlopen',
      'hi': '4. पूर्ण TRIM समर्थन के बिना कुछ तृतीय-पक्ष SSDs TRIM के दौरान बूट विलंब या रुकावट का अनुभव कर सकते हैं',
      'ar': '4. قد تواجه بعض محركات أقراص SSD التابعة لجهات خارجية دون دعم TRIM الكامل تأخيرات في التمهيد أو توقفًا أثناء TRIM',
      'id': '4. Beberapa SSD pihak ketiga tanpa dukungan penuh TRIM mungkin mengalami penundaan booting atau terhenti selama TRIM',
