    'AMD dGPU Spoofing (Device Properties):\n   1. Enter the dGPU PCI Path, e.g.: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Enter the spoofed Device ID (4 hex chars), e.g.: 73BF\n   3. Ensure appropriate boot-args are enabled (in dGPU Configuration -> AMD dGPU as needed)\n   4. The tool includes built-in presets for common spoofed AMD GPUs': {
      'pt': 'Falsificação de AMD dGPU (Propriedades do dispositivo):\n   1. Insira o caminho PCI dGPU, por exemplo: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Insira o ID do dispositivo falsificado (4 caracteres hexadecimais), por exemplo: 73BF\n   3. Certifique-se de que os argumentos de inicialização apropriados estejam habilitados (na configuração dGPU -> AMD dGPU conforme necessário)\n   4. A ferramenta inclui predefinições integradas para GPUs AMD falsificadas comuns',
      'zh': 'AMD dGPU 欺骗（设备属性）：\n   1. 输入 dGPU PCI 路径，例如：PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. 输入欺骗性设备 ID（4 个十六进制字符），例如：73BF\n   3. 确保启用适当的启动参数（根据需要在 dGPU 配置 -> AMD dGPU 中）\n   4. 该工具包含针对常见欺骗性 AMD GPU 的内置预设',
      'zh_Hant': 'AMD dGPU 欺骗（设备属性）：\n   1. 輸入 dGPU PCI 路徑，例如：PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. 輸入欺騙性設備 ID（4 個十六進位字元），例如：73BF\n   3. 確保啟用適當的啟動參數（根據需要在 dGPU 配置 -> AMD dGPU 中）\n   4. 此工具包含針對常見欺騙性 AMD GPU 的內建預設',
      'es': 'Suplantación de AMD dGPU (propiedades del dispositivo):\n   1. Ingrese la ruta PCI de la dGPU, por ejemplo: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Ingrese el ID del dispositivo falsificado (4 caracteres hexadecimales), por ejemplo: 73BF\n   3. Asegúrese de que los argumentos de arranque adecuados estén habilitados (en Configuración de dGPU -> AMD dGPU según sea necesario)\n   4. La herramienta incluye ajustes preestablecidos integrados para GPU AMD falsificadas comunes.',
      'de': 'AMD dGPU-Spoofing (Geräteeigenschaften):\n   1. Geben Sie den dGPU-PCI-Pfad ein, z. B.: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Geben Sie die gefälschte Geräte-ID (4 Hexadezimalzeichen) ein, z. B.: 73BF\n   3. Stellen Sie sicher, dass die entsprechenden Boot-Argumente aktiviert sind (in der dGPU-Konfiguration -> AMD dGPU nach Bedarf).\n   4. Das Tool enthält integrierte Voreinstellungen für gängige gefälschte AMD-GPUs',
      'fr': 'Usurpation d\'AMD dGPU (propriétés de l\'appareil) :\n   1. Entrez le chemin PCI du dGPU, par exemple : PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Entrez l\'ID de l\'appareil usurpé (4 caractères hexadécimaux), par exemple : 73BF\n   3. Assurez-vous que les arguments de démarrage appropriés sont activés (dans Configuration dGPU -> AMD dGPU si nécessaire)\n   4. L\'outil comprend des préréglages intégrés pour les GPU AMD usurpés courants',
      'ru': 'Подмена AMD dGPU (свойства устройства):\n   1. Введите путь PCI dGPU, например: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Введите поддельный идентификатор устройства (4 шестнадцатеричных символа), например: 73BF.\n   3. Убедитесь, что соответствующие загрузочные аргументы включены (при необходимости в конфигурации dGPU -> AMD dGPU).\n   4. Инструмент включает встроенные пресеты для распространенных поддельных графических процессоров AMD.',
      'ja': 'AMD dGPU スプーフィング (デバイス プロパティ):\n   1. dGPU PCI パスを入力します。例: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. スプーフィングされたデバイス ID (4 つの 16 進数文字) を入力します。例: 73BF\n   3. 適切なブート引数が有効になっていることを確認します (必要に応じて、[dGPU 構成] -> [AMD dGPU] で)\n   4. このツールには、一般的なスプーフィングされた AMD GPU 用の組み込みプリセットが含まれています',
      'ko': 'AMD dGPU 스푸핑(장치 속성):\n   1. dGPU PCI 경로를 입력합니다(예: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0))\n   2. 스푸핑된 장치 ID(4자리 16진수)를 입력하세요. 예: 73BF\n   3. 적절한 boot-args가 활성화되어 있는지 확인하십시오(필요에 따라 dGPU 구성 -> AMD dGPU에서).\n   4. 이 도구에는 일반적인 스푸핑된 AMD GPU에 대한 사전 설정이 내장되어 있습니다.',
      'it': 'Spoofing AMD dGPU (Proprietà dispositivo):\n   1. Immettere il percorso PCI dGPU, ad esempio: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Inserisci l\'ID dispositivo falsificato (4 caratteri esadecimali), ad esempio: 73BF\n   3. Assicurati che gli argomenti di avvio appropriati siano abilitati (in Configurazione dGPU -> AMD dGPU secondo necessità)\n   4. Lo strumento include preimpostazioni integrate per le comuni GPU AMD contraffatte',
      'tr': 'AMD dGPU Sahtekarlığı (Cihaz Özellikleri):\n   1. dGPU PCI Yolunu girin, örneğin: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Sahte Cihaz Kimliğini (4 onaltılık karakter) girin, örneğin: 73BF\n   3. Uygun önyükleme argümanlarının etkinleştirildiğinden emin olun (gerektiğinde dGPU Yapılandırması -> AMD dGPU\'da)\n   4. Araç, yaygın sahte AMD GPU\'lar için yerleşik ön ayarlar içerir',
      'vi': 'Giả mạo dGPU của AMD (Thuộc tính thiết bị):\n   1. Nhập Đường dẫn PCI dGPU, ví dụ: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Nhập ID thiết bị giả mạo (4 ký tự hex), ví dụ: 73BF\n   3. Đảm bảo bật các đối số khởi động thích hợp (trong Cấu hình dGPU -> AMD dGPU nếu cần)\n   4. Công cụ này bao gồm các cài đặt trước tích hợp sẵn cho các GPU AMD giả mạo phổ biến',
      'pl': 'Podszywanie się pod procesor AMD dGPU (właściwości urządzenia):\n   1. Wprowadź ścieżkę PCI dGPU, np.: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Wprowadź fałszywy identyfikator urządzenia (4 znaki szesnastkowe), np.: 73BF\n   3. Upewnij się, że włączone są odpowiednie argumenty rozruchowe (w razie potrzeby w Konfiguracja dGPU -> AMD dGPU)\n   4. Narzędzie zawiera wbudowane ustawienia wstępne dla popularnych, fałszywych procesorów graficznych AMD',
      'uk': 'AMD dGPU Spoofing (властивості пристрою):\n   1. Введіть шлях PCI dGPU, наприклад: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Введіть підроблений ідентифікатор пристрою (4 шістнадцяткові символи), наприклад: 73BF\n   3. Переконайтеся, що відповідні параметри завантаження ввімкнено (у Конфігурації dGPU -> AMD dGPU за потреби)\n   4. Інструмент містить вбудовані пресети для поширених підроблених графічних процесорів AMD',
      'nl': 'AMD dGPU-spoofing (apparaateigenschappen):\n   1. Voer het dGPU PCI-pad in, bijvoorbeeld: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Voer de vervalste apparaat-ID in (4 hexadecimale tekens), bijvoorbeeld: 73BF\n   3. Zorg ervoor dat de juiste boot-args zijn ingeschakeld (in dGPU-configuratie -> AMD dGPU indien nodig)\n   4. De tool bevat ingebouwde presets voor veelgebruikte vervalste AMD GPU\'s',
      'hi': 'AMD dGPU स्पूफ़िंग (डिवाइस गुण):\n   1. dGPU PCI पथ दर्ज करें, उदाहरण: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. नकली डिवाइस आईडी (4 हेक्स वर्ण) दर्ज करें, उदाहरण: 73BF\n   3. सुनिश्चित करें कि उपयुक्त बूट-आर्ग सक्षम हैं (डीजीपीयू कॉन्फ़िगरेशन में -> आवश्यकतानुसार एएमडी dGPU)\n   4. टूल में सामान्य नकली एएमडी जीपीयू के लिए अंतर्निहित प्रीसेट शामिल हैं',
      'ar': 'انتحال AMD dGPU (خصائص الجهاز):\n   1. أدخل مسار dGPU PCI، على سبيل المثال: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. أدخل معرف الجهاز المزيف (4 أحرف سداسية عشرية)، على سبيل المثال: 73BF\n   3. تأكد من تمكين وسائط التمهيد المناسبة (في تكوين dGPU -> AMD dGPU حسب الحاجة)\n   4. تتضمن الأداة إعدادات مسبقة مضمنة لوحدات معالجة الرسومات AMD المخادعة الشائعة',
      'id': 'Spoofing AMD dGPU (Properti Perangkat):\n   1. Masukkan Jalur PCI dGPU, misal: PciRoot(0x0)/Pci(0x1,0x0)/Pci(0x0,0x0)\n   2. Masukkan ID Perangkat palsu (4 karakter hex), misalnya: 73BF\n   3. Pastikan boot-arg yang sesuai diaktifkan (dalam Konfigurasi dGPU -> AMD dGPU sesuai kebutuhan)\n   4. Alat ini mencakup preset bawaan untuk GPU AMD palsu yang umum',
    },
