    'Add USB Wi-Fi required driver Kexts (Note: In addition to enabling this driver, install the Wireless USB Big Sur Adapter application in macOS; restart if it does not take effect)': {
      'pt': 'Adicione Kexts do driver USB Wi-Fi necessário (Observação: além de ativar este driver, instale o aplicativo Adaptador USB Big Sur sem fio no macOS; reinicie se não tiver efeito)',
      'zh': '添加USB Wi-Fi所需的驱动程序Kexts（注：除了启用此驱动程序外，还要在macOS中安装Wireless USB Big Sur Adapter应用程序；如果不生效请重新启动）',
      'zh_Hant': '新增USB Wi-Fi所需的驅動程式Kexts（註：除了啟用此驅動程式外，還要在macOS中安裝Wireless USB Big Sur Adapter應用程式；如果不生效請重新啟動）',
      'es': 'Agregue el controlador Kexts requerido para Wi-Fi USB (Nota: además de habilitar este controlador, instale la aplicación Adaptador inalámbrico USB Big Sur en macOS; reinicie si no surte efecto)',
      'de': 'Fügen Sie die für USB Wi-Fi erforderlichen Treiber-Kexts hinzu (Hinweis: Installieren Sie zusätzlich zur Aktivierung dieses Treibers die Anwendung „Wireless USB Big Sur Adapter“ in macOS; starten Sie sie neu, wenn sie nicht wirksam wird.)',
      'fr': 'Ajoutez le pilote USB Wi-Fi requis Kexts (Remarque : en plus d\'activer ce pilote, installez l\'application Wireless USB Big Sur Adapter dans macOS ; redémarrez si cela ne prend pas effet)',
      'ru': 'Добавьте требуемый драйвер USB Wi-Fi Kexts (Примечание: помимо включения этого драйвера установите приложение Wireless USB Big Sur Adaptor в macOS; перезапустите, если оно не вступит в силу)',
      'ja': 'USB Wi-Fi に必要なドライバー Kexts を追加します (注: このドライバーを有効にすることに加えて、macOS にワイヤレス USB Big Sur アダプター アプリケーションをインストールします。有効にならない場合は再起動します)',
      'ko': 'USB Wi-Fi 필수 드라이버 Kexts 추가(참고: 이 드라이버를 활성화하는 것 외에도 macOS에 Wireless USB Big Sur Adapter 애플리케이션을 설치하십시오. 적용되지 않으면 다시 시작하십시오)',
      'it': 'Aggiungi il driver USB Wi-Fi richiesto Kexts (Nota: oltre ad abilitare questo driver, installa l\'applicazione Wireless USB Big Sur Adapter in macOS; riavvia se non ha effetto)',
      'tr': 'USB Wi-Fi gerekli sürücü Kexts\'i ekleyin (Not: Bu sürücüyü etkinleştirmenin yanı sıra, Kablosuz USB Big Sur Adaptör uygulamasını macOS\'a yükleyin; etkili olmazsa yeniden başlatın)',
      'vi': 'Thêm trình điều khiển USB Wi-Fi cần thiết Kexts (Lưu ý: Ngoài việc bật trình điều khiển này, hãy cài đặt ứng dụng Wireless USB Big Sur Adapter trong macOS; khởi động lại nếu nó không có hiệu lực)',
      'pl': 'Dodaj wymagany sterownik USB Wi-Fi Kexts (Uwaga: oprócz włączenia tego sterownika zainstaluj aplikację Wireless USB Big Sur Adapter w systemie macOS; uruchom ponownie, jeśli nie przyniesie to efektu)',
      'uk': 'Додайте необхідний драйвер USB Wi-Fi Kexts (Примітка: окрім увімкнення цього драйвера, інсталюйте програму Wireless USB Big Sur Adapter у macOS; перезапустіть, якщо вона не почне діяти)',
      'nl': 'Voeg het USB Wi-Fi vereiste stuurprogramma Kexts toe (Opmerking: installeer naast het inschakelen van dit stuurprogramma ook de Wireless USB Big Sur Adapter-applicatie in macOS; start opnieuw op als dit geen effect heeft)',
      'hi': 'USB वाई-फाई आवश्यक ड्राइवर जोड़ें (नोट: इस ड्राइवर को सक्षम करने के अलावा, macOS में वायरलेस USB बिग सुर एडाप्टर एप्लिकेशन इंस्टॉल करें; यदि यह प्रभावी नहीं होता है तो पुनरारंभ करें)',
