    'Although disabling TRIM can improve boot speed on buggy drives, modern SSDs should keep TRIM enabled for optimal long-term performance and endurance.': {
      'pt': 'Embora a desativação do TRIM possa melhorar a velocidade de inicialização em unidades com bugs, os SSDs modernos devem manter o TRIM ativado para desempenho e resistência ideais a longo prazo.',
      'zh': '尽管禁用 TRIM 可以提高有问题的驱动器的启动速度，但现代 SSD 应保持 TRIM 启用，以获得最佳的长期性能和耐用性。',
      'zh_Hant': '儘管禁用 TRIM 可以提高有問題的驅動器的啟動速度，但現代 SSD 應保持 TRIM 啟用，以獲得最佳的長期性能和耐用性。',
      'es': 'Aunque deshabilitar TRIM puede mejorar la velocidad de arranque en unidades con errores, los SSD modernos deben mantener TRIM habilitado para lograr un rendimiento y una resistencia óptimos a largo plazo.',
      'de': 'Obwohl die Deaktivierung von TRIM die Startgeschwindigkeit auf fehlerhaften Laufwerken verbessern kann, sollten moderne SSDs TRIM für optimale Langzeitleistung und Ausdauer aktiviert lassen.',
      'fr': 'Bien que la désactivation de TRIM puisse améliorer la vitesse de démarrage sur les disques bogués, les SSD modernes devraient garder TRIM activé pour des performances et une endurance optimales à long terme.',
      'ru': 'Хотя отключение TRIM может улучшить скорость загрузки на дисках с ошибками, современные твердотельные накопители должны поддерживать TRIM включенным для оптимальной долгосрочной производительности и долговечности.',
      'ja': 'TRIM を無効にするとバグのあるドライブの起動速度が向上しますが、最新の SSD では最適な長期パフォーマンスと耐久性を得るために TRIM を有効にしておく必要があります。',
      'ko': 'TRIM을 비활성화하면 버그가 있는 드라이브의 부팅 속도가 향상될 수 있지만 최신 SSD는 최적의 장기 성능과 내구성을 위해 TRIM을 활성화된 상태로 유지해야 합니다.',
      'it': 'Sebbene disabilitare TRIM possa migliorare la velocità di avvio su unità difettose, i moderni SSD dovrebbero mantenere TRIM abilitato per prestazioni e resistenza ottimali a lungo termine.',
      'tr': 'TRIM\'i devre dışı bırakmak sorunlu sürücülerde önyükleme hızını artırabilse de modern SSD\'ler, optimum uzun vadeli performans ve dayanıklılık için TRIM\'i etkin tutmalıdır.',
      'vi': 'Mặc dù việc tắt TRIM có thể cải thiện tốc độ khởi động trên các ổ bị lỗi nhưng các ổ SSD hiện đại nên luôn bật TRIM để có hiệu suất và độ bền lâu dài tối ưu.',
      'pl': 'Chociaż wyłączenie TRIM może poprawić prędkość rozruchu na błędnych dyskach, nowoczesne dyski SSD powinny mieć włączone TRIM, aby zapewnić optymalną długoterminową wydajność i trwałość.',
      'uk': 'Хоча вимкнення TRIM може покращити швидкість завантаження на глючних дисках, сучасні твердотільні накопичувачі мають тримати TRIM увімкненим для оптимальної довгострокової продуктивності та витривалості.',
      'nl': 'Hoewel het uitschakelen van TRIM de opstartsnelheid op schijven met fouten kan verbeteren, moeten moderne SSD\'s TRIM ingeschakeld houden voor optimale prestaties en uithoudingsvermogen op de lange termijn.',
      'hi': 'हालाँकि TRIM को अक्षम करने से छोटी ड्राइव पर बूट गति में सुधार हो सकता है, आधुनिक SSDs को इष्टतम दीर्घकालिक प्रदर्शन और सहनशक्ति के लिए TRIM को सक्षम रखना चाहिए।',
      'ar': 'على الرغم من أن تعطيل TRIM يمكن أن يحسن سرعة التمهيد على محركات الأقراص التي تجرها الدواب، إلا أن محركات أقراص SSD الحديثة يجب أن تحافظ على تمكين TRIM للحصول على أفضل أداء وتحمل على المدى الطويل.',
      'id': 'Meskipun menonaktifkan TRIM dapat meningkatkan kecepatan boot pada drive yang bermasalah, SSD modern harus tetap mengaktifkan TRIM untuk kinerja dan daya tahan jangka panjang yang optimal.',
    },
    'Ambient light sensor emulation for auto-brightness (do not enable if laptop lacks sensor)': {
      'pt': 'Emulação de sensor de luz ambiente para brilho automático (não habilite se o laptop não tiver sensor)',
      'zh': '用于自动亮度的环境光传感器模拟（如果笔记本电脑缺少传感器，则不要启用）',
      'zh_Hant': '用於自動亮度的環境光感測器模擬（如果筆記型電腦缺少感測器，則不要啟用）',
      'es': 'Emulación de sensor de luz ambiental para brillo automático (no habilitar si la computadora portátil carece de sensor)',
      'de': 'Emulation des Umgebungslichtsensors für automatische Helligkeit (nicht aktivieren, wenn der Laptop keinen Sensor hat)',
      'fr': 'Émulation du capteur de lumière ambiante pour la luminosité automatique (ne pas activer si l\'ordinateur portable ne dispose pas de capteur)',
      'ru': 'Эмуляция датчика внешней освещенности для автоматической регулировки яркости (не включайте, если на ноутбуке нет датчика)',
      'ja': '自動明るさ調整のための周囲光センサーエミュレーション (ラップトップにセンサーがない場合は有効にしないでください)',
      'ko': '자동 밝기를 위한 주변광 센서 에뮬레이션(노트북에 센서가 없는 경우 활성화하지 않음)',
      'it': 'Emulazione del sensore di luce ambientale per la luminosità automatica (non abilitare se il laptop non dispone di sensore)',
      'tr': 'Otomatik parlaklık için ortam ışığı sensörü emülasyonu (dizüstü bilgisayarda sensör yoksa etkinleştirmeyin)',
      'vi': 'Mô phỏng cảm biến ánh sáng xung quanh để tự động điều chỉnh độ sáng (không bật nếu máy tính xách tay thiếu cảm biến)',
      'pl': 'Emulacja czujnika światła otoczenia dla automatycznej jasności (nie włączaj, jeśli laptop nie ma czujnika)',
      'uk': 'Емуляція датчика навколишнього освітлення для автоматичного налаштування яскравості (не вмикати, якщо в ноутбуку немає датчика)',
      'nl': 'Emulatie van omgevingslichtsensor voor automatische helderheid (niet inschakelen als laptop geen sensor heeft)',
      'hi': 'ऑटो-ब्राइटनेस के लिए परिवेश प्रकाश सेंसर अनुकरण (यदि लैपटॉप में सेंसर की कमी है तो सक्षम न करें)',
      'ar': 'محاكاة مستشعر الإضاءة المحيطة للسطوع التلقائي (لا تقم بالتمكين إذا كان الكمبيوتر المحمول يفتقر إلى المستشعر)',
      'id': 'Emulasi sensor cahaya sekitar untuk kecerahan otomatis (jangan aktifkan jika laptop tidak memiliki sensor)',
    },
    'Apple AirPort and Fenvi native cards. Natively supported up to Ventura 13; patchable for Sonoma 14 & Sequoia 15 via OCLP root patches!': {
      'pt': 'Placas nativas Apple AirPort e Fenvi. Suporte nativo até Ventura 13; patchable para Sonoma 14 e Sequoia 15 via patches de raiz OCLP!',
      'zh': 'Apple AirPort 和 Fenvi 本机卡。原生支持高达 Ventura 13；可通过 OCLP 根补丁修补 Sonoma 14 和 Sequoia 15！',
      'zh_Hant': 'Apple AirPort 和 Fenvi 本機卡。原生支援高達 Ventura 13；可透過 OCLP 根補丁修補 Sonoma 14 和 Sequoia 15！',
      'es': 'Tarjetas nativas Apple AirPort y Fenvi. Compatible de forma nativa hasta Ventura 13; Parcheable para Sonoma 14 y Sequoia 15 mediante parches raíz OCLP.',
      'de': 'Native Karten von Apple AirPort und Fenvi. Native Unterstützung bis Ventura 13; patchbar für Sonoma 14 & Sequoia 15 über OCLP-Root-Patches!',
      'fr': 'Cartes natives Apple AirPort et Fenvi. Supporté nativement jusqu\'à Ventura 13 ; patchable pour Sonoma 14 et Sequoia 15 via les correctifs racine OCLP !',
      'ru': 'Родные карты Apple AirPort и Fenvi. Встроенная поддержка до Ventura 13; доступен для Sonoma 14 и Sequoia 15 через корневые патчи OCLP!',
      'ja': 'Apple AirMac および Fenvi ネイティブ カード。 Ventura 13 まではネイティブでサポートされています。 OCLP ルート パッチ経由で Sonoma 14 および Sequoia 15 にパッチ可能!',
      'ko': 'Apple AirPort 및 Fenvi 기본 카드. Ventura 13까지 기본적으로 지원됩니다. OCLP 루트 패치를 통해 Sonoma 14 및 Sequoia 15에 패치 가능!',
      'it': 'Schede native Apple AirPort e Fenvi. Supportato nativamente fino a Ventura 13; patchabile per Sonoma 14 e Sequoia 15 tramite patch root OCLP!',
      'tr': 'Apple AirPort ve Fenvi yerel kartları. Ventura 13\'e kadar yerel olarak desteklenir; OCLP kök yamaları aracılığıyla Sonoma 14 ve Sequoia 15 için yama yapılabilir!',
      'vi': 'Thẻ gốc Apple AirPort và Fenvi. Được hỗ trợ nguyên bản lên tới Ventura 13; có thể vá cho Sonoma 14 & Sequoia 15 thông qua các bản vá gốc OCLP!',
      'pl': 'Natywne karty Apple AirPort i Fenvi. Natywnie obsługiwane do Ventura 13; Możliwość łatania dla Sonoma 14 i Sequoia 15 poprzez łatki root OCLP!',
      'uk': 'Вбудовані карти Apple AirPort і Fenvi. Вбудована підтримка до Ventura 13; можна виправити для Sonoma 14 і Sequoia 15 через кореневі патчі OCLP!',
      'nl': 'Apple AirPort- en Fenvi-native kaarten. Native ondersteund tot Ventura 13; patchbaar voor Sonoma 14 & Sequoia 15 via OCLP-rootpatches!',
      'hi': 'एप्पल एयरपोर्ट और फेनवी देशी कार्ड। वेंचुरा 13 तक मूल रूप से समर्थित; ओसीएलपी रूट पैच के माध्यम से सोनोमा 14 और सिकोइया 15 के लिए पैच करने योग्य!',
      'ar': 'بطاقات Apple AirPort وFenvi الأصلية. مدعوم محليًا حتى Ventura 13؛ قابل للتصحيح لـ Sonoma 14 وSequoia 15 عبر تصحيحات جذر OCLP!',
      'id': 'Kartu asli Apple AirPort dan Fenvi. Didukung secara asli hingga Ventura 13; dapat ditambal untuk Sonoma 14 & Sequoia 15 melalui patch root OCLP!',
    },
