      'ar': 'تدعم برامج تشغيل Atheros نظام التشغيل macOS Mojave 10.14 ~ macOS Sequoia 15! ملاحظة: يتطلب نظام التشغيل macOS Monterey 12+ تصحيح جذر OCLP!',
