    'Bluetooth Driver Notes:\n  1. When Intel Wi-Fi is selected, Intel Bluetooth drivers are automatically configured based on macOS version!\n  2. When Broadcom Wi-Fi is selected, Broadcom Bluetooth drivers are automatically configured based on macOS version!\n  3. When Atheros Wi-Fi is selected, Atheros Bluetooth drivers are automatically configured!\n  4. Manually select Bluetooth parameters only if not covered above or for standalone modules.\n  5. Bluetooth uses USB internally; ensure USB ports are properly mapped if Bluetooth is malfunctioning!': {
      'pt': 'Notas do driver Bluetooth:\n  1. Quando Intel Wi-Fi é selecionado, os drivers Intel Bluetooth são configurados automaticamente com base na versão do macOS!\n  2. Quando Broadcom Wi-Fi é selecionado, os drivers Broadcom Bluetooth são configurados automaticamente com base na versão do macOS!\n  3. Quando Atheros Wi-Fi é selecionado, os drivers Atheros Bluetooth são configurados automaticamente!\n  4. Selecione manualmente os parâmetros Bluetooth somente se não forem abordados acima ou para módulos independentes.\n  5. Bluetooth usa USB internamente; certifique-se de que as portas USB estejam mapeadas corretamente se o Bluetooth estiver com defeito!',
      'zh': '蓝牙驱动注意事项：\n  1.当选择Intel Wi-Fi时，会根据macOS版本自动配置Intel蓝牙驱动！\n  2.选择Broadcom Wi-Fi时，会根据macOS版本自动配置Broadcom蓝牙驱动！\n  3. 选择 Atheros Wi-Fi 时，会自动配置 Atheros 蓝牙驱动程序！\n  4. 仅当上面未提及或对于独立模块时，才手动选择蓝牙参数。\n  5.蓝牙内部使用USB；如果蓝牙出现故障，请确保 USB 端口正确映射！',
      'zh_Hant': '藍牙驅動注意事項：\n  1.當選擇Intel Wi-Fi時，會根據macOS版本自動設定Intel藍牙驅動！\n  2.選擇Broadcom Wi-Fi時，會根據macOS版本自動設定Broadcom藍牙驅動！\n  3. 選擇 Atheros Wi-Fi 時，會自動設定 Atheros 藍牙驅動程式！\n  4. 僅當上面未提及或對於獨立模組時，才手動選擇藍牙參數。\n  5.藍牙內部使用USB；如果藍牙故障，請確保 USB 連接埠正確映射！',
      'es': 'Notas del controlador Bluetooth:\n  1. Cuando se selecciona Intel Wi-Fi, los controladores Intel Bluetooth se configuran automáticamente según la versión de macOS.\n  2. Cuando se selecciona Broadcom Wi-Fi, los controladores Broadcom Bluetooth se configuran automáticamente según la versión de macOS.\n  3. Cuando se selecciona Atheros Wi-Fi, los controladores Bluetooth de Atheros se configuran automáticamente.\n  4. Seleccione manualmente los parámetros de Bluetooth solo si no se tratan anteriormente o para módulos independientes.\n  5. Bluetooth utiliza USB internamente; ¡Asegúrese de que los puertos USB estén asignados correctamente si Bluetooth no funciona correctamente!',
      'de': 'Hinweise zum Bluetooth-Treiber:\n  1. Wenn Intel Wi-Fi ausgewählt ist, werden Intel Bluetooth-Treiber automatisch basierend auf der macOS-Version konfiguriert!\n  2. Wenn Broadcom Wi-Fi ausgewählt ist, werden Broadcom Bluetooth-Treiber automatisch basierend auf der macOS-Version konfiguriert!\n  3. Wenn Atheros Wi-Fi ausgewählt ist, werden Atheros Bluetooth-Treiber automatisch konfiguriert!\n  4. Wählen Sie Bluetooth-Parameter nur dann manuell aus, wenn sie oben nicht abgedeckt sind oder für eigenständige Module.\n  5. Bluetooth verwendet intern USB; Stellen Sie sicher, dass die USB-Anschlüsse ordnungsgemäß zugeordnet sind, wenn Bluetooth nicht funktioniert!',
      'fr': 'Remarques sur le pilote Bluetooth :\n  1. Lorsque Intel Wi-Fi est sélectionné, les pilotes Intel Bluetooth sont automatiquement configurés en fonction de la version de macOS !\n  2. Lorsque Broadcom Wi-Fi est sélectionné, les pilotes Broadcom Bluetooth sont automatiquement configurés en fonction de la version de macOS !\n  3. Lorsque Atheros Wi-Fi est sélectionné, les pilotes Atheros Bluetooth sont automatiquement configurés !\n  4. Sélectionnez manuellement les paramètres Bluetooth uniquement s\'ils ne sont pas couverts ci-dessus ou pour les modules autonomes.\n  5. Bluetooth utilise l’USB en interne ; assurez-vous que les ports USB sont correctement mappés en cas de dysfonctionnement du Bluetooth !',
      'ru': 'Примечания к драйверу Bluetooth:\n  1. При выборе Intel Wi-Fi драйверы Intel Bluetooth автоматически настраиваются в зависимости от версии macOS!\n  2. При выборе Broadcom Wi-Fi драйверы Broadcom Bluetooth автоматически настраиваются в зависимости от версии macOS!\n  3. При выборе Atheros Wi-Fi драйверы Atheros Bluetooth настраиваются автоматически!\n  4. Вручную выбирайте параметры Bluetooth, только если они не указаны выше или для автономных модулей.\n  5. Bluetooth использует внутренний USB; убедитесь, что порты USB правильно сопоставлены, если Bluetooth неисправен!',
      'ja': 'Bluetooth ドライバーのメモ:\n  1. Intel Wi-Fi が選択されている場合、Intel Bluetooth ドライバーは macOS バージョンに基づいて自動的に構成されます。\n  2. Broadcom Wi-Fi が選択されている場合、Broadcom Bluetooth ドライバーは macOS バージョンに基づいて自動的に構成されます。\n  3. Atheros Wi-Fi が選択されると、Atheros Bluetooth ドライバーが自動的に構成されます。\n  4. 上記で説明されていない場合、またはスタンドアロン モジュールの場合にのみ、Bluetooth パラメータを手動で選択します。\n  5. Bluetooth は内部で USB を使用します。 Bluetooth が故障している場合は、USB ポートが正しくマッピングされていることを確認してください。',
      'ko': '블루투스 드라이버 참고사항:\n  1. Intel Wi-Fi를 선택하면 Intel Bluetooth 드라이버가 macOS 버전에 따라 자동으로 구성됩니다!\n  2. Broadcom Wi-Fi를 선택하면 Broadcom Bluetooth 드라이버가 macOS 버전에 따라 자동으로 구성됩니다!\n  3. Atheros Wi-Fi를 선택하면 Atheros Bluetooth 드라이버가 자동으로 구성됩니다!\n  4. 위에서 다루지 않은 경우나 독립형 모듈의 경우에만 Bluetooth 매개변수를 수동으로 선택하십시오.\n  5. 블루투스는 내부적으로 USB를 사용합니다. Bluetooth가 오작동하는 경우 USB 포트가 올바르게 매핑되었는지 확인하십시오!',
      'it': 'Note sul driver Bluetooth:\n  1. Quando è selezionato Intel Wi-Fi, i driver Intel Bluetooth vengono configurati automaticamente in base alla versione macOS!\n  2. Quando è selezionato Broadcom Wi-Fi, i driver Broadcom Bluetooth vengono configurati automaticamente in base alla versione di macOS!\n  3. Quando è selezionato Atheros Wi-Fi, i driver Bluetooth Atheros vengono configurati automaticamente!\n  4. Selezionare manualmente i parametri Bluetooth solo se non trattati sopra o per moduli autonomi.\n  5. Bluetooth utilizza USB internamente; assicurarsi che le porte USB siano mappate correttamente se il Bluetooth non funziona correttamente!',
      'tr': 'Bluetooth Sürücüsü Notları:\n  1. Intel Wi-Fi seçildiğinde Intel Bluetooth sürücüleri, macOS sürümüne göre otomatik olarak yapılandırılır!\n  2. Broadcom Wi-Fi seçildiğinde Broadcom Bluetooth sürücüleri, macOS sürümüne göre otomatik olarak yapılandırılır!\n  3. Atheros Wi-Fi seçildiğinde Atheros Bluetooth sürücüleri otomatik olarak yapılandırılır!\n  4. Bluetooth parametrelerini yalnızca yukarıda ele alınmıyorsa veya bağımsız modüller için manuel olarak seçin.\n  5. Bluetooth dahili olarak USB\'yi kullanır; Bluetooth arızalıysa USB bağlantı noktalarının düzgün şekilde eşleştirildiğinden emin olun!',
      'vi': 'Ghi chú về Trình điều khiển Bluetooth:\n  1. Khi chọn Intel Wi-Fi, trình điều khiển Intel Bluetooth sẽ được cấu hình tự động dựa trên phiên bản macOS!\n  2. Khi chọn Broadcom Wi-Fi, trình điều khiển Broadcom Bluetooth sẽ được cấu hình tự động dựa trên phiên bản macOS!\n  3. Khi chọn Atheros Wi-Fi, trình điều khiển Bluetooth Atheros sẽ được cấu hình tự động!\n  4. Chỉ chọn các thông số Bluetooth theo cách thủ công nếu không được đề cập ở trên hoặc đối với các mô-đun độc lập.\n  5. Bluetooth sử dụng USB bên trong; đảm bảo các cổng USB được ánh xạ chính xác nếu Bluetooth gặp trục trặc!',
      'pl': 'Uwagi dotyczące sterownika Bluetooth:\n  1. Po wybraniu Intel Wi-Fi sterowniki Intel Bluetooth są automatycznie konfigurowane w oparciu o wersję systemu macOS!\n  2. Po wybraniu Broadcom Wi-Fi sterowniki Broadcom Bluetooth są automatycznie konfigurowane w oparciu o wersję systemu macOS!\n  3. Po wybraniu Atheros Wi-Fi sterowniki Atheros Bluetooth zostaną skonfigurowane automatycznie!\n  4. Ręcznie wybierz parametry Bluetooth tylko wtedy, gdy nie zostały omówione powyżej lub w przypadku modułów samodzielnych.\n  5. Bluetooth wykorzystuje wewnętrznie USB; upewnij się, że porty USB są prawidłowo mapowane, jeśli Bluetooth działa nieprawidłowo!',
      'uk': 'Примітки драйвера Bluetooth:\n  1. Якщо вибрано Intel Wi-Fi, драйвери Intel Bluetooth автоматично налаштовуються на основі версії macOS!\n  2. Якщо вибрано Broadcom Wi-Fi, драйвери Broadcom Bluetooth автоматично налаштовуються на основі версії macOS!\n  3. Коли вибрано Atheros Wi-Fi, драйвери Atheros Bluetooth налаштовуються автоматично!\n  4. Виберіть параметри Bluetooth вручну, лише якщо вони не описані вище, або для окремих модулів.\n  5. Bluetooth використовує внутрішній USB; переконайтеся, що USB-порти правильно зіставлені, якщо Bluetooth не працює!',
      'nl': 'Opmerkingen over het Bluetooth-stuurprogramma:\n  1. Wanneer Intel Wi-Fi is geselecteerd, worden Intel Bluetooth-stuurprogramma\'s automatisch geconfigureerd op basis van de macOS-versie!\n  2. Wanneer Broadcom Wi-Fi is geselecteerd, worden Broadcom Bluetooth-stuurprogramma\'s automatisch geconfigureerd op basis van de macOS-versie!\n  3. Wanneer Atheros Wi-Fi is geselecteerd, worden Atheros Bluetooth-stuurprogramma\'s automatisch geconfigureerd!\n  4. Selecteer handmatig Bluetooth-parameters alleen als dit hierboven niet wordt behandeld of voor zelfstandige modules.\n  5. Bluetooth gebruikt intern USB; zorg ervoor dat de USB-poorten correct zijn toegewezen als Bluetooth niet goed functioneert!',
      'hi': 'ब्लूटूथ ड्राइवर नोट्स:\n  1. जब Intel वाई-फाई का चयन किया जाता है, तो Intel ब्लूटूथ ड्राइवर macOS संस्करण के आधार पर स्वचालित रूप से कॉन्फ़िगर हो जाते हैं!\n  2. जब ब्रॉडकॉम वाई-फाई का चयन किया जाता है, तो ब्रॉडकॉम ब्लूटूथ ड्राइवर macOS संस्करण के आधार पर स्वचालित रूप से कॉन्फ़िगर हो जाते हैं!\n  3. जब एथेरोस वाई-फाई का चयन किया जाता है, तो एथेरोस ब्लूटूथ ड्राइवर स्वचालित रूप से कॉन्फ़िगर हो जाते हैं!\n  4. मैन्युअल रूप से केवल ब्लूटूथ पैरामीटर का चयन करें यदि ऊपर कवर नहीं किया गया है या स्टैंडअलोन मॉड्यूल के लिए।\n  5. ब्लूटूथ आंतरिक रूप से USB का उपयोग करता है; सुनिश्चित करें कि यदि ब्लूटूथ खराब है तो यूएसबी पोर्ट ठीक से मैप किए गए हैं!',
      'ar': 'ملاحظات برنامج تشغيل البلوتوث:\n  1. عند تحديد Intel Wi-Fi، يتم تكوين برامج تشغيل Intel Bluetooth تلقائيًا بناءً على إصدار macOS!\n  2. عند تحديد Broadcom Wi-Fi، يتم تكوين برامج تشغيل Broadcom Bluetooth تلقائيًا بناءً على إصدار macOS!\n  3. عند تحديد Atheros Wi-Fi، يتم تكوين برامج تشغيل Atheros Bluetooth تلقائيًا!\n  4. حدد معلمات Bluetooth يدويًا فقط إذا لم يتم تغطيتها أعلاه أو للوحدات المستقلة.\n  5. يستخدم البلوتوث USB داخليًا؛ تأكد من تعيين منافذ USB بشكل صحيح في حالة تعطل Bluetooth!',
      'id': 'Catatan Pengandar Bluetooth:\n  1. Ketika Intel Wi-Fi dipilih, driver Bluetooth Intel secara otomatis dikonfigurasikan berdasarkan versi macOS!\n  2. Ketika Broadcom Wi-Fi dipilih, driver Broadcom Bluetooth secara otomatis dikonfigurasikan berdasarkan versi macOS!\n  3. Ketika Atheros Wi-Fi dipilih, driver Bluetooth Atheros dikonfigurasi secara otomatis!\n  4. Pilih parameter Bluetooth secara manual hanya jika tidak dibahas di atas atau untuk modul mandiri.\n  5. Bluetooth menggunakan USB secara internal; pastikan port USB dipetakan dengan benar jika Bluetooth tidak berfungsi!',
    },
