    'Common HPET Paths:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  This option is used to fix audio card IRQ conflict issues! Note: Do not enable unless your audio has IRQ issues!': {
      'pt': 'Caminhos HPET comuns:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Esta opção é usada para corrigir problemas de conflito de IRQ da placa de áudio! Nota: Não ative a menos que seu áudio tenha problemas de IRQ!',
      'zh': '常见的 HPET 路径：\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  该选项用于修复声卡IRQ冲突问题！注意：除非您的音频有 IRQ 问题，否则请勿启用！',
      'zh_Hant': '常見的 HPET 路徑：\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  此選項用於修復聲卡IRQ衝突問題！注意：除非您的音訊有 IRQ 問題，否則請勿啟用！',
      'es': 'Rutas HPET comunes:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  ¡Esta opción se utiliza para solucionar problemas de conflictos de IRQ de la tarjeta de audio! Nota: ¡No lo habilites a menos que tu audio tenga problemas de IRQ!',
      'de': 'Gängige HPET-Pfade:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Diese Option wird verwendet, um IRQ-Konfliktprobleme mit Audiokarten zu beheben! Hinweis: Aktivieren Sie diese Option nur, wenn Ihr Audio IRQ-Probleme aufweist!',
      'fr': 'Chemins HPET courants :\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Cette option est utilisée pour résoudre les problèmes de conflit IRQ de la carte audio ! Remarque : ne l\'activez que si votre audio présente des problèmes d\'IRQ !',
      'ru': 'Распространенные пути HPET:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Эта опция используется для устранения проблем с конфликтом IRQ звуковой карты! Примечание. Не включайте, если у вашего звука нет проблем с IRQ!',
      'ja': '一般的な HPET パス:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  このオプションは、オーディオ カードの IRQ 競合の問題を修正するために使用されます。注: オーディオに IRQ の問題がない限り、有効にしないでください。',
      'ko': '일반적인 HPET 경로:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  이 옵션은 오디오 카드 IRQ 충돌 문제를 해결하는 데 사용됩니다! 참고: 오디오에 IRQ 문제가 없는 한 활성화하지 마십시오!',
      'it': 'Percorsi HPET comuni:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Questa opzione viene utilizzata per risolvere i problemi di conflitto IRQ della scheda audio! Nota: non abilitare a meno che l\'audio non presenti problemi IRQ!',
      'tr': 'Ortak HPET Yolları:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Bu seçenek ses kartı IRQ çakışması sorunlarını düzeltmek için kullanılır! Not: Sesinizde IRQ sorunları olmadığı sürece etkinleştirmeyin!',
      'vi': 'Đường dẫn HPET phổ biến:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Tùy chọn này được sử dụng để khắc phục sự cố xung đột IRQ của card âm thanh! Lưu ý: Không bật trừ khi âm thanh của bạn có vấn đề về IRQ!',
      'pl': 'Typowe ścieżki HPET:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Ta opcja służy do naprawiania problemów związanych z konfliktem przerwań IRQ karty dźwiękowej! Uwaga: nie włączaj, jeśli dźwięk nie ma problemów z przerwaniami IRQ!',
      'uk': 'Загальні шляхи HPET:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Ця опція використовується для вирішення проблем конфлікту IRQ звукової карти! Примітка: не вмикайте, якщо ваш аудіо не має проблеми з IRQ!',
      'nl': 'Algemene HPET-paden:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Deze optie wordt gebruikt om IRQ-conflictproblemen met de geluidskaart op te lossen! Opmerking: schakel dit alleen in als uw audio IRQ-problemen heeft!',
      'hi': 'सामान्य एचपीईटी पथ:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  इस विकल्प का उपयोग ऑडियो कार्ड IRQ विरोध समस्याओं को ठीक करने के लिए किया जाता है! नोट: जब तक आपके ऑडियो में IRQ समस्याएँ न हों, तब तक सक्षम न करें!',
      'ar': 'مسارات HPET الشائعة:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  يُستخدم هذا الخيار لإصلاح مشكلات تعارض IRQ لبطاقة الصوت! ملاحظة: لا تقم بالتمكين إلا إذا كان الصوت الخاص بك به مشكلات IRQ!',
      'id': 'Jalur HPET Umum:\n  \\_SB.PCI0.LPCB.HPET\n  \\_SB.PCI0.LPC.HPET\n  \\_SB.PCI0.HPET\n  Opsi ini digunakan untuk memperbaiki masalah konflik IRQ kartu audio! Catatan: Jangan aktifkan kecuali audio Anda memiliki masalah IRQ!',
    },
