    'Completely disable DarkWake mode to enter traditional sleep; fixes wake black screen and auto-wake issues': {
      'pt': 'Desative completamente o modo DarkWake para entrar no modo de suspensão tradicional; corrige problemas de tela preta e ativação automática',
      'zh': '完全禁用DarkWake模式进入传统睡眠；修复唤醒黑屏和自动唤醒问题',
      'zh_Hant': '完全停用DarkWake模式進入傳統睡眠；修復喚醒黑屏和自動喚醒問題',
      'es': 'Desactive completamente el modo DarkWake para entrar en el modo de suspensión tradicional; soluciona problemas de activación automática y de pantalla negra',
      'de': 'Deaktivieren Sie den DarkWake-Modus vollständig, um in den herkömmlichen Ruhezustand zu wechseln. Behebt Probleme beim Aufwecken des schwarzen Bildschirms und beim automatischen Aufwecken',
      'fr': 'Désactivez complètement le mode DarkWake pour entrer en veille traditionnelle ; corrige les problèmes d\'écran noir de réveil et de réveil automatique',
      'ru': 'Полностью отключите режим DarkWake, чтобы войти в традиционный сон; исправляет черный экран пробуждения и проблемы с автоматическим пробуждением',
      'ja': '従来のスリープに入るには、DarkWake モードを完全に無効にします。ウェイクブラックスクリーンと自動ウェイクの問題を修正',
      'ko': '일반 절전 모드로 전환하려면 DarkWake 모드를 완전히 비활성화하세요. 깨우기 검은 화면 및 자동 깨우기 문제 수정',
      'it': 'Disabilita completamente la modalità DarkWake per entrare nel sonno tradizionale; risolve i problemi di riattivazione dello schermo nero e di riattivazione automatica',
      'tr': 'Geleneksel uykuya girmek için DarkWake modunu tamamen devre dışı bırakın; siyah ekranı uyandırma ve otomatik uyanma sorunlarını düzeltir',
      'vi': 'Tắt hoàn toàn chế độ DarkWake để vào chế độ ngủ truyền thống; khắc phục sự cố đánh thức màn hình đen và tự động đánh thức',
      'pl': 'Całkowicie wyłącz tryb DarkWake, aby przejść do tradycyjnego uśpienia; naprawia problemy z czarnym ekranem i automatycznym wybudzaniem',
      'uk': 'Повністю вимкніть режим DarkWake, щоб увійти в традиційний режим сну; вирішує проблеми з пробудженням чорного екрана та автоматичним пробудженням',
      'nl': 'Schakel de DarkWake-modus volledig uit om naar de traditionele slaapstand te gaan; lost problemen met het ontwaken van een zwart scherm en automatisch ontwaken op',
      'hi': 'पारंपरिक नींद में प्रवेश करने के लिए डार्कवेक मोड को पूरी तरह से अक्षम करें; वेक ब्लैक स्क्रीन और ऑटो-वेक समस्याओं को ठीक करता है',
      'ar': 'قم بتعطيل وضع DarkWake تمامًا للدخول في وضع السكون التقليدي؛ يعمل على إصلاح مشكلات تنبيه الشاشة السوداء والتنبيه التلقائي',
      'id': 'Nonaktifkan sepenuhnya mode DarkWake untuk memasuki mode tidur tradisional; memperbaiki masalah bangun layar hitam dan bangun otomatis',
    },
