    'Current Framebuffer does not support structured recommendations; remove existing value and reselect a supported iGPU configuration.': {
      'pt': 'O Framebuffer atual não oferece suporte a recomendações estruturadas; remova o valor existente e selecione novamente uma configuração iGPU compatível.',
      'zh': '当前Framebuffer不支持结构化推荐；删除现有值并重新选择支持的 iGPU 配置。',
      'zh_Hant': '目前Framebuffer不支援結構化推薦；刪除現有值並重新選擇支援的 iGPU 配置。',
      'es': 'Framebuffer actual no admite recomendaciones estructuradas; elimine el valor existente y vuelva a seleccionar una configuración de iGPU compatible.',
      'de': 'Der aktuelle Framebuffer unterstützt keine strukturierten Empfehlungen; Entfernen Sie den vorhandenen Wert und wählen Sie erneut eine unterstützte iGPU-Konfiguration aus.',
      'fr': 'Le Framebuffer actuel ne prend pas en charge les recommandations structurées ; supprimez la valeur existante et resélectionnez une configuration iGPU prise en charge.',
      'ru': 'Текущий Framebuffer не поддерживает структурированные рекомендации; удалите существующее значение и повторно выберите поддерживаемую конфигурацию iGPU.',
      'ja': '現在のフレームバッファは構造化された推奨事項をサポートしていません。既存の値を削除し、サポートされている iGPU 構成を再選択します。',
      'ko': '현재 프레임버퍼는 구조화된 권장 사항을 지원하지 않습니다. 기존 값을 제거하고 지원되는 iGPU 구성을 다시 선택하세요.',
      'it': 'L\'attuale Framebuffer non supporta raccomandazioni strutturate; rimuovere il valore esistente e selezionare nuovamente una configurazione iGPU supportata.',
      'tr': 'Geçerli Framebuffer yapılandırılmış önerileri desteklemez; mevcut değeri kaldırın ve desteklenen bir iGPU yapılandırmasını yeniden seçin.',
      'vi': 'Bộ đệm khung hiện tại không hỗ trợ các đề xuất có cấu trúc; xóa giá trị hiện có và chọn lại cấu hình iGPU được hỗ trợ.',
      'pl': 'Obecny bufor ramki nie obsługuje rekomendacji strukturalnych; usuń istniejącą wartość i ponownie wybierz obsługiwaną konfigurację iGPU.',
      'uk': 'Поточний Framebuffer не підтримує структуровані рекомендації; видаліть наявне значення та повторно виберіть підтримувану конфігурацію iGPU.',
      'nl': 'De huidige framebuffer ondersteunt geen gestructureerde aanbevelingen; verwijder de bestaande waarde en selecteer opnieuw een ondersteunde iGPU-configuratie.',
      'hi': 'वर्तमान फ़्रेमबफ़र संरचित अनुशंसाओं का समर्थन नहीं करता है; मौजूदा मान हटाएं और समर्थित iGPU कॉन्फ़िगरेशन को फिर से चुनें।',
      'ar': 'لا يدعم Framebuffer الحالي التوصيات المنظمة؛ قم بإزالة القيمة الحالية وأعد تحديد تكوين iGPU المدعوم.',
      'id': 'Framebuffer saat ini tidak mendukung rekomendasi terstruktur; hapus nilai yang ada dan pilih kembali konfigurasi iGPU yang didukung.',
    },
