    'DevirtualiseMmio(Helps resolve conflicts/incompatibilities when firmware handles MMIO regions, improving system compatibility and stability. Often combined with OpenCore Debug to customize MMIO for boards stuck at [EB|#LOG:EXITBS:START], e.g. some X58, X79, X99, and AMD 7000 series boards)': {
      'pt': 'DevirtualiseMmio(Ajuda a resolver conflitos/incompatibilidades quando o firmware lida com regiões MMIO, melhorando a compatibilidade e estabilidade do sistema. Freqüentemente combinado com OpenCore Debug para personalizar MMIO para placas travadas em [EB|#LOG:EXITBS:START], por exemplo, algumas placas da série X58, X79, X99 e AMD 7000)',
      'zh': 'DevirtualiseMmio（帮助解决固件处理MMIO区域时的冲突/不兼容问题，提高系统兼容性和稳定性。通常与OpenCore Debug结合使用，为卡在[EB|#LOG:EXITBS:START]的主板定制MMIO，例如一些X58、X79、X99和AMD 7000系列主板）',
      'zh_Hant': 'DevirtualiseMmio（協助解決韌體處理MMIO區域時的衝突/不相容問題，提高系統相容性和穩定性。通常與OpenCore Debug結合使用，為卡在[EB|#LOG:EXITBS:START]的主機板客製化MMIO，例如一些X58、X79、X99和AMD 7000系列主機板）',
      'es': 'DevirtualiseMmio (Ayuda a resolver conflictos/incompatibilidades cuando el firmware maneja regiones MMIO, mejorando la compatibilidad y la estabilidad del sistema. A menudo se combina con OpenCore Debug para personalizar MMIO para placas atascadas en [EB|#LOG:EXITBS:START], por ejemplo, algunas placas de las series X58, X79, X99 y AMD 7000)',
      'de': 'DevirtualiseMmio (Hilft bei der Lösung von Konflikten/Inkompatibilitäten, wenn die Firmware MMIO-Regionen verarbeitet, und verbessert so die Systemkompatibilität und -stabilität. Wird oft mit OpenCore Debug kombiniert, um MMIO für Boards anzupassen, die bei [EB|#LOG:EXITBS:START] hängen bleiben, z. B. einige Boards der X58-, X79-, X99- und AMD 7000-Serie.)',
      'fr': 'DevirtualiseMmio (Aide à résoudre les conflits/incompatibilités lorsque le micrologiciel gère les régions MMIO, améliorant ainsi la compatibilité et la stabilité du système. Souvent combiné avec OpenCore Debug pour personnaliser MMIO pour les cartes bloquées sur [EB|#LOG:EXITBS:START], par exemple certaines cartes des séries X58, X79, X99 et AMD 7000)',
      'ru': 'DevirtualiseMmio (Помогает разрешать конфликты/несовместимости, когда прошивка обрабатывает регионы MMIO, улучшая совместимость и стабильность системы. Часто в сочетании с OpenCore Debug для настройки MMIO для плат, зависших на [EB|#LOG:EXITBS:START], например, некоторых плат серий X58, X79, X99 и AMD 7000)',
      'ja': 'DevirtualiseMmio (ファームウェアが MMIO 領域を処理するときに競合/非互換性を解決し、システムの互換性と安定性を向上させます。多くの場合、OpenCore Debug と組み合わせて、[EB|#LOG:EXITBS:START] でスタックしているボード (一部の X58、X79、X99、および AMD 7000 シリーズ ボードなど) の MMIO をカスタマイズします)',
      'ko': 'DevirtualiseMmio(펌웨어가 MMIO 영역을 처리할 때 충돌/비호환성을 해결하여 시스템 호환성 및 안정성을 향상시킵니다. 종종 OpenCore 디버그와 결합하여 [EB|#LOG:EXITBS:START]에서 멈춘 보드(예: 일부 X58, X79, X99 및 AMD 7000 시리즈 보드)에 대해 MMIO를 사용자 정의합니다.',
      'it': 'DevirtualiseMmio (aiuta a risolvere conflitti/incompatibilità quando il firmware gestisce le regioni MMIO, migliorando la compatibilità e la stabilità del sistema. Spesso combinato con OpenCore Debug per personalizzare MMIO per schede bloccate su [EB|#LOG:EXITBS:START], ad esempio alcune schede X58, X79, X99 e AMD serie 7000)',
      'tr': 'DevirtualiseMmio(Ürün yazılımı MMIO bölgelerini işlediğinde çakışmaları/uyumsuzlukları çözmeye yardımcı olur, sistem uyumluluğunu ve kararlılığını artırır. Genellikle, [EB|#LOG:EXITBS:START] konumunda takılı kalan kartlar için MMIO\'yu özelleştirmek amacıyla OpenCore Debug ile birleştirilir, örneğin bazı X58, X79, X99 ve AMD 7000 serisi kartlar)',
      'vi': 'DevirtualiseMmio(Giúp giải quyết xung đột/không tương thích khi phần sụn xử lý các vùng MMIO, cải thiện tính tương thích và độ ổn định của hệ thống. Thường được kết hợp với OpenCore Debug để tùy chỉnh MMIO cho các bo mạch bị kẹt tại [EB|#LOG:EXITBS:Start], ví dụ: một số bo mạch dòng X58, X79, X99 và AMD 7000)',
      'pl': 'DewirtualizacjaMmio (pomaga rozwiązać konflikty/niekompatybilności, gdy oprogramowanie sprzętowe obsługuje regiony MMIO, poprawiając kompatybilność i stabilność systemu. Często w połączeniu z OpenCore Debug w celu dostosowania MMIO do płyt utkniętych w [EB|#LOG:EXITBS:START], np. niektóre płyty z serii X58, X79, X99 i AMD 7000)',
      'uk': 'DevirtualiseMmio (допомагає вирішувати конфлікти/несумісності, коли мікропрограмне забезпечення обробляє регіони MMIO, покращуючи сумісність і стабільність системи. Часто поєднується з OpenCore Debug для налаштування MMIO для плат, які застрягли на [EB|#LOG:EXITBS:START], наприклад, деякі плати серії X58, X79, X99 і AMD 7000)',
      'nl': 'DevirtualiseMmio(Helpt conflicten/incompatibiliteiten op te lossen wanneer firmware MMIO-regio\'s afhandelt, waardoor de systeemcompatibiliteit en stabiliteit wordt verbeterd. Vaak gecombineerd met OpenCore Debug om MMIO aan te passen voor boards die vastzitten op [EB|#LOG:EXITBS:START], bijvoorbeeld sommige X58-, X79-, X99- en AMD 7000-serie boards)',
      'hi': 'DevirtualiseMmio (जब फर्मवेयर MMIO क्षेत्रों को संभालता है, तो सिस्टम संगतता और स्थिरता में सुधार करते हुए टकराव/असंगतता को हल करने में मदद करता है। अक्सर [EB|#LOG:EXITBS:START] पर अटके बोर्डों के लिए MMIO को अनुकूलित करने के लिए ओपनकोर डीबग के साथ जोड़ा जाता है, उदाहरण के लिए कुछ X58, X79, X99, और AMD 7000 श्रृंखला बोर्ड)',
      'ar': 'DevirtualiseMmio (يساعد على حل التعارضات/حالات عدم التوافق عندما تتعامل البرامج الثابتة مع مناطق MMIO، مما يحسن توافق النظام واستقراره. غالبًا ما يتم دمجه مع OpenCore Debug لتخصيص MMIO للوحات العالقة عند [EB|#LOG:EXITBS:START]، على سبيل المثال بعض لوحات سلسلة X58 وX79 وX99 وAMD 7000)',
      'id': 'DevirtualiseMmio (Membantu menyelesaikan konflik/ketidakcocokan ketika firmware menangani wilayah MMIO, meningkatkan kompatibilitas dan stabilitas sistem. Sering dikombinasikan dengan OpenCore Debug untuk menyesuaikan MMIO untuk papan yang terjebak di [EB|#LOG:EXITBS:START], misalnya beberapa papan seri X58, X79, X99, dan AMD 7000)',
    },
    'Disable Power Management (DummyPowerManagement): Fixes reboot loops caused by CPU power management (e.g. AppleIntelCPUPowerManagement panic, boot logo freeze, immediate reboot after login). For Gen 4+ platforms, this is preferred over NullCpuPowerManagement.kext.': {
      'pt': 'Desativar gerenciamento de energia (DummyPowerManagement): corrige loops de reinicialização causados ​​pelo gerenciamento de energia da CPU (por exemplo, pânico AppleIntelCPUPowerManagement, congelamento do logotipo de inicialização, reinicialização imediata após login). Para plataformas Gen 4+, isso é preferível a NullCpuPowerManagement.kext.',
      'zh': '禁用电源管理 (DummyPowerManagement)：修复由 CPU 电源管理引起的重新启动循环（例如 AppleIntelCPUPowerManagement 恐慌、启动徽标冻结、登录后立即重新启动）。对于 Gen 4+ 平台，这优于 NullCpuPowerManagement.kext。',
      'zh_Hant': '停用電源管理 (DummyPowerManagement)：修復 CPU 電源管理引起的重新啟動循環（例如 AppleIntelCPUPowerManagement 恐慌、啟動徽標凍結、登入後立即重新啟動）。對於 Gen 4+ 平台，這優於 NullCpuPowerManagement.kext。',
      'es': 'Deshabilitar la administración de energía (DummyPowerManagement): corrige los bucles de reinicio causados ​​por la administración de energía de la CPU (por ejemplo, pánico de AppleIntelCPUPowerManagement, congelación del logotipo de inicio, reinicio inmediato después de iniciar sesión). Para plataformas Gen 4+, se prefiere esto a NullCpuPowerManagement.kext.',
      'de': 'Energieverwaltung deaktivieren (DummyPowerManagement): Behebt Neustartschleifen, die durch die CPU-Energieverwaltung verursacht werden (z. B. AppleIntelCPUPowerManagement-Panic, Einfrieren des Boot-Logos, sofortiger Neustart nach der Anmeldung). Für Gen 4+-Plattformen wird dies gegenüber NullCpuPowerManagement.kext bevorzugt.',
      'fr': 'Désactiver la gestion de l\'alimentation (DummyPowerManagement) : corrige les boucles de redémarrage causées par la gestion de l\'alimentation du processeur (par exemple, panique AppleIntelCPUPowerManagement, gel du logo de démarrage, redémarrage immédiat après la connexion). Pour les plates-formes Gen 4+, cette option est préférable à NullCpuPowerManagement.kext.',
      'ru': 'Отключить управление питанием (DummyPowerManagement): исправляет циклы перезагрузки, вызванные управлением питанием ЦП (например, паника AppleIntelCPUPowerManagement, зависание логотипа загрузки, немедленная перезагрузка после входа в систему). Для платформ поколения 4+ это предпочтительнее NullCpuPowerManagement.kext.',
      'ja': '電源管理を無効にする (DummyPowerManagement): CPU 電源管理によって引き起こされる再起動ループを修正します (例: AppleIntelCPUPowerManagement パニック、ブート ロゴのフリーズ、ログイン後の即時再起動)。第 4 世代以降のプラットフォームの場合、これは NullCpuPowerManagement.kext よりも優先されます。',
      'ko': '전원 관리 비활성화(DummyPowerManagement): CPU 전원 관리로 인해 발생하는 재부팅 루프를 수정합니다(예: AppleIntelCPUPowerManagement 패닉, 부팅 로고 정지, 로그인 후 즉시 재부팅). Gen 4+ 플랫폼의 경우 이는 NullCpuPowerManagement.kext보다 선호됩니다.',
      'it': 'Disabilita gestione alimentazione (DummyPowerManagement): risolve i cicli di riavvio causati dalla gestione dell\'alimentazione della CPU (ad esempio panico di AppleIntelCPUPowerManagement, blocco del logo di avvio, riavvio immediato dopo l\'accesso). Per le piattaforme Gen 4+, è preferibile rispetto a NullCpuPowerManagement.kext.',
      'tr': 'Güç Yönetimini Devre Dışı Bırak (DummyPowerManagement): CPU güç yönetiminin neden olduğu yeniden başlatma döngülerini düzeltir (örneğin, AppleIntelCPUPowerManagement paniği, önyükleme logosunun donması, oturum açtıktan sonra anında yeniden başlatma). 4. Nesil platformlarda NullCpuPowerManagement.kext yerine bu tercih edilir.',
      'vi': 'Tắt Quản lý nguồn (DummyPowerQuản lý): Khắc phục các vòng khởi động lại do quản lý nguồn CPU gây ra (ví dụ: AppleIntelCPUPowerQuản lý hoảng loạn, đóng băng logo khởi động, khởi động lại ngay lập tức sau khi đăng nhập). Đối với nền tảng Gen 4+, điều này được ưu tiên hơn NullCpuPowerQuản lý.kext.',
      'pl': 'Wyłącz zarządzanie energią (DummyPowerManagement): Naprawia pętle ponownego uruchamiania spowodowane zarządzaniem energią procesora (np. panika AppleIntelCPUPowerManagement, zawieszanie się logo startowego, natychmiastowe ponowne uruchomienie po zalogowaniu). W przypadku platform Gen 4+ jest to preferowane w porównaniu z plikiem NullCpuPowerManagement.kext.',
      'uk': 'Вимкнути керування живленням (DummyPowerManagement): виправляє цикли перезавантаження, спричинені керуванням живленням процесора (наприклад, паніка AppleIntelCPUPowerManagement, зависання логотипа завантаження, негайне перезавантаження після входу). Для платформ Gen 4+ це краще, ніж NullCpuPowerManagement.kext.',
      'nl': 'Schakel energiebeheer uit (DummyPowerManagement): Herstartlussen veroorzaakt door CPU-energiebeheer (bijvoorbeeld AppleIntelCPUPowerManagement paniek, opstartlogo vastlopen, onmiddellijk opnieuw opstarten na inloggen). Voor Gen 4+ platforms heeft dit de voorkeur boven NullCpuPowerManagement.kext.',
      'hi': 'पावर प्रबंधन अक्षम करें (डमीपावरमैनेजमेंट): सीपीयू पावर प्रबंधन के कारण होने वाले रिबूट लूप को ठीक करता है (उदाहरण के लिए AppleIntelCPUPowerManagement पैनिक, बूट लोगो फ्रीज, लॉगिन के बाद तत्काल रिबूट)। Gen 4+ प्लेटफ़ॉर्म के लिए, इसे NullCpuPowerManagement.kext की तुलना में प्राथमिकता दी जाती है।',
      'ar': 'تعطيل إدارة الطاقة (DummyPowerManagement): يعمل على إصلاح حلقات إعادة التشغيل الناتجة عن إدارة طاقة وحدة المعالجة المركزية (على سبيل المثال، ذعر AppleIntelCPUPowerManagement، وتجميد شعار التمهيد، وإعادة التشغيل الفوري بعد تسجيل الدخول). بالنسبة لمنصات Gen 4+، يُفضل هذا على NullCpuPowerManagement.kext.',
      'id': 'Nonaktifkan Manajemen Daya (DummyPowerManagement): Memperbaiki loop reboot yang disebabkan oleh manajemen daya CPU (misalnya kepanikan AppleIntelCPUPowerManagement, logo boot macet, reboot langsung setelah login). Untuk platform Gen 4+, ini lebih disukai daripada NullCpuPowerManagement.kext.',
    },
    'Disable iGPU RC6 render standby to fix NVMe kernel panic during sleep caused by RC6': {
      'pt': 'Desative o modo de espera de renderização iGPU RC6 para corrigir o pânico do kernel NVMe durante o sono causado pelo RC6',
      'zh': '禁用 iGPU RC6 渲染待机以修复 RC6 导致的睡眠期间 NVMe 内核崩溃',
      'zh_Hant': '停用 iGPU RC6 渲染待機以修復 RC6 導致的睡眠期間 NVMe 核心崩潰',
      'es': 'Deshabilite el modo de espera de procesamiento de iGPU RC6 para solucionar el pánico del kernel NVMe durante la suspensión causado por RC6',
      'de': 'Deaktivieren Sie den iGPU RC6-Render-Standby, um die durch RC6 verursachte NVMe-Kernel-Panik im Ruhezustand zu beheben',
      'fr': 'Désactivez la veille de rendu iGPU RC6 pour corriger la panique du noyau NVMe pendant le sommeil provoqué par RC6',
      'ru': 'Отключите режим ожидания рендеринга iGPU RC6, чтобы исправить панику ядра NVMe во время сна, вызванную RC6.',
      'ja': 'iGPU RC6 レンダー スタンバイを無効にして、RC6 が原因で発生するスリープ中の NVMe カーネル パニックを修正します。',
      'ko': 'iGPU RC6 렌더링 대기를 비활성화하여 RC6으로 인한 절전 모드 중 NVMe 커널 패닉을 수정합니다.',
      'it': 'Disabilita lo standby del rendering iGPU RC6 per correggere il panico del kernel NVMe durante la sospensione causato da RC6',
      'tr': 'Uyku sırasında RC6\'nın neden olduğu NVMe çekirdek paniğini düzeltmek için iGPU RC6 oluşturma beklemesini devre dışı bırakın',
      'vi': 'Tắt chế độ chờ kết xuất của iGPU RC6 để khắc phục tình trạng hoảng loạn kernel NVMe trong khi ngủ do RC6 gây ra',
      'pl': 'Wyłącz tryb gotowości renderowania iGPU RC6, aby naprawić panikę jądra NVMe podczas uśpienia spowodowaną przez RC6',
      'uk': 'Вимкніть iGPU RC6 в режимі очікування, щоб усунути паніку ядра NVMe під час сну, спричинену RC6',
      'nl': 'Schakel iGPU RC6 render standby uit om NVMe-kernelpaniek tijdens de slaap veroorzaakt door RC6 te verhelpen',
      'hi': 'RC6 के कारण नींद के दौरान NVMe कर्नेल पैनिक को ठीक करने के लिए iGPU RC6 रेंडर स्टैंडबाय को अक्षम करें',
      'ar': 'قم بتعطيل وضع الاستعداد لـ iGPU RC6 لإصلاح ذعر kernel NVMe أثناء النوم الناجم عن RC6',
      'id': 'Nonaktifkan iGPU RC6 render standby untuk memperbaiki kepanikan kernel NVMe saat tidur yang disebabkan oleh RC6',
    },
    'Disables AMD/ATI GPU acceleration (useful for recovery/debugging when OCLP patches fail to boot)': {
      'pt': 'Desativa a aceleração de GPU AMD/ATI (útil para recuperação/depuração quando os patches OCLP falham na inicialização)',
      'zh': '禁用 AMD/ATI GPU 加速（对于 OCLP 补丁无法启动时的恢复/调试很有用）',
      'zh_Hant': '停用 AMD/ATI GPU 加速（對於 OCLP 補丁無法啟動時的復原/偵錯很有用）',
      'es': 'Desactiva la aceleración de GPU AMD/ATI (útil para recuperación/depuración cuando los parches OCLP no se inician)',
      'de': 'Deaktiviert die AMD/ATI-GPU-Beschleunigung (nützlich für Wiederherstellung/Debugging, wenn OCLP-Patches nicht gestartet werden können)',
      'fr': 'Désactive l\'accélération GPU AMD/ATI (utile pour la récupération/le débogage lorsque les correctifs OCLP ne démarrent pas)',
      'ru': 'Отключает ускорение графического процессора AMD/ATI (полезно для восстановления/отладки, когда исправления OCLP не загружаются)',
      'ja': 'AMD/ATI GPU アクセラレーションを無効にします (OCLP パッチが起動に失敗した場合のリカバリ/デバッグに役立ちます)',
      'ko': 'AMD/ATI GPU 가속 비활성화(OCLP 패치가 부팅되지 않을 때 복구/디버깅에 유용함)',
      'it': 'Disabilita l\'accelerazione GPU AMD/ATI (utile per il ripristino/debug quando le patch OCLP non si avviano)',
      'tr': 'AMD/ATI GPU hızlandırmayı devre dışı bırakır (OCLP yamaları önyükleme yapmadığında kurtarma/hata ayıklama için kullanışlıdır)',
      'vi': 'Vô hiệu hóa khả năng tăng tốc GPU AMD/ATI (hữu ích cho việc khôi phục/gỡ lỗi khi các bản vá OCLP không khởi động được)',
      'pl': 'Wyłącza akcelerację procesora graficznego AMD/ATI (przydatne do odzyskiwania/debugowania, gdy poprawki OCLP nie uruchamiają się)',
      'uk': 'Вимикає прискорення GPU AMD/ATI (корисно для відновлення/налагодження, коли патчі OCLP не завантажуються)',
      'nl': 'Schakelt AMD/ATI GPU-versnelling uit (handig voor herstel/foutopsporing wanneer OCLP-patches niet opstarten)',
      'hi': 'AMD/ATI GPU त्वरण को अक्षम करता है (OCLP पैच बूट होने में विफल होने पर पुनर्प्राप्ति/डीबगिंग के लिए उपयोगी)',
      'ar': 'تعطيل تسريع AMD/ATI GPU (مفيد للاسترداد/تصحيح الأخطاء عند فشل تشغيل تصحيحات OCLP)',
      'id': 'Menonaktifkan akselerasi GPU AMD/ATI (berguna untuk pemulihan/debugging ketika patch OCLP gagal melakukan booting)',
    },
    'Disables AMFI (Apple Mobile File Integrity). Required for patching newer GPUs or legacy WiFi (mutually exclusive with amfi_get_out_of_my_way=0x1; requires SIP disabled)': {
      'pt': 'Desativa AMFI (Apple Mobile File Integrity). Necessário para corrigir GPUs mais recentes ou WiFi legado (mutuamente exclusivo com amfi_get_out_of_my_way=0x1; requer SIP desativado)',
      'zh': '禁用 AMFI（Apple 移动文件完整性）。修补较新的 GPU 或旧版 WiFi 所需（与 amfi_get_out_of_my_way=0x1 互斥；需要禁用 SIP）',
      'zh_Hant': '停用 AMFI（Apple 行動檔案完整性）。修補較新的 GPU 或舊版 WiFi 所需（與 amfi_get_out_of_my_way=0x1 互斥；需停用 SIP）',
      'es': 'Desactiva AMFI (Integridad de archivos móviles de Apple). Requerido para parchear GPU más nuevas o WiFi heredado (se excluyen mutuamente con amfi_get_out_of_my_way=0x1; requiere SIP deshabilitado)',
      'de': 'Deaktiviert AMFI (Apple Mobile File Integrity). Erforderlich für das Patchen neuer GPUs oder veralteter WLANs (schließt sich gegenseitig aus mit amfi_get_out_of_my_way=0x1; erfordert SIP deaktiviert)',
      'fr': 'Désactive AMFI (Apple Mobile File Integrity). Requis pour corriger les GPU plus récents ou le WiFi existant (mutuellement exclusif avec amfi_get_out_of_my_way=0x1 ; nécessite SIP désactivé)',
      'ru': 'Отключает AMFI (целостность файлов Apple Mobile). Требуется для исправления новых графических процессоров или устаревшего Wi-Fi (взаимоисключающе с amfi_get_out_of_my_way=0x1; требует отключения SIP)',
      'ja': 'AMFI (Apple モバイル ファイル整合性) を無効にします。新しい GPU または従来の WiFi にパッチを適用するために必要です (amfi_get_out_of_my_way=0x1 と相互に排他的です。SIP を無効にする必要があります)',
      'ko': 'AMFI(Apple 모바일 파일 무결성)를 비활성화합니다. 최신 GPU 또는 기존 WiFi 패치에 필요(amfi_get_out_of_my_way=0x1과 상호 배타적, SIP 비활성화 필요)',
      'it': 'Disabilita AMFI (Apple Mobile File Integrity). Necessario per l\'applicazione di patch alle GPU più recenti o al Wi-Fi legacy (si escludono a vicenda con amfi_get_out_of_my_way=0x1; richiede SIP disabilitato)',
      'tr': 'AMFI\'yi (Apple Mobil Dosya Bütünlüğü) devre dışı bırakır. Daha yeni GPU\'lara veya eski Wi-Fi\'ye yama uygulamak için gereklidir (amfi_get_out_of_my_way=0x1 ile karşılıklı olarak özeldir; SIP\'nin devre dışı bırakılmasını gerektirir)',
      'vi': 'Tắt AMFI (Tính toàn vẹn tệp di động của Apple). Cần thiết để vá các GPU mới hơn hoặc WiFi cũ (loại trừ lẫn nhau với amfi_get_out_of_my_way=0x1; yêu cầu tắt SIP)',
      'pl': 'Wyłącza AMFI (integralność plików mobilnych Apple). Wymagane do łatania nowszych procesorów graficznych lub starszych Wi-Fi (wzajemnie wykluczające się z amfi_get_out_of_my_way=0x1; wymaga wyłączonego protokołu SIP)',
      'uk': 'Вимикає AMFI (Apple Mobile File Integrity). Необхідно для виправлення нових графічних процесорів або застарілих Wi-Fi (взаємовиключні з amfi_get_out_of_my_way=0x1; потрібен SIP вимкнений)',
      'nl': 'Schakelt AMFI (Apple Mobile File Integrity) uit. Vereist voor het patchen van nieuwere GPU\'s of oudere WiFi (mutueel exclusief met amfi_get_out_of_my_way=0x1; vereist SIP uitgeschakeld)',
      'hi': 'AMFI (Apple मोबाइल फ़ाइल इंटीग्रिटी) को अक्षम करता है। नए जीपीयू या लीगेसी वाईफाई को पैच करने के लिए आवश्यक है (amfi_get_out_of_my_way=0x1 के साथ परस्पर अनन्य; SIP अक्षम की आवश्यकता है)',
      'ar': 'تعطيل AMFI (سلامة ملفات Apple Mobile). مطلوب لتصحيح وحدات معالجة الرسومات الأحدث أو شبكة WiFi القديمة (ينحصر كل منهما بشكل متبادل مع amfi_get_out_of_my_way=0x1؛ ويتطلب تعطيل SIP)',
      'id': 'Menonaktifkan AMFI (Integritas File Seluler Apple). Diperlukan untuk menambal GPU yang lebih baru atau WiFi lama (saling eksklusif dengan amfi_get_out_of_my_way=0x1; memerlukan SIP dinonaktifkan)',
    },
    'Disables AMFI for legacy GPUs (e.g. GT 240) and legacy WiFi (mutually exclusive with amfi=0x80; requires SIP disabled)': {
      'pt': 'Desativa AMFI para GPUs legadas (por exemplo, GT 240) e WiFi legado (mutuamente exclusivo com amfi=0x80; requer SIP desativado)',
      'zh': '禁用旧版 GPU（例如 GT 240）和旧版 WiFi 的 AMFI（与 amfi=0x80 互斥；需要禁用 SIP）',
      'zh_Hant': '停用舊版 GPU（例如 GT 240）和舊版 WiFi 的 AMFI（與 amfi=0x80 互斥；需停用 SIP）',
      'es': 'Deshabilita AMFI para GPU heredadas (por ejemplo, GT 240) y WiFi heredado (mutuamente excluyentes con amfi=0x80; requiere SIP deshabilitado)',
      'de': 'Deaktiviert AMFI für ältere GPUs (z. B. GT 240) und älteres WLAN (schließt sich gegenseitig aus mit amfi=0x80; erfordert SIP deaktiviert)',
      'fr': 'Désactive AMFI pour les GPU existants (par exemple GT 240) et le WiFi existant (mutuellement exclusifs avec amfi=0x80 ; nécessite que SIP soit désactivé)',
      'ru': 'Отключает AMFI для устаревших графических процессоров (например, GT 240) и устаревшего Wi-Fi (взаимоисключающе с amfi=0x80; требует отключения SIP)',
      'ja': 'レガシー GPU (GT 240 など) とレガシー WiFi の AMFI を無効にします (amfi=0x80 と相互に排他的です。SIP を無効にする必要があります)',
      'ko': '레거시 GPU(예: GT 240) 및 레거시 WiFi(amfi=0x80과 상호 배타적, SIP 비활성화 필요)에 대해 AMFI를 비활성화합니다.',
      'it': 'Disabilita AMFI per GPU legacy (ad esempio GT 240) e WiFi legacy (si escludono a vicenda con amfi=0x80; richiede SIP disabilitato)',
      'tr': 'Eski GPU\'lar (örn. GT 240) ve eski Wi-Fi (amfi=0x80 ile karşılıklı olarak özel; SIP\'nin devre dışı bırakılmasını gerektirir) için AMFI\'yi devre dışı bırakır',
      'vi': 'Tắt AMFI cho GPU cũ (ví dụ: GT 240) và WiFi cũ (loại trừ lẫn nhau với amfi=0x80; yêu cầu tắt SIP)',
      'pl': 'Wyłącza AMFI dla starszych procesorów graficznych (np. GT 240) i starszych Wi-Fi (wzajemnie wykluczające się z amfi=0x80; wymaga wyłączenia SIP)',
      'uk': 'Вимикає AMFI для застарілих графічних процесорів (наприклад, GT 240) і застарілого WiFi (взаємовиключні з amfi=0x80; потрібен вимкнений SIP)',
      'nl': 'Schakelt AMFI uit voor oudere GPU\'s (bijv. GT 240) en oudere WiFi (mutueel exclusief met amfi=0x80; vereist SIP uitgeschakeld)',
      'hi': 'पुराने GPU (उदाहरण के लिए GT 240) और पुराने वाईफाई के लिए AMFI को अक्षम करता है (amfi=0x80 के साथ परस्पर अनन्य; SIP को अक्षम करने की आवश्यकता है)',
      'ar': 'تعطيل AMFI لوحدات معالجة الرسومات القديمة (على سبيل المثال GT 240) وWiFi القديمة (حصريًا بشكل متبادل مع amfi=0x80؛ يتطلب تعطيل SIP)',
      'id': 'Menonaktifkan AMFI untuk GPU lawas (misalnya GT 240) dan WiFi lawas (saling eksklusif dengan amfi=0x80; memerlukan SIP dinonaktifkan)',
    },
    'Disables Apple Graphics Firmware loading to avoid boot hangs caused by firmware load failures (Intel iGPU only)': {
      'pt': 'Desativa o carregamento do firmware Apple Graphics para evitar travamentos de inicialização causados ​​por falhas no carregamento do firmware (somente Intel iGPU)',
      'zh': '禁用 Apple 图形固件加载以避免因固件加载失败而导致启动挂起（仅限 Intel iGPU）',
      'zh_Hant': '停用 Apple 圖形韌體載入以避免因韌體載入失敗而導致啟動掛起（僅限 Intel iGPU）',
      'es': 'Deshabilita la carga del firmware de gráficos de Apple para evitar bloqueos de arranque causados ​​por fallas en la carga del firmware (solo Intel iGPU)',
      'de': 'Deaktiviert das Laden der Apple-Grafik-Firmware, um Boot-Hänge aufgrund von Firmware-Ladefehlern zu vermeiden (nur Intel iGPU).',
      'fr': 'Désactive le chargement du micrologiciel Apple Graphics pour éviter les blocages de démarrage causés par des échecs de chargement du micrologiciel (Intel iGPU uniquement)',
      'ru': 'Отключает загрузку прошивки Apple Graphics, чтобы избежать зависаний загрузки, вызванных сбоями загрузки прошивки (только Intel iGPU)',
      'ja': 'Apple グラフィックス ファームウェアのロードを無効にして、ファームウェアのロード失敗によるブートハングを回避します (Intel iGPU のみ)',
      'ko': '펌웨어 로드 오류로 인한 부팅 중단을 방지하기 위해 Apple 그래픽 펌웨어 로드를 비활성화합니다(Intel iGPU만 해당).',
      'it': 'Disabilita il caricamento del firmware grafico Apple per evitare blocchi di avvio causati da errori di caricamento del firmware (solo Intel iGPU)',
      'tr': 'Firmware yükleme hatalarından kaynaklanan önyükleme takılmalarını önlemek için Apple Graphics Firmware yüklemesini devre dışı bırakır (yalnızca Intel iGPU)',
      'vi': 'Tắt tính năng tải chương trình cơ sở Apple Graphics để tránh tình trạng treo khởi động do lỗi tải chương trình cơ sở (chỉ dành cho Intel iGPU)',
      'pl': 'Wyłącza ładowanie oprogramowania sprzętowego Apple Graphics, aby uniknąć zawieszania się rozruchu spowodowanego błędami ładowania oprogramowania sprzętowego (tylko Intel iGPU)',
      'uk': 'Вимикає завантаження прошивки Apple Graphics, щоб уникнути зависань під час завантаження, спричинених помилками завантаження прошивки (лише Intel iGPU)',
      'nl': 'Schakelt het laden van Apple Graphics Firmware uit om te voorkomen dat het opstarten vastloopt als gevolg van fouten bij het laden van de firmware (alleen Intel iGPU)',
      'hi': 'फ़र्मवेयर लोड विफलताओं के कारण होने वाले बूट हैंग से बचने के लिए Apple ग्राफ़िक्स फ़र्मवेयर लोडिंग को अक्षम करता है (केवल Intel iGPU)',
      'ar': 'تعطيل تحميل البرامج الثابتة لرسومات Apple لتجنب توقف التمهيد الناتج عن فشل تحميل البرامج الثابتة (Intel iGPU فقط)',
      'id': 'Menonaktifkan pemuatan Firmware Apple Graphics untuk menghindari boot hang yang disebabkan oleh kegagalan pemuatan firmware (khusus Intel iGPU)',
    },
    'Disables Intel iGPU (recommended when iGPU is unsupported or causes panics)': {
      'pt': 'Desativa o Intel iGPU (recomendado quando o iGPU não é compatível ou causa pânico)',
      'zh': '禁用 Intel iGPU（当 iGPU 不受支持或导致紧急情况时推荐）',
      'zh_Hant': '停用 Intel iGPU（當 iGPU 不受支援或導致緊急情況時建議）',
      'es': 'Desactiva Intel iGPU (recomendado cuando la iGPU no es compatible o causa pánico)',
      'de': 'Deaktiviert Intel iGPU (empfohlen, wenn iGPU nicht unterstützt wird oder Panik verursacht)',
      'fr': 'Désactive Intel iGPU (recommandé lorsque l\'iGPU n\'est pas pris en charge ou provoque des paniques)',
