    'Disables Kernel Address Space Layout Randomization (KASLR) to fix early boot crashes caused by memory conflicts': {
      'pt': 'Desativa a Randomização de Layout de Espaço de Endereço do Kernel (KASLR) para corrigir falhas iniciais de inicialização causadas por conflitos de memória',
      'zh': '禁用内核地址空间布局随机化 (KASLR) 以修复内存冲突导致的早期启动崩溃',
      'zh_Hant': '停用核心位址空間佈局隨機化 (KASLR) 以修復記憶體衝突導致的早期啟動崩潰',
      'es': 'Deshabilita la aleatorización del diseño del espacio de direcciones del kernel (KASLR) para corregir fallas de arranque tempranas causadas por conflictos de memoria',
      'de': 'Deaktiviert die Kernel Address Space Layout Randomization (KASLR), um frühe Startabstürze aufgrund von Speicherkonflikten zu beheben',
      'fr': 'Désactive la randomisation de la disposition de l\'espace d\'adressage du noyau (KASLR) pour corriger les plantages de démarrage précoces causés par des conflits de mémoire.',
      'ru': 'Отключает рандомизацию макета адресного пространства ядра (KASLR) для исправления сбоев при ранней загрузке, вызванных конфликтами памяти.',
      'ja': 'カーネル アドレス空間レイアウトのランダム化 (KASLR) を無効にして、メモリ競合による初期ブート クラッシュを修正します。',
      'ko': '메모리 충돌로 인한 초기 부팅 충돌을 해결하기 위해 KASLR(Kernel Address Space Layout Randomization)을 비활성화합니다.',
      'it': 'Disabilita la randomizzazione del layout dello spazio degli indirizzi del kernel (KASLR) per correggere i primi arresti anomali di avvio causati da conflitti di memoria',
      'tr': 'Bellek çakışmalarından kaynaklanan erken önyükleme çökmelerini düzeltmek için Çekirdek Adres Alanı Düzeni Rastgeleleştirmesini (KASLR) devre dışı bırakır',
      'vi': 'Tắt Ngẫu nhiên bố cục không gian địa chỉ hạt nhân (KASLR) để khắc phục sự cố khởi động sớm do xung đột bộ nhớ',
      'pl': 'Wyłącza losowość układu przestrzeni adresowej jądra (KASLR), aby naprawić awarie wczesnego uruchamiania spowodowane konfliktami pamięci',
      'uk': 'Вимикає рандомізацію макету адресного простору ядра (KASLR), щоб виправити збої раннього завантаження, спричинені конфліктами пам’яті',
      'nl': 'Schakelt Kernel Address Space Layout Randomization (KASLR) uit om vroegtijdige opstartcrashes veroorzaakt door geheugenconflicten te verhelpen',
      'hi': 'मेमोरी विवादों के कारण शुरुआती बूट क्रैश को ठीक करने के लिए कर्नेल एड्रेस स्पेस लेआउट रैंडमाइजेशन (KASLR) को अक्षम करता है',
      'ar': 'تعطيل التوزيع العشوائي لتخطيط مساحة عنوان Kernel (KASLR) لإصلاح أعطال التمهيد المبكرة الناجمة عن تعارضات الذاكرة',
      'id': 'Menonaktifkan Pengacakan Tata Letak Ruang Alamat Kernel (KASLR) untuk memperbaiki kerusakan boot awal yang disebabkan oleh konflik memori',
