    'Disables iGPU telemetry module loading during boot; prevents boot hangs on certain laptops and Chromebooks (Intel 6th Gen+)': {
      'pt': 'Desativa o carregamento do módulo de telemetria iGPU durante a inicialização; evita travamentos de inicialização em determinados laptops e Chromebooks (Intel 6ª geração +)',
