      'ja': '起動中の iGPU テレメトリ モジュールの読み込みを無効にします。特定のラップトップおよび Chromebook (Intel 第 6 世代以降) でのブートハングを防止します。',
      'ko': '부팅 중 iGPU 원격 측정 모듈 로딩을 비활성화합니다. 특정 노트북 및 Chromebook(Intel 6세대+)에서 부팅 중단을 방지합니다.',
