      'pl': 'Wyłącza ładowanie modułu telemetrycznego iGPU podczas rozruchu; zapobiega zawieszaniu się rozruchu na niektórych laptopach i Chromebookach (Intel 6. generacji+)',
      'uk': 'Вимикає завантаження модуля телеметрії iGPU під час завантаження; запобігає зависанням завантаження на певних ноутбуках і Chromebook (Intel 6-го покоління+)',
