    'Emulates Apple SMC functionality on non-Apple hardware, managing fans, thermal sensors, power management, and battery status': {
      'pt': 'Emula a funcionalidade Apple SMC em hardware que não seja da Apple, gerenciando ventiladores, sensores térmicos, gerenciamento de energia e status da bateria',
      'zh': '在非 Apple 硬件上模拟 Apple SMC 功能，管理风扇、热传感器、电源管理和电池状态',
      'zh_Hant': '在非 Apple 硬體上模擬 Apple SMC 功能，管理風扇、熱感應器、電源管理和電池狀態',
      'es': 'Emula la funcionalidad Apple SMC en hardware que no es Apple, administrando ventiladores, sensores térmicos, administración de energía y estado de la batería.',
      'de': 'Emuliert die Apple SMC-Funktionalität auf Nicht-Apple-Hardware und verwaltet Lüfter, Temperatursensoren, Energieverwaltung und Batteriestatus',
      'fr': 'Émule la fonctionnalité Apple SMC sur du matériel non Apple, gérant les ventilateurs, les capteurs thermiques, la gestion de l\'alimentation et l\'état de la batterie.',
      'ru': 'Эмулирует функциональность Apple SMC на оборудовании сторонних производителей, управляет вентиляторами, термодатчиками, управлением питанием и состоянием батареи.',
      'ja': 'Apple 以外のハードウェア上で Apple SMC 機能をエミュレートし、ファン、温度センサー、電源管理、バッテリー状態を管理します。',
      'ko': 'Apple 이외의 하드웨어에서 Apple SMC 기능을 에뮬레이트하여 팬, 열 센서, 전원 관리 및 배터리 상태를 관리합니다.',
      'it': 'Emula la funzionalità Apple SMC su hardware non Apple, gestendo ventole, sensori termici, gestione dell\'alimentazione e stato della batteria',
      'tr': 'Apple dışı donanımlarda, fanların, termal sensörlerin, güç yönetiminin ve pil durumunun yönetilmesinde Apple SMC işlevselliğini taklit eder',
      'vi': 'Mô phỏng chức năng Apple SMC trên phần cứng không phải của Apple, quản lý quạt, cảm biến nhiệt, quản lý nguồn và trạng thái pin',
      'pl': 'Emuluje funkcjonalność Apple SMC na sprzęcie innych firm, zarządzając wentylatorami, czujnikami termicznymi, zarządzaniem energią i stanem baterii',
      'uk': 'Емулює функції Apple SMC на апаратному забезпеченні сторонніх виробників, керуючи вентиляторами, температурними датчиками, керуванням живленням і станом акумулятора',
