      'ar': 'يحاكي وظائف Apple SMC على الأجهزة غير التابعة لشركة Apple، وإدارة المراوح، وأجهزة الاستشعار الحرارية، وإدارة الطاقة، وحالة البطارية',
      'id': 'Mengemulasi fungsionalitas Apple SMC pada perangkat keras non-Apple, mengelola kipas, sensor termal, manajemen daya, dan status baterai',
    },
    'Enable \'UEFI->Quirks->ReleaseUsbOwnership\' quirk to release USB controller ownership from firmware. Useful for OEM boards (e.g. some H110, B150, B250, Q270) where USB freezes on boot or keyboard/mouse fails to respond.': {
      'pt': 'Habilite a peculiaridade \'UEFI-> Quirks-> ReleaseUsbOwnership\' para liberar a propriedade do controlador USB do firmware. Útil para placas OEM (por exemplo, algumas H110, B150, B250, Q270) onde o USB congela na inicialização ou o teclado/mouse não responde.',
      'zh': '启用“UEFI->Quirks->ReleaseUsbOwnership”怪癖以从固件中释放 USB 控制器所有权。对于 USB 在启动时冻结或键盘/鼠标无法响应的 OEM 主板（例如某些 H110、B150、B250、Q270）很有用。',
      'zh_Hant': '啟用「UEFI->Quirks->ReleaseUsbOwnership」怪癖以從韌體中釋放 USB 控制器所有權。對於 USB 在啟動時凍結或鍵盤/滑鼠無法回應的 OEM 主機板（例如某些 H110、B150、B250、Q270）很有用。',
      'es': 'Habilite la peculiaridad \'UEFI->Quirks->ReleaseUsbOwnership\' para liberar la propiedad del controlador USB del firmware. Útil para placas OEM (por ejemplo, algunas H110, B150, B250, Q270) donde el USB se congela durante el arranque o el teclado/ratón no responde.',
      'de': 'Aktivieren Sie die Eigenart „UEFI->Quirks->ReleaseUsbOwnership“, um den Besitz des USB-Controllers von der Firmware freizugeben. Nützlich für OEM-Boards (z. B. einige H110, B150, B250, Q270), bei denen USB beim Booten einfriert oder Tastatur/Maus nicht reagiert.',
      'fr': 'Activez la bizarrerie « UEFI->Quirks->ReleaseUsbOwnership » pour libérer la propriété du contrôleur USB du micrologiciel. Utile pour les cartes OEM (par exemple certains H110, B150, B250, Q270) où l\'USB se bloque au démarrage ou où le clavier/souris ne répond pas.',
      'ru': 'Включите функцию «UEFI->Quirks->ReleaseUsbOwnership», чтобы освободить владение USB-контроллером от прошивки. Полезно для плат OEM (например, некоторых H110, B150, B250, Q270), где USB зависает при загрузке или клавиатура/мышь не отвечает.',
      'ja': '「UEFI->Quirks->ReleaseUsbOwnership」Quirk を有効にして、USB コントローラーの所有権をファームウェアから解放します。 USB が起動時にフリーズしたり、キーボード/マウスが応答しなくなったりする OEM ボード (一部の H110、B150、B250、Q270 など) に役立ちます。',
      'ko': '펌웨어에서 USB 컨트롤러 소유권을 해제하려면 \'UEFI->Quirks->ReleaseUsbOwnership\' 특수 기능을 활성화하세요. 부팅 시 USB가 멈추거나 키보드/마우스가 응답하지 않는 OEM 보드(예: 일부 H110, B150, B250, Q270)에 유용합니다.',
      'it': 'Abilita il quirk "UEFI->Quirks->ReleaseUsbOwnership" per rilasciare la proprietà del controller USB dal firmware. Utile per schede OEM (ad esempio alcune H110, B150, B250, Q270) in cui l\'USB si blocca all\'avvio o la tastiera/mouse non risponde.',
      'tr': 'Firmware\'den USB denetleyici sahipliğini serbest bırakmak için \'UEFI->Quirks->ReleaseUsbOwnership\' özelliğini etkinleştirin. USB\'nin önyükleme sırasında donduğu veya klavye/farenin yanıt vermediği OEM kartları (örneğin bazı H110, B150, B250, Q270) için kullanışlıdır.',
      'vi': 'Kích hoạt giải pháp \'UEFI->Quirks->ReleaseUsbOwnership\' để giải phóng quyền sở hữu bộ điều khiển USB khỏi chương trình cơ sở. Hữu ích cho các bo mạch OEM (ví dụ: một số H110, B150, B250, Q270) trong đó USB bị treo khi khởi động hoặc bàn phím/chuột không phản hồi.',
      'pl': 'Włącz dziwactwo „UEFI->Quirks->ReleaseUsbOwnership”, aby zwolnić własność kontrolera USB z oprogramowania sprzętowego. Przydatne w przypadku płyt OEM (np. niektórych H110, B150, B250, Q270), gdzie USB zawiesza się podczas uruchamiania lub klawiatura/mysz nie odpowiada.',
      'uk': 'Увімкніть параметр «UEFI->Quirks->ReleaseUsbOwnership», щоб звільнити право власності на контролер USB із мікропрограми. Корисно для плат OEM (наприклад, деяких H110, B150, B250, Q270), де USB зависає під час завантаження або клавіатура/миша не відповідають.',
      'nl': 'Schakel \'UEFI->Quirks->ReleaseUsbOwnership\' in om het eigendom van de USB-controller vrij te geven van de firmware. Handig voor OEM-kaarten (bijvoorbeeld sommige H110, B150, B250, Q270) waarbij USB vastloopt tijdens het opstarten of toetsenbord/muis niet reageert.',
      'hi': 'फर्मवेयर से USB नियंत्रक स्वामित्व को मुक्त करने के लिए \'UEFI->Quirks->ReleaseUsbOwnership\' क्विर्क सक्षम करें। OEM बोर्डों के लिए उपयोगी (उदाहरण के लिए कुछ H110, B150, B250, Q270) जहां USB बूट पर फ़्रीज़ हो जाता है या कीबोर्ड/माउस प्रतिक्रिया देने में विफल रहता है।',
      'ar': 'قم بتمكين الميزة "UEFI->Quirks->ReleaseUsbOwnership" لتحرير ملكية وحدة تحكم USB من البرامج الثابتة. مفيد للوحات OEM (على سبيل المثال بعض H110، B150، B250، Q270) حيث يتجمد USB عند التمهيد أو فشل لوحة المفاتيح/الماوس في الاستجابة.',
      'id': 'Aktifkan kekhasan \'UEFI->Quirks->ReleaseUsbOwnership\' untuk melepaskan kepemilikan pengontrol USB dari firmware. Berguna untuk papan OEM (misalnya beberapa H110, B150, B250, Q270) di mana USB macet saat boot atau keyboard/mouse gagal merespons.',
    },
