    'EnableWriteUnprotector(Recommended on firmware without Memory Attribute Table (MAT) support, especially OEM firmware. Removes write protection from CR0 register during execution to allow proper NVRAM writing. Typically used for pre-8th Gen platforms)': {
      'pt': 'EnableWriteUnprotector (Recomendado em firmware sem suporte a Memory Attribute Table (MAT), especialmente firmware OEM. Remove a proteção contra gravação do registro CR0 durante a execução para permitir a gravação adequada de NVRAM. Normalmente usado para plataformas anteriores à 8ª geração)',
      'zh': 'EnableWriteUnprotector（建议在不支持内存属性表 (MAT) 的固件上使用，尤其是 OEM 固件。在执行期间删除 CR0 寄存器的写保护，以允许正确的 NVRAM 写入。通常用于第 8 代之前的平台）',
      'zh_Hant': 'EnableWriteUnprotector（建議在不支援記憶體屬性表 (MAT) 的韌體上使用，尤其是 OEM 韌體。在執行期間刪除 CR0 暫存器的寫入保護，以允許正確的 NVRAM 寫入。通常用於第 8 代之前的平台）',
      'es': 'EnableWriteUnprotector (recomendado en firmware sin compatibilidad con la tabla de atributos de memoria (MAT), especialmente firmware OEM. Elimina la protección contra escritura del registro CR0 durante la ejecución para permitir una escritura NVRAM adecuada. Generalmente se usa para plataformas anteriores a la octava generación)',
      'de': 'EnableWriteUnprotector (Empfohlen für Firmware ohne MAT-Unterstützung (Memory Attribute Table), insbesondere OEM-Firmware. Entfernt den Schreibschutz vom CR0-Register während der Ausführung, um ordnungsgemäßes NVRAM-Schreiben zu ermöglichen. Wird normalerweise für Plattformen vor der 8. Generation verwendet.)',
      'fr': 'EnableWriteUnprotector (recommandé sur les micrologiciels sans prise en charge de la table d\'attributs de mémoire (MAT), en particulier le micrologiciel OEM. Supprime la protection en écriture du registre CR0 pendant l\'exécution pour permettre une écriture NVRAM appropriée. Généralement utilisé pour les plates-formes antérieures à la 8e génération)',
      'ru': 'EnableWriteUnprotector (рекомендуется для прошивок без поддержки таблицы атрибутов памяти (MAT), особенно для прошивок OEM. Удаляет защиту от записи из регистра CR0 во время выполнения, чтобы обеспечить правильную запись NVRAM. Обычно используется для платформ до 8-го поколения)',
      'ja': 'EnableWriteUnprotector (メモリ属性テーブル (MAT) サポートのないファームウェア、特に OEM ファームウェアで推奨されます。実行中に CR0 レジスタから書き込み保護を削除して、適切な NVRAM 書き込みを可能にします。通常、第 8 世代より前のプラットフォームで使用されます)',
      'ko': 'EnableWriteUnprotector(MAT(메모리 속성 테이블)을 지원하지 않는 펌웨어, 특히 OEM 펌웨어에 권장됩니다. 실행 중에 CR0 레지스터에서 쓰기 보호를 제거하여 적절한 NVRAM 쓰기를 허용합니다. 일반적으로 8세대 이전 플랫폼에 사용됨)',
      'it': 'EnableWriteUnprotector (consigliato su firmware senza supporto Memory Attribute Table (MAT), in particolare firmware OEM. Rimuove la protezione da scrittura dal registro CR0 durante l\'esecuzione per consentire la corretta scrittura NVRAM. Tipicamente utilizzato per piattaforme precedenti all\'ottava generazione)',
      'tr': 'EnableWriteUnprotector(Bellek Öznitelik Tablosu (MAT) desteği olmayan bellenimde, özellikle de OEM belleniminde önerilir. Uygun NVRAM yazmaya izin vermek için yürütme sırasında CR0 kaydından yazma korumasını kaldırır. Tipik olarak 8. Nesil öncesi platformlar için kullanılır)',
      'vi': 'EnableWriteUnprotector(Được khuyến nghị trên chương trình cơ sở không hỗ trợ Bảng thuộc tính bộ nhớ (MAT), đặc biệt là chương trình cơ sở OEM. Loại bỏ tính năng bảo vệ ghi khỏi thanh ghi CR0 trong khi thực thi để cho phép ghi NVRAM thích hợp. Thường được sử dụng cho các nền tảng trước Thế hệ thứ 8)',
      'pl': 'EnableWriteUnprotector (zalecane w przypadku oprogramowania sprzętowego bez obsługi tablicy atrybutów pamięci (MAT), zwłaszcza oprogramowania OEM. Usuwa ochronę przed zapisem z rejestru CR0 podczas wykonywania, aby umożliwić prawidłowy zapis NVRAM. Zwykle używane na platformach wcześniejszych niż 8. generacji)',
      'uk': 'EnableWriteUnprotector (рекомендується для вбудованого програмного забезпечення без підтримки таблиці атрибутів пам’яті (MAT), особливо мікропрограмного забезпечення OEM. Знімає захист від запису з регістра CR0 під час виконання, щоб забезпечити належний запис NVRAM. Зазвичай використовується для платформ до 8-го покоління)',
      'nl': 'EnableWriteUnprotector (aanbevolen voor firmware zonder ondersteuning voor Memory Attribute Table (MAT), vooral OEM-firmware. Verwijdert de schrijfbeveiliging uit het CR0-register tijdens uitvoering om correct NVRAM-schrijven mogelijk te maken. Meestal gebruikt voor platforms van vóór de 8e generatie)',
      'hi': 'EnableWriteUnprotector (मेमोरी एट्रीब्यूट टेबल (MAT) समर्थन के बिना फर्मवेयर पर अनुशंसित, विशेष रूप से OEM फर्मवेयर। उचित NVRAM लेखन की अनुमति देने के लिए निष्पादन के दौरान CR0 रजिस्टर से लेखन सुरक्षा हटा देता है। आमतौर पर प्री-8 वीं पीढ़ी के प्लेटफार्मों के लिए उपयोग किया जाता है)',
      'ar': 'EnableWriteUnprotector (يوصى به على البرامج الثابتة دون دعم جدول سمات الذاكرة (MAT)، وخاصة البرامج الثابتة الخاصة بشركة OEM. يزيل الحماية ضد الكتابة من سجل CR0 أثناء التنفيذ للسماح بالكتابة المناسبة لذاكرة NVRAM. يُستخدم عادةً لمنصات الجيل ما قبل الثامن)',
      'id': 'EnableWriteUnprotector (Direkomendasikan pada firmware tanpa dukungan Memory Attribute Table (MAT), terutama firmware OEM. Menghapus perlindungan penulisan dari register CR0 selama eksekusi untuk memungkinkan penulisan NVRAM yang tepat. Biasanya digunakan untuk platform sebelum Generasi ke-8)',
    },
    'Enables AMFIPass.kext in newer macOS versions to bypass AMFI checks safely without globally disabling AMFI (Requires AMFIPass.kext)': {
      'pt': 'Permite que AMFIPass.kext em versões mais recentes do macOS ignore as verificações AMFI com segurança sem desabilitar globalmente o AMFI (requer AMFIPass.kext)',
      'zh': '在较新的 macOS 版本中启用 AMFIPass.kext 以安全地绕过 AMFI 检查，而无需全局禁用 AMFI（需要 AMFIPass.kext）',
      'zh_Hant': '在較新的 macOS 版本中啟用 AMFIPass.kext 以安全地繞過 AMFI 檢查，而無需全域停用 AMFI（需要 AMFIPass.kext）',
      'es': 'Habilita AMFIPass.kext en versiones más nuevas de macOS para evitar las comprobaciones de AMFI de forma segura sin deshabilitar AMFI globalmente (requiere AMFIPass.kext)',
      'de': 'Ermöglicht AMFIPass.kext in neueren macOS-Versionen, AMFI-Prüfungen sicher zu umgehen, ohne AMFI global zu deaktivieren (erfordert AMFIPass.kext)',
      'fr': 'Permet à AMFIPass.kext dans les versions plus récentes de macOS de contourner les vérifications AMFI en toute sécurité sans désactiver globalement AMFI (nécessite AMFIPass.kext)',
      'ru': 'Включает AMFIPass.kext в новых версиях macOS для безопасного обхода проверок AMFI без глобального отключения AMFI (требуется AMFIPass.kext)',
      'ja': '新しい macOS バージョンで AMFIPass.kext を有効にして、AMFI をグローバルに無効にすることなく AMFI チェックを安全にバイパスできるようにします (AMFIPass.kext が必要)',
      'ko': '최신 macOS 버전에서 AMFIPass.kext를 활성화하여 AMFI를 전체적으로 비활성화하지 않고도 안전하게 AMFI 검사를 우회합니다(AMFIPass.kext 필요).',
      'it': 'Abilita AMFIPass.kext nelle versioni macOS più recenti per aggirare i controlli AMFI in modo sicuro senza disabilitare AMFI a livello globale (richiede AMFIPass.kext)',
      'tr': 'Daha yeni macOS sürümlerinde AMFIPass.kext\'in, AMFI\'yi genel olarak devre dışı bırakmadan AMFI kontrollerini güvenli bir şekilde atlamasına olanak tanır (AMFIPass.kext gerektirir)',
      'vi': 'Cho phép AMFIPass.kext trong các phiên bản macOS mới hơn để vượt qua kiểm tra AMFI một cách an toàn mà không vô hiệu hóa AMFI trên toàn cầu (Yêu cầu AMFIPass.kext)',
      'pl': 'Włącza plik AMFIPass.kext w nowszych wersjach systemu macOS w celu bezpiecznego ominięcia kontroli AMFI bez globalnego wyłączania AMFI (wymaga pliku AMFIPass.kext)',
      'uk': 'Дозволяє AMFIPass.kext у новіших версіях macOS безпечно обходити перевірки AMFI без глобального вимкнення AMFI (потрібен AMFIPass.kext)',
      'nl': 'Zorgt ervoor dat AMFIPass.kext in nieuwere macOS-versies AMFI-controles veilig kan omzeilen zonder AMFI globaal uit te schakelen (vereist AMFIPass.kext)',
      'hi': 'वैश्विक स्तर पर AMFI को अक्षम किए बिना AMFI चेक को सुरक्षित रूप से बायपास करने के लिए नए macOS संस्करणों में AMFIPass.kext को सक्षम करता है (AMFIPass.kext की आवश्यकता है)',
      'ar': 'تمكين AMFIPass.kext في إصدارات macOS الأحدث لتجاوز عمليات فحص AMFI بأمان دون تعطيل AMFI عالميًا (يتطلب AMFIPass.kext)',
      'id': 'Mengaktifkan AMFIPass.kext di versi macOS yang lebih baru untuk melewati pemeriksaan AMFI dengan aman tanpa menonaktifkan AMFI secara global (Memerlukan AMFIPass.kext)',
    },
    'Enables USB network tethering from Android devices on macOS': {
      'pt': 'Ativa o tethering de rede USB de dispositivos Android no macOS',
      'zh': '在 macOS 上启用 Android 设备的 USB 网络共享',
      'zh_Hant': '在 macOS 上啟用 Android 裝置的 USB 網路共享',
      'es': 'Habilita la conexión a red USB desde dispositivos Android en macOS',
      'de': 'Ermöglicht USB-Netzwerk-Tethering von Android-Geräten unter macOS',
      'fr': 'Permet le partage de connexion réseau USB à partir d\'appareils Android sur macOS',
      'ru': 'Включает USB-модем к сети с устройств Android на macOS.',
      'ja': 'macOS 上の Android デバイスから USB ネットワーク テザリングを有効にします',
      'ko': 'macOS의 Android 장치에서 USB 네트워크 테더링을 활성화합니다.',
      'it': 'Abilita il tethering di rete USB da dispositivi Android su macOS',
      'tr': 'MacOS\'ta Android cihazlardan USB ağ bağlantısını etkinleştirir',
      'vi': 'Cho phép kết nối mạng USB từ thiết bị Android trên macOS',
      'pl': 'Umożliwia tethering sieciowy USB z urządzeń z systemem Android w systemie macOS',
      'uk': 'Вмикає мережевий USB-модем із пристроїв Android на macOS',
      'nl': 'Maakt USB-netwerktethering mogelijk vanaf Android-apparaten op macOS',
      'hi': 'MacOS पर Android डिवाइस से USB नेटवर्क टेदरिंग सक्षम करता है',
      'ar': 'لتمكين ربط شبكة USB من أجهزة Android على نظام التشغيل macOS',
      'id': 'Mengaktifkan tethering jaringan USB dari perangkat Android di macOS',
    },
    'Enables WhateverGreen, AppleALC, VirtualSMC and others to patch macOS on-the-fly for graphics, audio, sensors, etc.': {
      'pt': 'Permite que EverythingGreen, AppleALC, VirtualSMC e outros corrijam o macOS dinamicamente para gráficos, áudio, sensores, etc.',
      'zh': '使 WhateverGreen、AppleALC、VirtualSMC 等能够即时修补 macOS 的图形、音频、传感器等。',
      'zh_Hant': '讓 WhateverGreen、AppleALC、VirtualSMC 等能夠即時修補 macOS 的圖形、音訊、感應器等。',
      'es': 'Permite a AnythingGreen, AppleALC, VirtualSMC y otros parchear macOS sobre la marcha para gráficos, audio, sensores, etc.',
      'de': 'Ermöglicht WhateverGreen, AppleALC, VirtualSMC und anderen das spontane Patchen von macOS für Grafik, Audio, Sensoren usw.',
      'fr': 'Permet à WhichGreen, AppleALC, VirtualSMC et autres de patcher macOS à la volée pour les graphiques, l\'audio, les capteurs, etc.',
      'ru': 'Позволяет компаниям EverythingGreen, AppleALC, VirtualSMC и другим оперативно обновлять macOS для графики, звука, датчиков и т. д.',
      'ja': 'WhateverGreen、AppleALC、VirtualSMC などがグラフィックス、オーディオ、センサーなどの macOS にオンザフライでパッチを適用できるようにします。',
      'ko': 'EverythingGreen, AppleALC, VirtualSMC 등이 그래픽, 오디오, 센서 등에 대해 macOS를 즉시 패치할 수 있도록 지원합니다.',
      'it': 'Consente a EverythingGreen, AppleALC, VirtualSMC e altri di applicare al volo patch a macOS per grafica, audio, sensori, ecc.',
      'tr': 'WhatGreen, AppleALC, VirtualSMC ve diğerlerinin grafik, ses, sensörler vb. için macOS\'a anında yama yapmasını sağlar.',
      'vi': 'Cho phép AnythingGreen, AppleALC, VirtualSMC và các hãng khác vá macOS nhanh chóng cho đồ họa, âm thanh, cảm biến, v.v.',
      'pl': 'Umożliwia firmie WhatGreen, AppleALC, VirtualSMC i innym aktualizację macOS w locie w zakresie grafiki, dźwięku, czujników itp.',
      'uk': 'Дозволяє WhateverGreen, AppleALC, VirtualSMC та іншим виправляти macOS на льоту для графіки, аудіо, датчиків тощо.',
      'nl': 'Zorgt ervoor dat WhatGreen, AppleALC, VirtualSMC en anderen macOS on-the-fly kunnen patchen voor graphics, audio, sensoren, enz.',
      'hi': 'ग्राफ़िक्स, ऑडियो, सेंसर आदि के लिए macOS को ऑन-द-फ़्लाई पैच करने के लिए WhicheverGreen, AppleALC, VirtualSMC और अन्य को सक्षम बनाता है।',
      'ar': 'يمكّن WhatGreen وAppleALC وVirtualSMC وغيرها من تصحيح نظام التشغيل macOS أثناء التنقل للرسومات والصوت وأجهزة الاستشعار وما إلى ذلك.',
      'id': 'Memungkinkan ApapunGreen, AppleALC, VirtualSMC, dan lainnya untuk menambal macOS dengan cepat untuk grafis, audio, sensor, dll.',
    },
    'Enables complete iGPU firmware loading (GuC/HuC) to improve performance; may cause boot failure on some configurations, use with caution': {
      'pt': 'Permite o carregamento completo do firmware iGPU (GuC/HuC) para melhorar o desempenho; pode causar falha na inicialização em algumas configurações, use com cuidado',
      'zh': '启用完整的iGPU固件加载（GuC/HuC）以提高性能；某些配置可能会导致启动失败，请谨慎使用',
      'zh_Hant': '啟用完整的iGPU韌體載入（GuC/HuC）以提高效能；某些配置可能會導致啟動失敗，請謹慎使用',
      'es': 'Permite la carga completa del firmware de iGPU (GuC/HuC) para mejorar el rendimiento; puede causar fallas de arranque en algunas configuraciones, úselo con precaución',
      'de': 'Ermöglicht das vollständige Laden der iGPU-Firmware (GuC/HuC) zur Verbesserung der Leistung; kann bei manchen Konfigurationen zu Startfehlern führen, daher mit Vorsicht verwenden',
      'fr': 'Permet le chargement complet du micrologiciel iGPU (GuC/HuC) pour améliorer les performances ; peut provoquer un échec de démarrage sur certaines configurations, à utiliser avec prudence',
      'ru': 'Обеспечивает полную загрузку прошивки iGPU (GuC/HuC) для повышения производительности; может вызвать сбой загрузки в некоторых конфигурациях, используйте с осторожностью.',
      'ja': '完全な iGPU ファームウェアの読み込み (GuC/HuC) を有効にしてパフォーマンスを向上させます。一部の構成では起動エラーが発生する可能性があるため、使用には注意が必要です',
      'ko': '성능 향상을 위해 완전한 iGPU 펌웨어 로딩(GuC/HuC)을 활성화합니다. 일부 구성에서는 부팅 오류가 발생할 수 있으므로 주의해서 사용하세요.',
      'it': 'Abilita il caricamento completo del firmware iGPU (GuC/HuC) per migliorare le prestazioni; potrebbe causare errori di avvio in alcune configurazioni, utilizzare con cautela',
      'tr': 'Performansı artırmak için tam iGPU ürün yazılımı yüklemesini (GuC/HuC) etkinleştirir; bazı yapılandırmalarda önyükleme hatasına neden olabilir, dikkatli kullanın',
      'vi': 'Cho phép tải chương trình cơ sở iGPU hoàn chỉnh (GuC/HuC) để cải thiện hiệu suất; có thể gây ra lỗi khởi động trên một số cấu hình, hãy thận trọng khi sử dụng',
      'pl': 'Umożliwia pełne ładowanie oprogramowania sprzętowego iGPU (GuC/HuC) w celu poprawy wydajności; może spowodować awarię rozruchu w niektórych konfiguracjach, należy zachować ostrożność',
      'uk': 'Дозволяє повне завантаження прошивки iGPU (GuC/HuC) для підвищення продуктивності; може спричинити помилку завантаження в деяких конфігураціях, використовуйте з обережністю',
      'nl': 'Maakt het volledig laden van iGPU-firmware mogelijk (GuC/HuC) om de prestaties te verbeteren; kan bij sommige configuraties een opstartfout veroorzaken. Wees voorzichtig bij gebruik',
      'hi': 'प्रदर्शन में सुधार के लिए संपूर्ण iGPU फ़र्मवेयर लोडिंग (GuC/HuC) सक्षम करता है; कुछ कॉन्फ़िगरेशन पर बूट विफलता हो सकती है, सावधानी के साथ उपयोग करें',
      'ar': 'تمكين التحميل الكامل للبرامج الثابتة لـ iGPU (GuC/HuC) لتحسين الأداء؛ قد يتسبب في فشل التمهيد في بعض التكوينات، استخدمه بحذر',
      'id': 'Memungkinkan pemuatan firmware iGPU lengkap (GuC/HuC) untuk meningkatkan kinerja; dapat menyebabkan kegagalan boot pada beberapa konfigurasi, gunakan dengan hati-hati',
    },
    'Enables max pixel clock override on iGPU to remove macOS default resolution and refresh rate restrictions': {
      'pt': 'Permite a substituição do relógio máximo de pixels no iGPU para remover a resolução padrão do macOS e as restrições de taxa de atualização',
      'zh': '在 iGPU 上启用最大像素时钟覆盖，以消除 macOS 默认分辨率和刷新率限制',
      'zh_Hant': '在 iGPU 上啟用最大像素時脈覆蓋，以消除 macOS 預設解析度和刷新率限制',
      'es': 'Habilita la anulación del reloj máximo de píxeles en iGPU para eliminar las restricciones de frecuencia de actualización y resolución predeterminadas de macOS',
      'de': 'Aktiviert die Überschreibung des maximalen Pixeltakts auf der iGPU, um die Einschränkungen der macOS-Standardauflösung und Bildwiederholfrequenz zu entfernen',
      'fr': 'Permet le remplacement de l\'horloge maximale des pixels sur l\'iGPU pour supprimer les restrictions de résolution par défaut et de taux de rafraîchissement de macOS',
      'ru': 'Включает переопределение максимальной частоты пикселей на iGPU для снятия ограничений разрешения и частоты обновления по умолчанию в macOS.',
      'ja': 'iGPU の最大ピクセル クロック オーバーライドを有効にして、macOS のデフォルトの解像度とリフレッシュ レートの制限を削除します。',
      'ko': 'iGPU에서 최대 픽셀 클럭 재정의를 활성화하여 macOS 기본 해상도 및 새로 고침 빈도 제한을 제거합니다.',
      'it': 'Abilita l\'override del clock massimo dei pixel sull\'iGPU per rimuovere la risoluzione predefinita di macOS e le restrizioni sulla frequenza di aggiornamento',
      'tr': 'MacOS\'un varsayılan çözünürlüğünü ve yenileme hızı kısıtlamalarını kaldırmak için iGPU\'da maksimum piksel saatini geçersiz kılmayı etkinleştirir',
      'vi': 'Cho phép ghi đè xung nhịp pixel tối đa trên iGPU để loại bỏ các hạn chế về độ phân giải mặc định và tốc độ làm mới của macOS',
      'pl': 'Umożliwia zastąpienie maksymalnego zegara pikseli w iGPU w celu usunięcia domyślnych ograniczeń rozdzielczości i częstotliwości odświeżania macOS',
      'uk': 'Вмикає перевизначення максимальної тактової частоти пікселів на iGPU, щоб усунути обмеження роздільної здатності та частоти оновлення macOS за замовчуванням',
      'nl': 'Schakelt overschrijving van de maximale pixelklok op iGPU in om de standaardresolutie van macOS en beperkingen op de vernieuwingsfrequentie te verwijderen',
      'hi': 'MacOS डिफ़ॉल्ट रिज़ॉल्यूशन और ताज़ा दर प्रतिबंधों को हटाने के लिए iGPU पर अधिकतम पिक्सेल क्लॉक ओवरराइड सक्षम करता है',
      'ar': 'تمكين تجاوز الحد الأقصى لساعة البكسل على iGPU لإزالة الدقة الافتراضية لنظام التشغيل macOS وقيود معدل التحديث',
      'id': 'Mengaktifkan penggantian jam piksel maksimal di iGPU untuk menghapus resolusi default macOS dan batasan kecepatan refresh',
    },
    'Enables only 1 CPU core (useful for multi-core server CPU kernel panics during early installation)': {
      'pt': 'Ativa apenas 1 núcleo de CPU (útil para pânico de kernel de CPU de servidor multinúcleo durante a instalação inicial)',
      'zh': '仅启用 1 个 CPU 核心（对于早期安装期间的多核服务器 CPU 内核崩溃很有用）',
      'zh_Hant': '僅啟用 1 個 CPU 核心（對於早期安裝期間的多核心伺服器 CPU 核心崩潰很有用）',
      'es': 'Habilita solo 1 núcleo de CPU (útil para pánicos del kernel de CPU de servidores de múltiples núcleos durante la instalación temprana)',
      'de': 'Aktiviert nur 1 CPU-Kern (nützlich für Multi-Core-Server-CPU-Kernel-Paniks während der frühen Installation)',
      'fr': 'Active seulement 1 cœur de processeur (utile en cas de panique du noyau de processeur de serveur multicœur lors d\'une installation précoce)',
      'ru': 'Включает только 1 ядро ​​ЦП (полезно при возникновении паники ядра ЦП многоядерного сервера во время ранней установки)',
      'ja': '1 つの CPU コアのみを有効にします (初期インストール中のマルチコア サーバー CPU カーネル パニックに役立ちます)',
      'ko': '1개의 CPU 코어만 활성화합니다(초기 설치 중 멀티 코어 서버 CPU 커널 패닉에 유용함).',
      'it': 'Abilita solo 1 core della CPU (utile in caso di panico del kernel della CPU del server multi-core durante l\'installazione iniziale)',
      'tr': 'Yalnızca 1 CPU çekirdeğini etkinleştirir (erken kurulum sırasında çok çekirdekli sunucu CPU çekirdeği panikleri için kullanışlıdır)',
      'vi': 'Chỉ cho phép 1 lõi CPU (hữu ích khi nhân CPU máy chủ đa lõi bị hoảng loạn trong quá trình cài đặt ban đầu)',
      'pl': 'Włącza tylko 1 rdzeń procesora (przydatne w przypadku błędów jądra procesora wielordzeniowego serwera podczas wczesnej instalacji)',
      'uk': 'Вмикає лише 1 ядро ​​ЦП (корисно для багатоядерних серверів, ядро ​​ЦП паніки під час раннього встановлення)',
      'nl': 'Schakelt slechts 1 CPU-kern in (handig bij CPU-kernelpaniek van multi-core servers tijdens vroege installatie)',
      'hi': 'केवल 1 सीपीयू कोर सक्षम करता है (प्रारंभिक इंस्टॉलेशन के दौरान मल्टी-कोर सर्वर सीपीयू कर्नेल पैनिक के लिए उपयोगी)',
      'ar': 'تمكين وحدة معالجة مركزية واحدة فقط (مفيدة لحالات ذعر نواة وحدة المعالجة المركزية للخادم متعدد النواة أثناء التثبيت المبكر)',
      'id': 'Hanya mengaktifkan 1 inti CPU (berguna untuk kepanikan kernel CPU server multi-inti selama instalasi awal)',
    },
    'Enables support for unsupported RX 6000 series GPUs (RX 6700, 6750 XT, 6750 GRE); conflicts with WhateverGreen': {
      'pt': 'Permite suporte para GPUs da série RX 6000 não suportadas (RX 6700, 6750 XT, 6750 GRE); entra em conflito comWhateverGreen',
      'zh': '启用对不支持的 RX 6000 系列 GPU（RX 6700、6750 XT、6750 GRE）的支持；与WhateverGreen冲突',
      'zh_Hant': '啟用對不支援的 RX 6000 系列 GPU（RX 6700、6750 XT、6750 GRE）的支援；與WhateverGreen衝突',
      'es': 'Habilita la compatibilidad con GPU de la serie RX 6000 no compatibles (RX 6700, 6750 XT, 6750 GRE); entra en conflicto con lo que sea verde',
      'de': 'Ermöglicht die Unterstützung für nicht unterstützte GPUs der RX 6000-Serie (RX 6700, 6750 XT, 6750 GRE); Konflikte mit WhateverGreen',
      'fr': 'Permet la prise en charge des GPU de la série RX 6000 non pris en charge (RX 6700, 6750 XT, 6750 GRE) ; est en conflit avec WhichGreen',
      'ru': 'Включает поддержку неподдерживаемых графических процессоров серии RX 6000 (RX 6700, 6750 XT, 6750 GRE); конфликтует с WhateverGreen',
      'ja': 'サポートされていない RX 6000 シリーズ GPU (RX 6700、6750 XT、6750 GRE) のサポートを有効にします。 WhateverGreen と競合します',
      'ko': '지원되지 않는 RX 6000 시리즈 GPU(RX 6700, 6750 XT, 6750 GRE)에 대한 지원을 활성화합니다. EverythingGreen과 충돌',
      'it': 'Abilita il supporto per GPU serie RX 6000 non supportate (RX 6700, 6750 XT, 6750 GRE); è in conflitto con QualunqueVerde',
      'tr': 'Desteklenmeyen RX 6000 serisi GPU\'lar (RX 6700, 6750 XT, 6750 GRE) için desteği etkinleştirir; WhatGreen ile çakışıyor',
      'vi': 'Cho phép hỗ trợ các GPU dòng RX 6000 không được hỗ trợ (RX 6700, 6750 XT, 6750 GRE); xung đột với AnythingGreen',
      'pl': 'Umożliwia obsługę nieobsługiwanych procesorów graficznych z serii RX 6000 (RX 6700, 6750 XT, 6750 GRE); koliduje z WhatGreen',
      'uk': 'Вмикає підтримку непідтримуваних графічних процесорів серії RX 6000 (RX 6700, 6750 XT, 6750 GRE); конфліктує з WhateverGreen',
      'nl': 'Maakt ondersteuning mogelijk voor niet-ondersteunde GPU\'s uit de RX 6000-serie (RX 6700, 6750 XT, 6750 GRE); conflicteert met WhatGreen',
      'hi': 'असमर्थित RX 6000 श्रृंखला GPU (RX 6700, 6750 XT, 6750 GRE) के लिए समर्थन सक्षम करता है; व्हेयरग्रीन के साथ टकराव',
      'ar': 'تمكين الدعم لوحدات معالجة الرسومات غير المدعومة من سلسلة RX 6000 (RX 6700، 6750 XT، 6750 GRE)؛ يتعارض مع WhatGreen',
      'id': 'Mengaktifkan dukungan untuk GPU seri RX 6000 yang tidak didukung (RX 6700, 6750 XT, 6750 GRE); konflik dengan ApapunGreen',
    },
