      'nl': 'Compatibiliteitsproblemen met XHCI USB 3.0 oplossen op oudere AMD-platforms (FM1, FM2, AM3, enz.)',
      'hi': 'पुराने AMD प्लेटफ़ॉर्म (FM1, FM2, AM3, आदि) पर XHCI USB 3.0 संगतता समस्याओं को ठीक करें',
      'ar': 'إصلاح مشكلات توافق XHCI USB 3.0 على منصات AMD القديمة (FM1، FM2، AM3، إلخ.)',
      'id': 'Perbaiki masalah kompatibilitas XHCI USB 3.0 pada platform AMD lama (FM1, FM2, AM3, dll.)',
    },
    'Fix black screen and display issues by ignoring AppleGraphicsDevicePolicy restrictions. Note: Requires WhateverGreen.kext to take effect.': {
      'pt': 'Corrija problemas de tela preta e exibição ignorando as restrições AppleGraphicsDevicePolicy. Nota: Requer que AnythingGreen.kext entre em vigor.',
      'zh': '通过忽略 AppleGraphicsDevicePolicy 限制来修复黑屏和显示问题。注意：需要WhateverGreen.kext才能生效。',
      'zh_Hant': '透過忽略 AppleGraphicsDevicePolicy 限制來修復黑屏和顯示問題。注意：需要WhateverGreen.kext才能生效。',
      'es': 'Solucione problemas de visualización y pantalla negra ignorando las restricciones de AppleGraphicsDevicePolicy. Nota: Requiere AnywhereGreen.kext para que entre en vigor.',
      'de': 'Beheben Sie Probleme mit dem schwarzen Bildschirm und der Anzeige, indem Sie die AppleGraphicsDevicePolicy-Einschränkungen ignorieren. Hinweis: Erfordert WhateverGreen.kext, um wirksam zu werden.',
      'fr': 'Résolvez les problèmes d’écran noir et d’affichage en ignorant les restrictions AppleGraphicsDevicePolicy. Remarque : Nécessite WhichGreen.kext pour prendre effet.',
      'ru': 'Устраните проблемы с черным экраном и отображением, игнорируя ограничения AppleGraphicsDevicePolicy. Примечание. Для вступления в силу требуется файл WhateverGreen.kext.',
      'ja': 'AppleGraphicsDevicePolicy の制限を無視して、黒い画面と表示の問題を修正します。注: 有効にするには WhateverGreen.kext が必要です。',
      'ko': 'AppleGraphicsDevicePolicy 제한을 무시하여 검은색 화면 및 디스플레이 문제를 해결합니다. 참고: 적용하려면 EverythingGreen.kext가 필요합니다.',
      'it': 'Risolvi i problemi di schermo nero e visualizzazione ignorando le restrizioni di AppleGraphicsDevicePolicy. Nota: è necessario che EverythingGreen.kext abbia effetto.',
      'tr': 'AppleGraphicsDevicePolicy kısıtlamalarını göz ardı ederek siyah ekran ve görüntü sorunlarını düzeltin. Not: Etkili olması için WhatGreen.kext gerekir.',
      'vi': 'Khắc phục sự cố màn hình và hiển thị màu đen bằng cách bỏ qua các hạn chế của AppleGraphicsDevicePolicy. Lưu ý: Cần có AnythingGreen.kext để có hiệu lực.',
      'pl': 'Napraw problemy z czarnym ekranem i wyświetlaniem, ignorując ograniczenia AppleGraphicsDevicePolicy. Uwaga: do działania wymaga pliku WhatGreen.kext.',
      'uk': 'Усуньте проблеми з чорним екраном і дисплеєм, ігноруючи обмеження AppleGraphicsDevicePolicy. Примітка. Щоб набув чинності, потрібен файл WhateverGreen.kext.',
      'nl': 'Los problemen met het zwarte scherm en de weergave op door de AppleGraphicsDevicePolicy-beperkingen te negeren. Opmerking: vereist dat AnythingGreen.kext van kracht wordt.',
      'hi': 'AppleGraphicsDevicePolicy प्रतिबंधों को अनदेखा करके काली स्क्रीन और डिस्प्ले संबंधी समस्याओं को ठीक करें। ध्यान दें: प्रभावी होने के लिए WhichGreen.kext की आवश्यकता है।',
      'ar': 'أصلح مشكلات الشاشة السوداء والعرض من خلال تجاهل قيود AppleGraphicsDevicePolicy. ملحوظة: يتطلب تفعيل WhatGreen.kext.',
      'id': 'Perbaiki masalah layar dan tampilan hitam dengan mengabaikan batasan AppleGraphicsDevicePolicy. Catatan: Membutuhkan ApapunGreen.kext untuk diterapkan.',
    },
    'Fix black screen on Intel 3rd Gen and older platforms with AMD RX5XX/RX5XXX/RX6XXX GPUs on macOS Ventura and above (Requires OCLP root patch in OS; remove boot-arg or use config-after-post afterwards)': {
      'pt': 'Corrija a tela preta em plataformas Intel de 3ª geração e anteriores com GPUs AMD RX5XX/RX5XXX/RX6XXX no macOS Ventura e superior (requer patch raiz OCLP no sistema operacional; remova boot-arg ou use config-after-post posteriormente)',
      'zh': '修复 macOS Ventura 及更高版本上具有 AMD RX5XX/RX5XXX/RX6XXX GPU 的 Intel 第三代及更旧平台上的黑屏（需要操作系统中的 OCLP 根补丁；删除 boot-arg 或之后使用 config-after-post）',
      'zh_Hant': '修復 macOS Ventura 及更高版本上具有 AMD RX5XX/RX5XXX/RX6XXX GPU 的 Intel 第三代及更舊平台上的黑屏（需要作業系統中的 OCLP 根補丁；刪除 boot-arg 或之後使用 config-after-post）',
      'es': 'Repare la pantalla negra en Intel de 3.ª generación y plataformas anteriores con GPU AMD RX5XX/RX5XXX/RX6XXX en macOS Ventura y superiores (requiere el parche raíz OCLP en el sistema operativo; elimine boot-arg o use config-after-post después)',
      'de': 'Behebung des schwarzen Bildschirms auf Intel-Plattformen der 3. Generation und älteren Plattformen mit AMD RX5XX/RX5XXX/RX6XXX-GPUs unter macOS Ventura und höher (Erfordert OCLP-Root-Patch im Betriebssystem; boot-arg entfernen oder anschließend config-after-post verwenden)',
      'fr': 'Correction d\'un écran noir sur les plates-formes Intel de 3e génération et antérieures avec les GPU AMD RX5XX/RX5XXX/RX6XXX sur macOS Ventura et supérieur (nécessite le correctif racine OCLP dans le système d\'exploitation ; supprimez boot-arg ou utilisez config-after-post par la suite)',
      'ru': 'Исправлен черный экран на платформах Intel 3-го поколения и более старых с графическими процессорами AMD RX5XX/RX5XXX/RX6XXX в macOS Ventura и более поздних версиях (требуется корневой патч OCLP в ОС; удалите boot-arg или впоследствии используйте config-after-post)',
      'ja': 'macOS Ventura 以降で AMD RX5XX/RX5XXX/RX6XXX GPU を搭載した Intel 第 3 世代以降のプラットフォームでの黒い画面を修正 (OS で OCLP ルート パッチが必要。boot-arg を削除するか、後で config-after-post を使用)',
      'ko': 'macOS Ventura 이상에서 AMD RX5XX/RX5XXX/RX6XXX GPU를 사용하는 Intel 3세대 및 이전 플랫폼의 검은색 화면 수정(OS에서 OCLP 루트 패치 필요, boot-arg를 제거하거나 나중에 config-after-post 사용)',
      'it': 'Correggi lo schermo nero su piattaforme Intel di terza generazione e precedenti con GPU AMD RX5XX/RX5XXX/RX6XXX su macOS Ventura e versioni successive (richiede la patch root OCLP nel sistema operativo; rimuovi boot-arg o utilizza config-after-post in seguito)',
      'tr': 'MacOS Ventura ve sonraki sürümlerde AMD RX5XX/RX5XXX/RX6XXX GPU\'lara sahip Intel 3. Nesil ve daha eski platformlardaki siyah ekranı düzeltin (İşletim Sisteminde OCLP kök yamasını gerektirir; boot-arg\'ı kaldırın veya daha sonra config-after-post kullanın)',
      'vi': 'Sửa màn hình đen trên nền tảng Intel thế hệ thứ 3 trở lên với GPU AMD RX5XX/RX5XXX/RX6XXX trên macOS Ventura trở lên (Yêu cầu bản vá gốc OCLP trong HĐH; xóa boot-arg hoặc sử dụng config-after-post sau đó)',
      'pl': 'Napraw czarny ekran na platformach Intel 3. generacji i starszych z procesorami graficznymi AMD RX5XX/RX5XXX/RX6XXX w systemie macOS Ventura i nowszych (wymaga łatki root OCLP w systemie operacyjnym; usuń boot-arg lub później użyj config-after-post)',
      'uk': 'Виправлення чорного екрану на платформах Intel 3-го покоління та старіших платформах із графічними процесорами AMD RX5XX/RX5XXX/RX6XXX на macOS Ventura та новіших версіях (потрібне кореневе виправлення OCLP в ОС; видаліть boot-arg або потім скористайтеся config-after-post)',
      'nl': 'Zwart scherm repareren op Intel 3e generatie en oudere platforms met AMD RX5XX/RX5XXX/RX6XXX GPU\'s op macOS Ventura en hoger (vereist OCLP-rootpatch in OS; verwijder boot-arg of gebruik daarna config-after-post)',
      'hi': 'MacOS वेंचुरा और उससे ऊपर के AMD RX5XX/RX5XXX/RX6XXX GPU के साथ Intel 3rd Gen और पुराने प्लेटफ़ॉर्म पर काली स्क्रीन को ठीक करें (OS में OCLP रूट पैच की आवश्यकता है; बूट-आर्ग हटाएं या बाद में कॉन्फिग-आफ्टर-पोस्ट का उपयोग करें)',
      'ar': 'إصلاح الشاشة السوداء على منصات Intel من الجيل الثالث والأنظمة الأقدم باستخدام وحدات معالجة الرسومات AMD RX5XX/RX5XXX/RX6XXX على نظام التشغيل macOS Ventura والإصدارات الأحدث (يتطلب تصحيح جذر OCLP في نظام التشغيل؛ قم بإزالة وسيطة التمهيد أو استخدم التكوين بعد النشر بعد ذلك)',
      'id': 'Memperbaiki layar hitam pada platform Intel Generasi ke-3 dan yang lebih lama dengan GPU AMD RX5XX/RX5XXX/RX6XXX pada macOS Ventura dan yang lebih baru (Memerlukan patch root OCLP di OS; hapus boot-arg atau gunakan config-after-post setelahnya)',
    },
    'Fix boot black screen on AMD Navi RX5XXX/RX6XXX GPUs (e.g. RX5500, RX5700, RX6600, RX6800, RX6900). Requires WhateverGreen.kext and disabling Serial/COM Port in BIOS.': {
      'pt': 'Corrija a tela preta de inicialização em GPUs AMD Navi RX5XXX/RX6XXX (por exemplo, RX5500, RX5700, RX6600, RX6800, RX6900). RequerWhateverGreen.kext e desativação da porta serial/COM no BIOS.',
      'zh': '修复 AMD Navi RX5XXX/RX6XXX GPU（例如 RX5500、RX5700、RX6600、RX6800、RX6900）上的启动黑屏。需要WhateverGreen.kext 并在BIOS 中禁用串行/COM 端口。',
      'zh_Hant': '修復 AMD Navi RX5XXX/RX6XXX GPU（例如 RX5500、RX5700、RX6600、RX6800、RX6900）上的啟動黑屏。需要WhateverGreen.kext 並在BIOS 中停用串列/COM 連接埠。',
      'es': 'Se corrigió la pantalla negra de arranque en las GPU AMD Navi RX5XXX/RX6XXX (por ejemplo, RX5500, RX5700, RX6600, RX6800, RX6900). Requiere WhicheverGreen.kext y deshabilitar el puerto serie/COM en BIOS.',
      'de': 'Behebung des schwarzen Startbildschirms auf AMD Navi RX5XXX/RX6XXX-GPUs (z. B. RX5500, RX5700, RX6600, RX6800, RX6900). Erfordert WhateverGreen.kext und die Deaktivierung des seriellen/COM-Ports im BIOS.',
      'fr': 'Correction de l\'écran noir de démarrage sur les GPU AMD Navi RX5XXX/RX6XXX (par exemple RX5500, RX5700, RX6600, RX6800, RX6900). Nécessite WhichGreen.kext et la désactivation du port série/COM dans le BIOS.',
      'ru': 'Исправлен черный экран при загрузке на графических процессорах AMD Navi RX5XXX/RX6XXX (например, RX5500, RX5700, RX6600, RX6800, RX6900). Требуется AnyGreen.kext и отключение последовательного/COM-порта в BIOS.',
      'ja': 'AMD Navi RX5XXX/RX6XXX GPU (RX5500、RX5700、RX6600、RX6800、RX6900 など) のブート ブラック スクリーンを修正しました。 WhateverGreen.kext と BIOS のシリアル/COM ポートの無効化が必要です。',
      'ko': 'AMD Navi RX5XXX/RX6XXX GPU(예: RX5500, RX5700, RX6600, RX6800, RX6900)에서 부팅 검은색 화면 문제를 해결합니다. EverythingGreen.kext가 필요하고 BIOS에서 직렬/COM 포트를 비활성화해야 합니다.',
      'it': 'Correzione della schermata nera di avvio sulle GPU AMD Navi RX5XXX/RX6XXX (ad esempio RX5500, RX5700, RX6600, RX6800, RX6900). Richiede EverythingGreen.kext e la disabilitazione della porta seriale/COM nel BIOS.',
      'tr': 'AMD Navi RX5XXX/RX6XXX GPU\'larda (örn. RX5500, RX5700, RX6600, RX6800, RX6900) önyükleme siyah ekranını düzeltin. WhatGreen.kext dosyasını ve BIOS\'ta Seri/COM Bağlantı Noktasının devre dışı bırakılmasını gerektirir.',
      'vi': 'Sửa màn hình đen khởi động trên GPU AMD Navi RX5XXX/RX6XXX (ví dụ: RX5500, RX5700, RX6600, RX6800, RX6900). Yêu cầu AnythingGreen.kext và tắt Cổng Serial/COM trong BIOS.',
      'pl': 'Napraw czarny ekran podczas uruchamiania na procesorach graficznych AMD Navi RX5XXX/RX6XXX (np. RX5500, RX5700, RX6600, RX6800, RX6900). Wymaga pliku WhatGreen.kext i wyłączenia portu szeregowego/COM w BIOS-ie.',
      'uk': 'Виправте чорний екран завантаження на графічних процесорах AMD Navi RX5XXX/RX6XXX (наприклад, RX5500, RX5700, RX6600, RX6800, RX6900). Потрібен WhateverGreen.kext і відключення послідовного/COM порту в BIOS.',
      'nl': 'Probleem met het zwarte opstartscherm op AMD Navi RX5XXX/RX6XXX GPU\'s (bijv. RX5500, RX5700, RX6600, RX6800, RX6900) opgelost. Vereist AnythingGreen.kext en het uitschakelen van de seriële/COM-poort in het BIOS.',
      'hi': 'AMD Navi RX5XXX/RX6XXX GPU (जैसे RX5500, RX5700, RX6600, RX6800, RX6900) पर बूट ब्लैक स्क्रीन को ठीक करें। BetterGreen.kext की आवश्यकता है और BIOS में सीरियल/COM पोर्ट को अक्षम करना है।',
      'ar': 'إصلاح شاشة التمهيد السوداء على وحدات معالجة الرسوميات AMD Navi RX5XXX/RX6XXX (مثل RX5500 وRX5700 وRX6600 وRX6800 وRX6900). يتطلب WhatGreen.kext وتعطيل المنفذ التسلسلي/COM في BIOS.',
      'id': 'Memperbaiki layar hitam boot pada GPU AMD Navi RX5XXX/RX6XXX (mis. RX5500, RX5700, RX6600, RX6800, RX6900). Membutuhkan ApapunGreen.kext dan menonaktifkan Serial/COM Port di BIOS.',
    },
    'Fix corrupted or yellow screen display issues on legacy AMD cards such as HD7750, HD7850 (GCN series HD77XX, HD78XX, HD79XX)': {
      'pt': 'Corrija problemas de exibição de tela amarela ou corrompida em placas AMD herdadas, como HD7750, HD7850 (série GCN HD77XX, HD78XX, HD79XX)',
      'zh': '修复旧版 AMD 卡（例如 HD7750、HD7850（GCN 系列 HD77XX、HD78XX、HD79XX））上的损坏或黄屏显示问题',
      'zh_Hant': '修正舊版 AMD 卡（例如 HD7750、HD7850（GCN 系列 HD77XX、HD78XX、HD79XX））上的損壞或黃色螢幕顯示問題',
      'es': 'Solucione problemas de visualización de pantalla amarilla o dañada en tarjetas AMD heredadas como HD7750, HD7850 (series GCN HD77XX, HD78XX, HD79XX)',
      'de': 'Beheben Sie Probleme mit der beschädigten oder gelben Bildschirmanzeige auf älteren AMD-Karten wie HD7750, HD7850 (GCN-Serie HD77XX, HD78XX, HD79XX).',
      'fr': 'Résoudre les problèmes d\'affichage d\'écran corrompus ou jaunes sur les anciennes cartes AMD telles que HD7750, HD7850 (série GCN HD77XX, HD78XX, HD79XX)',
      'ru': 'Исправление проблем с поврежденным или желтым экраном на устаревших картах AMD, таких как HD7750, HD7850 (серии GCN HD77XX, HD78XX, HD79XX).',
      'ja': 'HD7750、HD7850 (GCN シリーズ HD77XX、HD78XX、HD79XX) などのレガシー AMD カードでの破損または黄色の画面表示の問題を修正します。',
      'ko': 'HD7750, HD7850(GCN 시리즈 HD77XX, HD78XX, HD79XX)과 같은 레거시 AMD 카드에서 손상되거나 노란색 화면 디스플레이 문제 수정',
      'it': 'Risolvi i problemi di visualizzazione dello schermo danneggiato o giallo su schede AMD legacy come HD7750, HD7850 (serie GCN HD77XX, HD78XX, HD79XX)',
      'tr': 'HD7750, HD7850 (GCN serisi HD77XX, HD78XX, HD79XX) gibi eski AMD kartlarındaki bozuk veya sarı ekran sorunlarını düzeltin',
      'vi': 'Khắc phục sự cố hiển thị màn hình bị hỏng hoặc màu vàng trên các thẻ AMD cũ như HD7750, HD7850 (GCN series HD77XX, HD78XX, HD79XX)',
      'pl': 'Napraw problemy z uszkodzonym lub żółtym ekranem na starszych kartach AMD, takich jak HD7750, HD7850 (seria GCN HD77XX, HD78XX, HD79XX)',
      'uk': 'Виправлення проблем із пошкодженим або жовтим екраном на застарілих картах AMD, таких як HD7750, HD7850 (GCN серії HD77XX, HD78XX, HD79XX)',
      'nl': 'Problemen met beschadigde of gele schermweergave oplossen op oudere AMD-kaarten zoals HD7750, HD7850 (GCN-serie HD77XX, HD78XX, HD79XX)',
      'hi': 'HD7750, HD7850 (GCN श्रृंखला HD77XX, HD78XX, HD79XX) जैसे पुराने AMD कार्ड पर दूषित या पीली स्क्रीन डिस्प्ले समस्याओं को ठीक करें',
      'ar': 'إصلاح مشكلات عرض الشاشة التالفة أو الصفراء على بطاقات AMD القديمة مثل HD7750، HD7850 (سلسلة GCN HD77XX، HD78XX، HD79XX)',
      'id': 'Memperbaiki masalah tampilan layar yang rusak atau kuning pada kartu AMD lama seperti HD7750, HD7850 (seri GCN HD77XX, HD78XX, HD79XX)',
    },
    'Fix graphics driver for legacy NVIDIA Fermi/Maxwell/Pascal GPUs on macOS Big Sur 11+ (Requires OCLP root patch; Kepler cores do not need this parameter)': {
      'pt': 'Correção do driver gráfico para GPUs NVIDIA Fermi/Maxwell/Pascal legadas no macOS Big Sur 11+ (requer patch raiz OCLP; os núcleos Kepler não precisam deste parâmetro)',
      'zh': '修复 macOS Big Sur 11+ 上传统 NVIDIA Fermi/Maxwell/Pascal GPU 的图形驱动程序（需要 OCLP 根补丁；Kepler 核心不需要此参数）',
      'zh_Hant': '修正 macOS Big Sur 11+ 上傳統 NVIDIA Fermi/Maxwell/Pascal GPU 的圖形驅動程式（需要 OCLP 根補丁；Kepler 核心不需要此參數）',
      'es': 'Se corrigió el controlador de gráficos para las GPU NVIDIA Fermi/Maxwell/Pascal heredadas en macOS Big Sur 11+ (requiere el parche raíz OCLP; los núcleos Kepler no necesitan este parámetro)',
      'de': 'Grafiktreiber für ältere NVIDIA Fermi/Maxwell/Pascal-GPUs auf macOS Big Sur 11+ reparieren (Erfordert OCLP-Root-Patch; Kepler-Kerne benötigen diesen Parameter nicht)',
      'fr': 'Correction du pilote graphique pour les anciens GPU NVIDIA Fermi/Maxwell/Pascal sur macOS Big Sur 11+ (nécessite le correctif racine OCLP ; les cœurs Kepler n\'ont pas besoin de ce paramètre)',
      'ru': 'Исправление графического драйвера для устаревших графических процессоров NVIDIA Fermi/Maxwell/Pascal в macOS Big Sur 11+ (требуется корневой патч OCLP; ядрам Kepler этот параметр не требуется).',
      'ja': 'macOS Big Sur 11+ 上のレガシー NVIDIA Fermi/Maxwell/Pascal GPU のグラフィックス ドライバーを修正 (OCLP ルート パッチが必要。Kepler コアにはこのパラメーターは必要ありません)',
      'ko': 'macOS Big Sur 11+에서 레거시 NVIDIA Fermi/Maxwell/Pascal GPU용 그래픽 드라이버 수정(OCLP 루트 패치 필요, Kepler 코어에는 이 매개변수가 필요하지 않음)',
      'it': 'Correzione del driver grafico per GPU NVIDIA Fermi/Maxwell/Pascal legacy su macOS Big Sur 11+ (richiede la patch root OCLP; i core Kepler non necessitano di questo parametro)',
      'tr': 'MacOS Big Sur 11+ üzerinde eski NVIDIA Fermi/Maxwell/Pascal GPU\'lar için grafik sürücüsünü düzeltin (OCLP kök düzeltme eki gerektirir; Kepler çekirdekleri bu parametreye ihtiyaç duymaz)',
      'vi': 'Sửa trình điều khiển đồ họa cho GPU NVIDIA Fermi/Maxwell/Pascal cũ trên macOS Big Sur 11+ (Yêu cầu bản vá gốc OCLP; lõi Kepler không cần tham số này)',
      'pl': 'Napraw sterownik graficzny dla starszych procesorów graficznych NVIDIA Fermi/Maxwell/Pascal w systemie macOS Big Sur 11+ (wymaga łatki root OCLP; rdzenie Kepler nie potrzebują tego parametru)',
      'uk': 'Виправити графічний драйвер для застарілих графічних процесорів NVIDIA Fermi/Maxwell/Pascal на macOS Big Sur 11+ (потрібне кореневе виправлення OCLP; ядра Kepler не потребують цього параметра)',
      'nl': 'Grafisch stuurprogramma repareren voor oudere NVIDIA Fermi/Maxwell/Pascal GPU\'s op macOS Big Sur 11+ (vereist OCLP-rootpatch; Kepler-cores hebben deze parameter niet nodig)',
      'hi': 'MacOS बिग सुर 11+ पर लीगेसी NVIDIA Fermi/Maxwell/Pascal GPU के लिए ग्राफ़िक्स ड्राइवर ठीक करें (OCLP रूट पैच की आवश्यकता है; केप्लर कोर को इस पैरामीटर की आवश्यकता नहीं है)',
      'ar': 'إصلاح برنامج تشغيل الرسومات لوحدات معالجة الرسومات NVIDIA Fermi/Maxwell/Pascal القديمة على نظام التشغيل macOS Big Sur 11+ (يتطلب تصحيح جذر OCLP؛ ولا تحتاج مراكز Kepler إلى هذه المعلمة)',
      'id': 'Memperbaiki driver grafis untuk GPU NVIDIA Fermi/Maxwell/Pascal lama di macOS Big Sur 11+ (Memerlukan patch root OCLP; core Kepler tidak memerlukan parameter ini)',
    },
    'Fix macOS OTA updates when SIP or SecureBootModel is disabled, and fix custom CPU name display': {
