    'Fix sleep wake black screen on RX470/RX570 GPUs by disabling board-id check in AppleGraphicsDevicePolicy. Requires WhateverGreen.kext.': {
      'pt': 'Corrija a tela preta sleep wake em GPUs RX470/RX570 desativando a verificação de id da placa em AppleGraphicsDevicePolicy. RequerWhateverGreen.kext.',
      'zh': '通过在 AppleGraphicsDevicePolicy 中禁用板 ID 检查来修复 RX470/RX570 GPU 上的睡眠唤醒黑屏。需要WhateverGreen.kext。',
      'zh_Hant': '透過在 AppleGraphicsDevicePolicy 中停用板 ID 檢查來修復 RX470/RX570 GPU 上的睡眠喚醒黑屏。需要WhateverGreen.kext。',
      'es': 'Se corrige la pantalla negra de activación y suspensión en las GPU RX470/RX570 deshabilitando la verificación de identificación de la placa en AppleGraphicsDevicePolicy. Requiere AnywhereGreen.kext.',
      'de': 'Beheben Sie den schwarzen Sleep-Wake-Bildschirm auf RX470/RX570-GPUs, indem Sie die Board-ID-Prüfung in AppleGraphicsDevicePolicy deaktivieren. Erfordert WhateverGreen.kext.',
      'fr': 'Correction de l\'écran noir de veille sur les GPU RX470/RX570 en désactivant la vérification de l\'ID de la carte dans AppleGraphicsDevicePolicy. Nécessite WhichGreen.kext.',
      'ru': 'Исправьте черный экран сна и пробуждения на графических процессорах RX470/RX570, отключив проверку идентификатора платы в AppleGraphicsDevicePolicy. Требуется AnyGreen.kext.',
      'ja': 'AppleGraphicsDevicePolicy でボード ID チェックを無効にすることで、RX470/RX570 GPU でのスリープ解除の黒い画面を修正しました。 WhateverGreen.kext が必要です。',
      'ko': 'AppleGraphicsDevicePolicy에서 보드 ID 확인을 비활성화하여 RX470/RX570 GPU에서 절전 모드 해제 검은색 화면 문제를 해결합니다. EverythingGreen.kext가 필요합니다.',
      'it': 'Correggi la schermata nera di riattivazione della modalità di sospensione sulle GPU RX470/RX570 disabilitando il controllo dell\'ID della scheda in AppleGraphicsDevicePolicy. Richiede EverythingGreen.kext.',
      'tr': 'AppleGraphicsDevicePolicy\'de anakart kimliği kontrolünü devre dışı bırakarak RX470/RX570 GPU\'larda uykudan uyanma siyah ekranını düzeltin. WhatGreen.kext gerektirir.',
      'vi': 'Khắc phục màn hình đen khi ngủ trên GPU RX470/RX570 bằng cách tắt tính năng kiểm tra id bảng trong AppleGraphicsDevicePolicy. Yêu cầu AnythingGreen.kext.',
      'pl': 'Napraw czarny ekran po wybudzeniu w trybie uśpienia na procesorach graficznych RX470/RX570, wyłączając sprawdzanie identyfikatora płyty w AppleGraphicsDevicePolicy. Wymaga pliku WhatGreen.kext.',
      'uk': 'Виправте чорний екран у режимі сну та пробудження на графічних процесорах RX470/RX570, вимкнувши перевірку ідентифікатора плати в AppleGraphicsDevicePolicy. Потрібен WhateverGreen.kext.',
      'nl': 'Herstel het zwarte slaapscherm op RX470/RX570 GPU\'s door de board-id-controle in AppleGraphicsDevicePolicy uit te schakelen. Vereist AnythingGreen.kext.',
      'hi': 'AppleGraphicsDevicePolicy में बोर्ड-आईडी चेक को अक्षम करके RX470/RX570 GPU पर स्लीप वेक ब्लैक स्क्रीन को ठीक करें। VeryGreen.kext की आवश्यकता है।',
      'ar': 'قم بإصلاح الشاشة السوداء أثناء النوم على وحدات معالجة الرسومات RX470/RX570 عن طريق تعطيل التحقق من معرف اللوحة في AppleGraphicsDevicePolicy. يتطلب WhatGreen.kext.',
      'id': 'Perbaiki layar hitam bangun tidur pada GPU RX470/RX570 dengan menonaktifkan pemeriksaan board-id di AppleGraphicsDevicePolicy. Membutuhkan ApapunGreen.kext.',
    },
    'Fix slow Broadcom WiFi speeds by setting country code to HK (can also improve by changing router channels)': {
      'pt': 'Corrija velocidades lentas do Broadcom WiFi definindo o código do país como HK (também pode melhorar alterando os canais do roteador)',
      'zh': '通过将国家/地区代码设置为 HK 来修复 Broadcom WiFi 速度较慢的问题（也可以通过更改路由器频道来改善）',
      'zh_Hant': '透過將國家代碼設定為 HK 來修復 Broadcom WiFi 速度較慢的問題（也可以透過更改路由器頻道來改善）',
      'es': 'Corrija las velocidades lentas de WiFi de Broadcom configurando el código de país en HK (también puede mejorar cambiando los canales del enrutador)',
      'de': 'Beheben Sie langsame Broadcom-WLAN-Geschwindigkeiten, indem Sie den Ländercode auf HK setzen (kann auch durch Ändern der Router-Kanäle verbessert werden)',
      'fr': 'Corrigez les vitesses lentes du WiFi Broadcom en définissant le code de pays sur HK (peut également s\'améliorer en changeant les canaux du routeur)',
      'ru': 'Исправьте низкую скорость Wi-Fi Broadcom, установив код страны на HK (также можно улучшить, изменив каналы маршрутизатора).',
      'ja': '国コードを HK に設定して、Broadcom WiFi 速度の遅さを修正します (ルーターのチャネルを変更することでも改善できます)',
      'ko': '국가 코드를 홍콩으로 설정하여 느린 Broadcom WiFi 속도 문제 해결(라우터 채널을 변경하여 개선할 수도 있음)',
      'it': 'Correggi le velocità lente del WiFi Broadcom impostando il codice paese su HK (puoi anche migliorare cambiando i canali del router)',
      'tr': 'Ülke kodunu HK olarak ayarlayarak yavaş Broadcom WiFi hızlarını düzeltin (yönlendirici kanallarını değiştirerek de geliştirilebilir)',
      'vi': 'Khắc phục tốc độ WiFi Broadcom chậm bằng cách đặt mã quốc gia thành HK (cũng có thể cải thiện bằng cách thay đổi kênh bộ định tuyến)',
      'pl': 'Napraw wolne prędkości Wi-Fi Broadcom, ustawiając kod kraju na HK (można to również poprawić, zmieniając kanały routera)',
      'uk': 'Виправте повільну швидкість Wi-Fi Broadcom, встановивши код країни на HK (також можна покращити, змінивши канали маршрутизатора)',
      'nl': 'Los de trage Broadcom WiFi-snelheden op door de landcode in te stellen op HK (kan ook worden verbeterd door de routerkanalen te wijzigen)',
      'hi': 'देश कोड को HK पर सेट करके धीमी ब्रॉडकॉम वाईफ़ाई गति को ठीक करें (राउटर चैनल बदलकर भी सुधार किया जा सकता है)',
      'ar': 'قم بإصلاح سرعات Broadcom WiFi البطيئة عن طريق تعيين رمز البلد على HK (يمكن أيضًا تحسينه عن طريق تغيير قنوات جهاز التوجيه)',
      'id': 'Perbaiki kecepatan WiFi Broadcom yang lambat dengan mengatur kode negara ke HK (dapat juga ditingkatkan dengan mengubah saluran router)',
    },
