      'hi': 'कुछ लैपटॉप पर 4K एचडीएमआई ब्लैक स्क्रीन को ठीक करता है (उदाहरण के लिए थिंकपैड P71 / i7-7700HQ / HD 630 gIOScreenLockState3 पर अटका हुआ)',
