    'Fixes CPU power management panics on Intel 3rd Gen and older platforms (AppleIntelCPUPowerManagement panic, boot logo hang, instant reboot)': {
      'pt': 'Corrige pânico de gerenciamento de energia da CPU em plataformas Intel de 3ª geração e anteriores (pânico AppleIntelCPUPowerManagement, travamento do logotipo de inicialização, reinicialização instantânea)',
      'zh': '修复了 Intel 第三代及更早版本平台上的 CPU 电源管理恐慌（AppleIntelCPUPowerManagement 恐慌、启动徽标挂起、即时重启）',
      'zh_Hant': '修正了 Intel 第三代及更早版本平台上的 CPU 電源管理恐慌（AppleIntelCPUPowerManagement 恐慌、啟動標誌掛起、即時重新啟動）',
      'es': 'Soluciona problemas de pánico en la administración de energía de la CPU en plataformas Intel de 3.ª generación y anteriores (pánico de AppleIntelCPUPowerManagement, bloqueo del logotipo de arranque, reinicio instantáneo)',
      'de': 'Behebt CPU-Energieverwaltungs-Panik auf Intel-Plattformen der 3. Generation und älteren Plattformen (AppleIntelCPUPowerManagement-Panik, Boot-Logo hängt, sofortiger Neustart)',
      'fr': 'Corrige les paniques de gestion de l\'alimentation du processeur sur les plates-formes Intel de 3e génération et antérieures (panique AppleIntelCPUPowerManagement, blocage du logo de démarrage, redémarrage instantané)',
      'ru': 'Устраняет панику при управлении питанием ЦП на платформах Intel 3-го поколения и более ранних (паника AppleIntelCPUPowerManagement, зависание логотипа загрузки, мгновенная перезагрузка)',
      'ja': 'Intel 第 3 世代以前のプラットフォームでの CPU 電源管理パニック (AppleIntelCPUPowerManagement パニック、ブート ロゴのハング、インスタント リブート) を修正しました。',
      'ko': 'Intel 3세대 및 이전 플랫폼에서 CPU 전원 관리 패닉을 수정합니다(AppleIntelCPUPowerManagement 패닉, 부팅 로고 정지, 즉시 재부팅).',
      'it': 'Risolve i problemi di gestione energetica della CPU su piattaforme Intel di terza generazione e precedenti (panico AppleIntelCPUPowerManagement, blocco del logo di avvio, riavvio istantaneo)',
      'tr': 'Intel 3. Nesil ve daha eski platformlarda CPU güç yönetimi paniklerini düzeltir (AppleIntelCPUPowerManagement paniği, önyükleme logosunun askıda kalması, anında yeniden başlatma)',
      'vi': 'Khắc phục sự cố quản lý năng lượng CPU trên Intel thế hệ thứ 3 và các nền tảng cũ hơn (AppleIntelCPUPowerQuản lý hoảng loạn, treo logo khởi động, khởi động lại ngay lập tức)',
      'pl': 'Naprawiono błędy związane z zarządzaniem energią procesora na platformach Intel 3. generacji i starszych (awaria AppleIntelCPUPowerManagement, zawieszanie się logo startowego, natychmiastowe ponowne uruchomienie)',
      'uk': 'Виправляє паніку керування живленням ЦП на платформах Intel 3-го покоління та старіших платформах (паніка AppleIntelCPUPowerManagement, зависання логотипа завантаження, миттєве перезавантаження)',
      'nl': 'Verhelpt paniek bij CPU-energiebeheer op Intel 3e generatie en oudere platforms (AppleIntelCPUPowerManagement paniek, opstartlogo blijft hangen, onmiddellijk opnieuw opstarten)',
      'hi': 'Intel 3rd Gen और पुराने प्लेटफ़ॉर्म पर CPU पावर मैनेजमेंट पैनिक को ठीक करता है (AppleIntelCPUPowerManagement पैनिक, बूट लोगो हैंग, इंस्टेंट रिबूट)',
      'ar': 'يعمل على إصلاح حالات الذعر المتعلقة بإدارة طاقة وحدة المعالجة المركزية على أنظمة Intel من الجيل الثالث والأنظمة الأقدم (ذعر AppleIntelCPUPowerManagement، تعليق شعار التمهيد، إعادة التشغيل الفوري)',
      'id': 'Memperbaiki kepanikan manajemen daya CPU pada platform Intel Generasi ke-3 dan yang lebih lama (kepanikan AppleIntelCPUPowerManagement, logo boot hang, reboot instan)',
    },
