    'Fixes Intel iGPU maximum link rate calculation that causes crashes or no signal on 4K displays (Skylake, Kaby Lake, Coffee Lake, Comet Lake)': {
      'pt': 'Corrige o cálculo da taxa de link máxima do Intel iGPU que causa travamentos ou ausência de sinal em monitores 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'zh': '修复了 Intel iGPU 最大链接速率计算导致 4K 显示器崩溃或无信号的问题（Skylake、Kaby Lake、Coffee Lake、Comet Lake）',
      'zh_Hant': '修正了 Intel iGPU 最大連結速率計算導致 4K 顯示器崩潰或無訊號的問題（Skylake、Kaby Lake、Coffee Lake、Comet Lake）',
      'es': 'Corrige el cálculo de la velocidad de enlace máxima de Intel iGPU que provoca fallas o falta de señal en pantallas 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'de': 'Behebt die Berechnung der maximalen Verbindungsrate der Intel iGPU, die zu Abstürzen oder keinem Signal auf 4K-Displays führt (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'fr': 'Corrige le calcul du débit de liaison maximal Intel iGPU qui provoque des plantages ou l\'absence de signal sur les écrans 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'ru': 'Исправлен расчет максимальной скорости соединения Intel iGPU, приводивший к сбоям или отсутствию сигнала на дисплеях 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake).',
      'ja': '4K ディスプレイ (Skylake、Kaby Lake、Coffee Lake、Comet Lake) でクラッシュまたは無信号を引き起こす Intel iGPU の最大リンク レートの計算を修正しました。',
      'ko': '4K 디스플레이(Skylake, Kaby Lake, Coffee Lake, Comet Lake)에서 충돌이나 신호 없음을 유발하는 Intel iGPU 최대 링크 속도 계산을 수정합니다.',
      'it': 'Risolto il problema con il calcolo della velocità di collegamento massima dell\'iGPU Intel che causava arresti anomali o assenza di segnale sui display 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'tr': '4K ekranlarda (Skylake, Kaby Lake, Coffee Lake, Comet Lake) çökmelere veya sinyal olmamasına neden olan Intel iGPU maksimum bağlantı hızı hesaplamasını düzeltir',
      'vi': 'Khắc phục tính toán tốc độ liên kết tối đa của Intel iGPU gây ra sự cố hoặc không có tín hiệu trên màn hình 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'pl': 'Naprawiono obliczanie maksymalnej szybkości łącza Intel iGPU, które powoduje awarie lub brak sygnału na wyświetlaczach 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'uk': 'Виправлено розрахунок максимальної швидкості з’єднання Intel iGPU, який спричиняє збої або відсутність сигналу на дисплеях 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'nl': 'Oplossing voor een berekening van de maximale verbindingssnelheid van Intel iGPU die crashes of geen signaal veroorzaakt op 4K-schermen (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
      'hi': 'Intel iGPU अधिकतम लिंक दर गणना को ठीक करता है जिसके कारण 4K डिस्प्ले (स्काइलेक, कैबी लेक, कॉफ़ी लेक, कॉमेट लेक) पर क्रैश या कोई सिग्नल नहीं होता है।',
      'ar': 'يعمل على إصلاح حساب الحد الأقصى لمعدل الارتباط Intel iGPU الذي يتسبب في حدوث أعطال أو عدم وجود إشارة على شاشات 4K (Skylake، وKaby Lake، وCoffee Lake، وComet Lake)',
      'id': 'Memperbaiki penghitungan kecepatan tautan maksimum Intel iGPU yang menyebabkan gangguan atau tidak ada sinyal pada tampilan 4K (Skylake, Kaby Lake, Coffee Lake, Comet Lake)',
    },
    'Fixes UI lag, boot logo freezes, audio/video sync anomalies, and sleep/wake failures': {
      'pt': 'Corrige atraso na interface do usuário, congelamento do logotipo de inicialização, anomalias na sincronização de áudio/vídeo e falhas de suspensão/despertar',
      'zh': '修复了 UI 延迟、启动徽标冻结、音频/视频同步异常以及睡眠/唤醒失败的问题',
      'zh_Hant': '修復了 UI 延遲、啟動徽標凍結、音訊/視訊同步異常以及睡眠/喚醒失敗的問題',
      'es': 'Corrige retrasos en la interfaz de usuario, congelaciones del logotipo de arranque, anomalías de sincronización de audio/vídeo y fallos de suspensión/activación.',
      'de': 'Behebt UI-Verzögerungen, einfrierendes Boot-Logo, Audio-/Video-Synchronisierungsanomalien und Sleep/Wake-Fehler',
      'fr': 'Corrige le décalage de l\'interface utilisateur, le gel du logo de démarrage, les anomalies de synchronisation audio/vidéo et les échecs de veille/réveil',
      'ru': 'Устраняет задержку пользовательского интерфейса, зависание логотипа загрузки, аномалии синхронизации аудио/видео, а также сбои режима сна/пробуждения.',
      'ja': 'UI の遅延、起動ロゴのフリーズ、オーディオ/ビデオ同期の異常、スリープ/スリープ解除の失敗を修正',
      'ko': 'UI 지연, 부팅 로고 정지, 오디오/비디오 동기화 이상, 잠자기/깨우기 오류 수정',
      'it': 'Risolve il ritardo dell\'interfaccia utente, il blocco del logo di avvio, le anomalie di sincronizzazione audio/video e gli errori di sospensione/riattivazione',
      'tr': 'Kullanıcı arayüzü gecikmesini, önyükleme logosu donmalarını, ses/video senkronizasyon anormalliklerini ve uyku/uyanma hatalarını düzeltir',
      'vi': 'Sửa lỗi lag giao diện người dùng, treo logo khởi động, bất thường về đồng bộ hóa âm thanh/video và lỗi ngủ/thức',
      'pl': 'Naprawia opóźnienia interfejsu użytkownika, zawieszanie się logo startowego, anomalie synchronizacji audio/wideo oraz błędy uśpienia/wybudzenia',
      'uk': 'Виправляє затримку інтерфейсу користувача, зависання логотипа завантаження, аномалії синхронізації аудіо/відео та збої в режимі сну/пробудження',
      'nl': 'Lost UI-vertraging op, het vastlopen van het opstartlogo, afwijkingen in de audio-/videosynchronisatie en slaap-/waakfouten',
      'hi': 'यूआई लैग, बूट लोगो फ्रीज, ऑडियो/वीडियो सिंक विसंगतियों और स्लीप/वेक विफलताओं को ठीक करता है',
      'ar': 'يعمل على إصلاح تأخر واجهة المستخدم، وتجميد شعار التمهيد، والحالات الشاذة في مزامنة الصوت/الفيديو، وفشل السكون/الاستيقاظ',
      'id': 'Memperbaiki kelambatan UI, logo boot macet, anomali sinkronisasi audio/video, dan kegagalan tidur/bangun',
