      'fr': 'Corrige les micro-bégaiements de l\'interface utilisateur, les gels aléatoires et les anomalies de synchronisation',
      'ru': 'Устраняет микроподвисания пользовательского интерфейса, случайные зависания и аномалии синхронизации.',
      'ja': 'UI の微小な途切れ、ランダムなフリーズ、同期の異常を修正',
      'ko': 'UI 미세 끊김, 무작위 정지 및 동기화 이상 현상을 수정합니다.',
      'it': 'Risolve i micro-stutter dell\'interfaccia utente, i blocchi casuali e le anomalie di sincronizzazione',
      'tr': 'Kullanıcı arayüzündeki mikro takılmaları, rastgele donmaları ve senkronizasyon anormalliklerini düzeltir',
      'vi': 'Sửa lỗi giao diện người dùng bị giật, treo ngẫu nhiên và bất thường về đồng bộ hóa',
      'pl': 'Naprawia mikrozacięcia interfejsu użytkownika, losowe zawieszanie się i anomalie synchronizacji',
      'uk': 'Виправляє мікрозависання інтерфейсу користувача, випадкові зависання та аномалії синхронізації',
