    'Fixes app crashes after disabling AMFI (requires SIP disabled)': {
      'pt': 'Corrige falhas de aplicativos após desativar AMFI (requer SIP desativado)',
      'zh': '修复了禁用 AMFI 后应用程序崩溃的问题（需要禁用 SIP）',
      'zh_Hant': '修正了禁用 AMFI 後應用程式崩潰的問題（需要停用 SIP）',
      'es': 'Soluciona fallas de la aplicación después de deshabilitar AMFI (requiere SIP deshabilitado)',
      'de': 'Behebt App-Abstürze nach der Deaktivierung von AMFI (erfordert deaktiviertes SIP)',
      'fr': 'Corrige le crash de l\'application après la désactivation d\'AMFI (nécessite SIP désactivé)',
      'ru': 'Исправляет сбои приложения после отключения AMFI (требуется отключенный SIP)',
      'ja': 'AMFI を無効にした後のアプリのクラッシュを修正 (SIP を無効にする必要があります)',
      'ko': 'AMFI 비활성화 후 앱 충돌 수정(SIP 비활성화 필요)',
