      'tr': 'AMFI\'yi devre dışı bıraktıktan sonra uygulama çökmelerini düzeltir (SIP\'in devre dışı bırakılmasını gerektirir)',
      'vi': 'Khắc phục sự cố ứng dụng sau khi tắt AMFI (yêu cầu tắt SIP)',
      'pl': 'Naprawia awarie aplikacji po wyłączeniu AMFI (wymaga wyłączenia SIP)',
      'uk': 'Виправляє збої програми після вимкнення AMFI (потрібно відключити SIP)',
      'nl': 'Lost app-crashes op na het uitschakelen van AMFI (vereist SIP uitgeschakeld)',
      'hi': 'AMFI को अक्षम करने के बाद ऐप क्रैश को ठीक करता है (SIP अक्षम होना आवश्यक है)',
      'ar': 'يعمل على إصلاح أعطال التطبيق بعد تعطيل AMFI (يتطلب تعطيل SIP)',
      'id': 'Memperbaiki aplikasi yang mogok setelah menonaktifkan AMFI (memerlukan SIP dinonaktifkan)',
    },
    'Fixes backlight registers on 7th/8th/9th Gen laptops on macOS < 13.4 to resolve 3-minute black/dim screen issues': {
      'pt': 'Corrige registros de luz de fundo em laptops de 7ª/8ª/9ª geração no macOS < 13.4 para resolver problemas de tela preta/escurecida de 3 minutos',
      'zh': '修复了 macOS < 13.4 上第 7/8/9 代笔记本电脑上的背光寄存器，以解决 3 分钟黑屏/暗屏问题',
      'zh_Hant': '修正了 macOS < 13.4 上第 7/8/9 代筆記型電腦上的背光寄存器，以解決 3 分鐘黑屏/暗屏問題',
      'es': 'Corrige los registros de retroiluminación en portátiles de 7.ª/8.ª/9.ª generación en macOS < 13.4 para resolver problemas de pantalla oscura/negra durante 3 minutos',
      'de': 'Behebt Probleme mit der Hintergrundbeleuchtung auf Laptops der 7./8./9. Generation unter macOS < 13.4, um Probleme mit 3-minütigen schwarzen/dunklen Bildschirmen zu beheben',
      'fr': 'Corrige les registres de rétroéclairage sur les ordinateurs portables de 7e/8e/9e génération sous macOS < 13.4 pour résoudre les problèmes d\'écran noir/assombri pendant 3 minutes',
      'ru': 'Исправляет регистры подсветки на ноутбуках 7/8/9 поколения на macOS < 13.4, чтобы устранить 3-минутные проблемы с черным/тусклым экраном.',
      'ja': 'macOS 13.4 未満の第 7/8/9 世代ラップトップのバックライト レジスタを修正し、3 分間画面が真っ黒/薄暗い問題を解決します。',
      'ko': 'macOS < 13.4의 7세대/8세대/9세대 노트북에서 백라이트 레지스터를 수정하여 3분간 검은색/어두운 화면 문제를 해결합니다.',
      'it': 'Corregge i registri di retroilluminazione sui laptop di 7a/8a/9a generazione su macOS < 13.4 per risolvere i problemi dello schermo nero/oscuro di 3 minuti',
      'tr': '3 dakikalık siyah/karanlık ekran sorunlarını çözmek için macOS < 13.4\'teki 7./8./9. Nesil dizüstü bilgisayarlardaki arka ışık kayıtlarını düzeltir',
      'vi': 'Sửa lỗi đăng ký đèn nền trên máy tính xách tay thế hệ thứ 7/8/9 trên macOS < 13.4 để giải quyết sự cố màn hình đen/mờ trong 3 phút',
      'pl': 'Naprawia rejestry podświetlenia w laptopach 7./8./9. generacji w systemie macOS < 13.4, aby rozwiązać problemy z czarnym/przyciemnionym ekranem trwającym 3 minuty',
      'uk': 'Виправляє регістри підсвічування на ноутбуках 7-го/8-го/9-го поколінь на macOS < 13.4, щоб вирішити проблеми з 3-хвилинним чорним/тьмяним екраном',
      'nl': 'Oplossing voor achtergrondverlichtingsregisters op laptops van de 7e/8e/9e generatie op macOS < 13.4 om problemen met zwart/donker scherm na 3 minuten op te lossen',
      'hi': '3 मिनट की ब्लैक/डिम स्क्रीन समस्याओं को हल करने के लिए macOS <13.4 पर 7वीं/8वीं/9वीं पीढ़ी के लैपटॉप पर बैकलाइट रजिस्टर को ठीक करता है',
      'ar': 'يعمل على إصلاح تسجيلات الإضاءة الخلفية على أجهزة الكمبيوتر المحمولة من الجيل السابع/الثامن/التاسع التي تعمل بنظام التشغيل macOS <13.4 لحل مشكلات الشاشة السوداء/المعتمة لمدة 3 دقائق',
      'id': 'Memperbaiki register lampu latar pada laptop Generasi ke-7/8/9 dengan macOS <13.4 untuk mengatasi masalah layar hitam/redup selama 3 menit',
    },
    'Fixes backlight registers on 7th/8th/9th Gen laptops on macOS >= 13.4 to resolve 3-minute black/dim screen issues': {
      'pt': 'Corrige registros de luz de fundo em laptops de 7ª/8ª/9ª geração no macOS >= 13.4 para resolver problemas de tela preta/escurecida de 3 minutos',
      'zh': '修复了 macOS >= 13.4 上第 7/8/9 代笔记本电脑上的背光寄存器，以解决 3 分钟黑屏/暗屏问题',
      'zh_Hant': '修正了 macOS >= 13.4 上第 7/8/9 代筆記型電腦上的背光寄存器，以解決 3 分鐘黑屏/暗屏問題',
      'es': 'Corrige los registros de retroiluminación en portátiles de 7.ª/8.ª/9.ª generación en macOS >= 13.4 para resolver problemas de pantalla negra/tenue durante 3 minutos',
