      'ru': 'Исправляет регистры подсветки на ноутбуках 7/8/9 поколения на macOS >= 13.4 для устранения 3-минутных проблем с черным/тусклым экраном.',
      'ja': 'macOS 13.4 以降の第 7/8/9 世代ラップトップのバックライト レジスタを修正し、3 分間画面が真っ黒/薄暗い問題を解決します。',
      'ko': 'macOS 13.4 이상의 7세대/8세대/9세대 노트북에서 백라이트 레지스터를 수정하여 3분 동안 검은색/어두운 화면 문제를 해결합니다.',
      'it': 'Corregge i registri di retroilluminazione sui laptop di 7a/8a/9a generazione su macOS >= 13.4 per risolvere i problemi dello schermo nero/oscuro di 3 minuti',
      'tr': '3 dakikalık siyah/karanlık ekran sorunlarını çözmek için macOS >= 13.4 işletim sistemine sahip 7./8./9. Nesil dizüstü bilgisayarlardaki arka ışık kayıtlarını düzeltir',
      'vi': 'Sửa lỗi đăng ký đèn nền trên máy tính xách tay thế hệ thứ 7/8/9 trên macOS >= 13.4 để giải quyết sự cố màn hình đen/mờ trong 3 phút',
      'pl': 'Naprawia rejestry podświetlenia w laptopach 7./8./9. generacji w systemie macOS >= 13.4, aby rozwiązać problemy z czarnym/przyciemnionym ekranem trwającym 3 minuty',
      'uk': 'Виправляє регістри підсвічування на ноутбуках 7-го/8-го/9-го поколінь на macOS >= 13.4, щоб вирішити проблеми з 3-хвилинним чорним/тьмяним екраном',
      'nl': 'Oplossing voor achtergrondverlichtingsregisters op laptops van de 7e/8e/9e generatie op macOS >= 13.4 om problemen met het zwart/donkere scherm van 3 minuten op te lossen',
      'hi': '3 मिनट की ब्लैक/डिम स्क्रीन समस्याओं को हल करने के लिए macOS>=13.4 पर 7वीं/8वीं/9वीं पीढ़ी के लैपटॉप पर बैकलाइट रजिस्टर को ठीक करता है',
      'ar': 'يعمل على إصلاح تسجيلات الإضاءة الخلفية على أجهزة الكمبيوتر المحمولة من الجيل السابع/الثامن/التاسع التي تعمل بنظام التشغيل macOS >= 13.4 لحل مشكلات الشاشة السوداء/المعتمة لمدة 3 دقائق',
      'id': 'Memperbaiki register lampu latar pada laptop Generasi ke-7/8/9 di macOS >= 13.4 untuk menyelesaikan masalah layar hitam/redup selama 3 menit',
    },
    'Fixes boot hang at [PCI Configuration Begin] when Above 4G Decoding is disabled (mutually exclusive with npci=0x2000; common on X58/X79/X99/AMD)': {
      'pt': 'Corrige o travamento da inicialização em [Início da configuração PCI] quando a decodificação acima de 4G está desativada (mutuamente exclusivo com npci = 0x2000; comum em X58/X79/X99/AMD)',
      'zh': '修复了禁用以上 4G 解码时在 [PCI 配置开始] 处的启动挂起（与 npci=0x2000 互斥；在 X58/X79/X99/AMD 上常见）',
      'zh_Hant': '修正了禁用以上 4G 解碼時在 [PCI 配置開始] 處的啟動掛起（與 npci=0x2000 互斥；在 X58/X79/X99/AMD 上常見）',
      'es': 'Soluciona el bloqueo del arranque en [Inicio de configuración PCI] cuando la decodificación por encima de 4G está deshabilitada (mutuamente excluyente con npci=0x2000; común en X58/X79/X99/AMD)',
      'de': 'Behebt das Boot-Hängen bei [PCI-Konfigurationsbeginn], wenn die Decodierung über 4G deaktiviert ist (schließt sich gegenseitig aus mit npci=0x2000; häufig bei X58/X79/X99/AMD)',
      'fr': 'Corrige le blocage du démarrage à [PCI Configuration Begin] lorsque le décodage au-dessus de 4G est désactivé (mutuellement exclusif avec npci=0x2000 ; commun sur X58/X79/X99/AMD)',
      'ru': 'Исправлено зависание загрузки в [Начало конфигурации PCI], когда отключено декодирование выше 4G (взаимоисключающее явление с npci=0x2000; обычно для X58/X79/X99/AMD).',
      'ja': 'Above 4G デコードが無効になっている場合の [PCI Configuration Begin] でのブートハングを修正 (npci=0x2000 と相互に排他的、X58/X79/X99/AMD で共通)',
      'ko': 'Above 4G Decoding이 비활성화된 경우 [PCI 구성 시작]에서 부팅이 중단되는 문제 수정(npci=0x2000과 상호 배타적, X58/X79/X99/AMD에서 공통)',
      'it': 'Risolto il problema con il blocco dell\'avvio in [Inizio configurazione PCI] quando la decodifica superiore a 4G è disabilitata (si escludono a vicenda con npci=0x2000; comune su X58/X79/X99/AMD)',
      'tr': '4G Üstü Kod Çözme devre dışı bırakıldığında [PCI Yapılandırma Başlangıcı] sırasındaki önyükleme askılığını düzeltir (npci=0x2000 ile birbirini dışlar; X58/X79/X99/AMD\'de ortaktır)',
      'vi': 'Sửa lỗi treo khởi động ở [Bắt đầu cấu hình PCI] khi Giải mã trên 4G bị tắt (loại trừ lẫn nhau với npci=0x2000; phổ biến trên X58/X79/X99/AMD)',
      'pl': 'Naprawiono zawieszanie się rozruchu w [Początek konfiguracji PCI], gdy dekodowanie powyżej 4G jest wyłączone (wzajemnie wykluczające się z npci=0x2000; powszechne w X58/X79/X99/AMD)',
      'uk': 'Виправлено зависання завантаження на [Початок конфігурації PCI], коли декодування вище 4G вимкнено (взаємовиключне з npci=0x2000; поширене на X58/X79/X99/AMD)',
      'nl': 'Oplossing voor het vastlopen bij opstarten bij [PCI Configuration Begin] wanneer decodering boven 4G is uitgeschakeld (mutueel exclusief met npci=0x2000; gebruikelijk op X58/X79/X99/AMD)',
      'hi': 'उपरोक्त 4जी डिकोडिंग अक्षम होने पर [पीसीआई कॉन्फ़िगरेशन प्रारंभ] पर बूट हैंग को ठीक करता है (npci=0x2000 के साथ परस्पर अनन्य; X58/X79/X99/AMD पर सामान्य)',
      'ar': 'إصلاح توقف التمهيد عند [بدء تكوين PCI] عند تعطيل فك التشفير فوق 4G (حصريًا بشكل متبادل مع npci=0x2000؛ شائع في X58/X79/X99/AMD)',
      'id': 'Memperbaiki boot hang di [PCI Configuration Begin] ketika Decoding 4G Di Atas dinonaktifkan (saling eksklusif dengan npci=0x2000; umum pada X58/X79/X99/AMD)',
    },
    'Fixes boot hang at [PCI Configuration Begin] when Above 4G Decoding is disabled (mutually exclusive with npci=0x3000; common on X58/X79/X99/AMD)': {
      'pt': 'Corrige o travamento da inicialização em [Início da configuração PCI] quando a decodificação acima de 4G está desativada (mutuamente exclusivo com npci = 0x3000; comum em X58/X79/X99/AMD)',
      'zh': '修复了禁用以上 4G 解码时在 [PCI 配置开始] 处的启动挂起（与 npci=0x3000 互斥；在 X58/X79/X99/AMD 上常见）',
      'zh_Hant': '修正了停用以上 4G 解碼時在 [PCI 配置開始] 處的啟動掛起（與 npci=0x3000 互斥；在 X58/X79/X99/AMD 上常見）',
      'es': 'Soluciona el bloqueo del arranque en [Inicio de configuración PCI] cuando la decodificación por encima de 4G está deshabilitada (mutuamente excluyente con npci=0x3000; común en X58/X79/X99/AMD)',
      'de': 'Behebt Boot-Hang bei [PCI-Konfigurationsbeginn], wenn die Decodierung über 4G deaktiviert ist (schließt sich gegenseitig aus mit npci=0x3000; häufig bei X58/X79/X99/AMD)',
      'fr': 'Corrige le blocage du démarrage à [PCI Configuration Begin] lorsque le décodage au-dessus de 4G est désactivé (mutuellement exclusif avec npci=0x3000 ; commun sur X58/X79/X99/AMD)',
      'ru': 'Исправлено зависание загрузки на этапе [Начало конфигурации PCI], когда отключено декодирование выше 4G (взаимоисключающее явление с npci=0x3000; обычно для X58/X79/X99/AMD).',
      'ja': 'Above 4G Decoding が無効になっている場合の [PCI Configuration Begin] でのブートハングを修正 (npci=0x3000 と相互に排他的、X58/X79/X99/AMD で共通)',
      'ko': 'Above 4G Decoding이 비활성화된 경우 [PCI 구성 시작]에서 부팅이 중단되는 문제 수정(npci=0x3000과 상호 배타적, X58/X79/X99/AMD에서 공통)',
      'it': 'Risolto il problema con il blocco dell\'avvio in [Inizio configurazione PCI] quando la decodifica superiore a 4G è disabilitata (si escludono a vicenda con npci=0x3000; comune su X58/X79/X99/AMD)',
      'tr': '4G Üstü Kod Çözme devre dışı bırakıldığında [PCI Yapılandırma Başlangıcı] sırasındaki önyükleme askısını düzeltir (npci=0x3000 ile birbirini dışlar; X58/X79/X99/AMD\'de ortaktır)',
      'vi': 'Sửa lỗi treo khởi động ở [Bắt đầu cấu hình PCI] khi Giải mã trên 4G bị tắt (loại trừ lẫn nhau với npci=0x3000; phổ biến trên X58/X79/X99/AMD)',
      'pl': 'Naprawiono zawieszanie się rozruchu przy [Początek konfiguracji PCI], gdy dekodowanie powyżej 4G jest wyłączone (wzajemnie wykluczające się z npci=0x3000; powszechne w X58/X79/X99/AMD)',
      'uk': 'Виправлено зависання при завантаженні [PCI Configuration Begin], коли декодування вище 4G вимкнено (взаємовиключне з npci=0x3000; поширене на X58/X79/X99/AMD)',
