    'Fixes infinite loop on 6th/7th/8th Gen Intel iGPUs when connecting external HDMI displays (internal screen blacks out with backlight, system freezes)': {
      'pt': 'Corrige loop infinito em iGPUs Intel de 6ª/7ª/8ª geração ao conectar monitores HDMI externos (a tela interna escurece com a luz de fundo, o sistema congela)',
      'zh': '修复了连接外部 HDMI 显示器时第 6/7/8 代 Intel iGPU 上的无限循环（内部屏幕因背光而变黑，系统冻结）',
      'zh_Hant': '修正了連接外部 HDMI 顯示器時第 6/7/8 代 Intel iGPU 上的無限循環（內部螢幕因背光而變黑，系統凍結）',
      'es': 'Corrige el bucle infinito en las iGPU Intel de 6.ª/7.ª/8.ª generación al conectar pantallas HDMI externas (la pantalla interna se oscurece con la luz de fondo, el sistema se congela)',
      'de': 'Behebt eine Endlosschleife auf Intel iGPUs der 6./7./8. Generation beim Anschluss externer HDMI-Displays (interner Bildschirm wird bei Hintergrundbeleuchtung schwarz, System friert ein)',
      'fr': 'Corrige la boucle infinie sur les iGPU Intel de 6e/7e/8e génération lors de la connexion d\'écrans HDMI externes (l\'écran interne s\'assombrit avec le rétroéclairage, le système se fige)',
      'ru': 'Исправлен бесконечный цикл на iGPU Intel 6-го, 7-го и 8-го поколения при подключении внешних дисплеев HDMI (внутренний экран затемняется из-за подсветки, система зависает).',
      'ja': '外部 HDMI ディスプレイを接続する際の第 6/7/8 世代 Intel iGPU の無限ループを修正 (バックライトで内部画面がブラックアウトし、システムがフリーズする)',
      'ko': '외부 HDMI 디스플레이를 연결할 때 6세대/7세대/8세대 Intel iGPU의 무한 루프 수정(내부 화면이 백라이트로 인해 어두워지고 시스템이 정지됨)',
      'it': 'Risolto il problema del loop infinito sulle iGPU Intel di sesta/settima/ottava generazione quando si collegavano display HDMI esterni (lo schermo interno si oscura con retroilluminazione, il sistema si blocca)',
      'tr': 'Harici HDMI ekranları bağlarken 6./7./8. Nesil Intel iGPU\'larda sonsuz döngüyü düzeltir (dahili ekran arka ışık nedeniyle kararır, sistem donar)',
      'vi': 'Khắc phục vòng lặp vô hạn trên Intel iGPU thế hệ thứ 6/7/8 khi kết nối màn hình HDMI bên ngoài (màn hình bên trong bị đen do đèn nền, hệ thống bị treo)',
      'pl': 'Naprawiono nieskończoną pętlę w procesorach Intel iGPU 6./7./8. generacji podczas podłączania zewnętrznych wyświetlaczy HDMI (ekran wewnętrzny przyciemnia się z powodu podświetlenia, system zawiesza się)',
      'uk': 'Виправляє нескінченне зациклення на графічних процесорах Intel 6-го/7-го/8-го поколінь під час підключення зовнішніх дисплеїв HDMI (внутрішній екран затемнюється з підсвічуванням, система зависає)',
