    'Forces online status on all displays; helps with multi-display output and avoids black screen after sleep (for 8th Gen Coffee Lake+ iGPUs)': {
      'pt': 'Força o status online em todos os monitores; ajuda com saída multi-display e evita tela preta após suspensão (para iGPUs Coffee Lake+ de 8ª geração)',
