      'ja': 'すべてのディスプレイでオンライン状態を強制します。マルチディスプレイ出力をサポートし、スリープ後の黒い画面を回避します (第 8 世代 Coffee Lake+ iGPU の場合)',
      'ko': '모든 디스플레이에 온라인 상태를 적용합니다. 다중 디스플레이 출력에 도움이 되며 절전 모드 후 검은색 화면을 방지합니다(8세대 Coffee Lake+ iGPU의 경우).',
