      'tr': 'Tüm ekranlarda çevrimiçi durumu zorunlu kılar; çoklu ekran çıkışına yardımcı olur ve uyku sonrasında siyah ekranı önler (8. Nesil Coffee Lake+ iGPU\'lar için)',
      'vi': 'Buộc trạng thái trực tuyến trên tất cả các màn hình; hỗ trợ đầu ra đa màn hình và tránh màn hình đen sau khi ngủ (đối với Coffee Lake+ iGPU thế hệ thứ 8)',
      'pl': 'Wymusza stan online na wszystkich wyświetlaczach; pomaga w wyświetlaniu obrazu na wielu wyświetlaczach i pozwala uniknąć czarnego ekranu po uśpieniu (dla procesorów iGPU Coffee Lake+ 8. generacji)',
      'uk': 'Примусовий статус онлайн на всіх дисплеях; допомагає з виведенням на багато дисплеїв і запобігає чорному екрану після сну (для графічних процесорів Coffee Lake+ 8-го покоління)',
      'nl': 'Forceert de onlinestatus op alle beeldschermen; helpt bij uitvoer op meerdere schermen en vermijdt een zwart scherm na de slaapstand (voor 8e generatie Coffee Lake+ iGPU\'s)',
      'hi': 'सभी डिस्प्ले पर ऑनलाइन स्थिति को बाध्य करता है; helps with multi-display output and avoids black screen after sleep (for 8th Gen Coffee Lake+ iGPUs)',
      'ar': 'يفرض حالة الاتصال بالإنترنت على جميع شاشات العرض؛ يساعد في إخراج الشاشات المتعددة ويتجنب الشاشة السوداء بعد النوم (لوحدات الجيل الثامن Coffee Lake+ iGPU)',
      'id': 'Memaksa status online di semua tampilan; membantu output multi-display dan menghindari layar hitam setelah mode tidur (untuk iGPU Coffee Lake+ Generasi ke-8)',
    },
