      'ja': '安定性に問題がある可能性があります。 Big Sur に滞在し、SmallTree を使用することをお勧めします',
      'ko': '안정성 문제가 있을 수 있습니다. Big Sur에 머무르고 SmallTree를 사용하는 것이 좋습니다.',
      'it': 'Potrebbe avere problemi di stabilità; consiglio di soggiornare a Big Sur e di utilizzare SmallTree',
