      'vi': 'Có thể có vấn đề về độ ổn định; khuyên bạn nên ở lại Big Sur và sử dụng SmallTree',
      'pl': 'Może mieć problemy ze stabilnością; polecam pobyt na Big Sur i korzystanie z SmallTree',
      'uk': 'Можуть виникнути проблеми зі стабільністю; рекомендую залишатися на Big Sur і використовувати SmallTree',
      'nl': 'Kan stabiliteitsproblemen hebben; raad aan om op Big Sur te blijven en SmallTree te gebruiken',
      'hi': 'स्थिरता संबंधी समस्याएँ हो सकती हैं; बिग सुर पर रहने और स्मॉलट्री का उपयोग करने की सलाह देते हैं',
      'ar': 'قد يكون لديك مشاكل في الاستقرار؛ أوصي بالبقاء في Big Sur واستخدام SmallTree',
