    'Microsoft Surface dedicated keyboard, trackpad, and touchscreen driver suite.': {
      'pt': 'Conjunto de teclado, trackpad e driver de tela sensível ao toque dedicados do Microsoft Surface.',
      'zh': 'Microsoft Surface 专用键盘、触控板和触摸屏驱动程序套件。',
      'zh_Hant': 'Microsoft Surface 專用鍵盤、觸控板和觸控螢幕驅動程式套件。',
      'es': 'Conjunto de controladores de pantalla táctil, trackpad y teclado dedicado de Microsoft Surface.',
      'de': 'Spezielle Treibersuite für Tastatur, Trackpad und Touchscreen für Microsoft Surface.',
      'fr': 'Suite de pilotes dédiés au clavier, au trackpad et à l\'écran tactile Microsoft Surface.',
      'ru': 'Специальный пакет драйверов для клавиатуры, трекпада и сенсорного экрана Microsoft Surface.',
      'ja': 'Microsoft Surface 専用のキーボード、トラックパッド、およびタッチスクリーン ドライバー スイート。',
      'ko': 'Microsoft Surface 전용 키보드, 트랙패드 및 터치스크린 드라이버 제품군.',
      'it': 'Suite di driver dedicata per tastiera, trackpad e touchscreen Microsoft Surface.',
      'tr': 'Microsoft Surface\'a özel klavye, izleme dörtgeni ve dokunmatik ekran sürücü paketi.',
      'vi': 'Bộ trình điều khiển màn hình cảm ứng, bàn di chuột và bàn phím chuyên dụng của Microsoft Surface.',
      'pl': 'Dedykowana klawiatura, gładzik i sterownik ekranu dotykowego dla Microsoft Surface.',
      'uk': 'Набір драйверів спеціальної клавіатури, трекпада та сенсорного екрана Microsoft Surface.',
      'nl': 'Speciaal Microsoft Surface-stuurprogramma voor toetsenbord, trackpad en touchscreen.',
      'hi': 'Microsoft Surface समर्पित कीबोर्ड, ट्रैकपैड और टचस्क्रीन ड्राइवर सुइट।',
      'ar': 'لوحة مفاتيح Microsoft Surface المخصصة ولوحة التتبع ومجموعة برامج تشغيل الشاشة التي تعمل باللمس.',
      'id': 'Rangkaian driver keyboard, trackpad, dan layar sentuh khusus Microsoft Surface.',
    },
    'NVIDIA GPU Support Summary:\n    • Tesla Series (8000 - 300 series): Natively supported up to macOS High Sierra 10.13.x (may require NVCAP fix); higher versions require OCLP (no Metal support).\n       e.g.: 8600GT, 9600GT, GT210, GT220, GT240 etc. Obsolete hardware, not recommended!\n    • Kepler Series (600 - 800 series): Natively supported up to macOS Big Sur 11.x; higher versions require OCLP (supports Metal, full acceleration).\n       Kepler consumer: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black etc.\n       Kepler workstation: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 etc.\n    • Fermi, Maxwell, Pascal Series: Web Driver supported up to macOS High Sierra 10.13.x; macOS Big Sur 11.x+ requires boot-args below plus OCLP patch (no Metal support).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 etc.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 etc.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 etc.\n  Unsupported NVIDIA GPUs (Turing, Ampere, Ada Lovelace, Blackwell - no macOS support):\n    • 16xx ~ 50xx series: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 etc.': {
      'pt': 'Resumo do suporte à GPU NVIDIA:\n    • Série Tesla (série 8000 - 300): suporte nativo até macOS High Sierra 10.13.x (pode exigir correção NVCAP); versões superiores requerem OCLP (sem suporte Metal).\n       por exemplo: 8600GT, 9600GT, GT210, GT220, GT240 etc. Hardware obsoleto, não recomendado!\n    • Série Kepler (série 600 - 800): suporte nativo até macOS Big Sur 11.x; versões superiores requerem OCLP (suporta Metal, aceleração total).\n       Consumidor Kepler: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black etc.\n       Estação de trabalho Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 etc.\n    • Série Fermi, Maxwell, Pascal: Web Driver compatível até macOS High Sierra 10.13.x; O macOS Big Sur 11.x+ requer argumentos de inicialização abaixo, além do patch OCLP (sem suporte para Metal).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 etc.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 etc.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 etc.\n  GPUs NVIDIA não suportadas (Turing, Ampere, Ada Lovelace, Blackwell - sem suporte para macOS):\n    • Série 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 etc.',
      'zh': 'NVIDIA GPU 支持摘要：\n    • Tesla 系列（8000 - 300 系列）：本机支持最高可达 macOS High Sierra 10.13.x（可能需要 NVCAP 修复）；更高版本需要 OCLP（无 Metal 支持）。\n       例如：8600GT、9600GT、GT210、GT220、GT240等。过时的硬件，不推荐！\n    • Kepler 系列（600 - 800 系列）：原生支持 macOS Big Sur 11.x；高版本需要OCLP（支持Metal，全加速）。\n       Kepler消费类：GT630、GT635、GT640、GTX650、GTX660、GTX680、GT710、GT720、GT730、GT740、GTX760、GTX Titan Z、GTX Titan Black等。\n       开普勒工作站：NVS 510、Quadro 410、Quadro K420、Quadro K600、Quadro K2000 等。\n    • Fermi、Maxwell、Pascal 系列：最高支持 macOS High Sierra 10.13.x 的 Web 驱动程序； macOS Big Sur 11.x+ 需要以下启动参数以及 OCLP 补丁（不支持 Metal）。\n       费米：GT605、GT610、GT620、GT630、GT705、GT710、GT720、GT730、GT740等\n       麦克斯韦：GTX750、GTX750Ti、GTX950、GTX960、GTX970、GTX980等\n       帕斯卡：GTX1050、GTX1060、GTX1070、GTX1080等\n  不支持的 NVIDIA GPU（Turing、Ampere、Ada Lovelace、Blackwell - 不支持 macOS）：\n    • 16xx ~ 50xx 系列：GTX 1650、GTX 1660、RTX 2060、RTX 3060、RTX 4060、RTX 5070 等。',
      'zh_Hant': 'NVIDIA GPU 支援摘要：\n    • Tesla 系列（8000 - 300 系列）：本機支援最高可達 macOS High Sierra 10.13.x（可能需要 NVCAP 修復）；更高版本需要 OCLP（無 Metal 支援）。\n       例如：8600GT、9600GT、GT210、GT220、GT240等。過時的硬件，不推薦！\n    • Kepler 系列（600 - 800 系列）：原生支援 macOS Big Sur 11.x；高版本需要OCLP（支援Metal，全加速）。\n       Kepler消費類：GT630、GT635、GT640、GTX650、GTX660、GTX680、GT710、GT720、GT730、GT740、GTX760、GTX Titan Z、GTX Titan Black等。\n       開普勒工作站：NVS 510、Quadro 410、Quadro K420、Quadro K600、Quadro K2000 等。\n    • Fermi、Maxwell、Pascal 系列：最高支援 macOS High Sierra 10.13.x 的 Web 驅動程式； macOS Big Sur 11.x+ 需要以下啟動參數以及 OCLP 修補程式（不支援 Metal）。\n       費米：GT605、GT610、GT620、GT630、GT705、GT710、GT720、GT730、GT740等\n       麥克斯韋：GTX750、GTX750Ti、GTX950、GTX960、GTX970、GTX980等\n       帕斯卡：GTX1050、GTX1060、GTX1070、GTX1080等\n  不支援的 NVIDIA GPU（Turing、Ampere、Ada Lovelace、Blackwell - 不支援 macOS）：\n    • 16xx ~ 50xx 系列：GTX 1650、GTX 1660、RTX 2060、RTX 3060、RTX 4060、RTX 5070 等。',
      'es': 'Resumen de soporte de GPU NVIDIA:\n    • Serie Tesla (series 8000 - 300): compatible de forma nativa hasta macOS High Sierra 10.13.x (puede requerir solución NVCAP); Las versiones superiores requieren OCLP (sin soporte metálico).\n       por ejemplo: 8600GT, 9600GT, GT210, GT220, GT240, etc. Hardware obsoleto, ¡no recomendado!\n    • Serie Kepler (series 600 - 800): compatible de forma nativa hasta macOS Big Sur 11.x; Las versiones superiores requieren OCLP (admite Metal, aceleración total).\n       Consumidor Kepler: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black, etc.\n       Estación de trabajo Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000, etc.\n    • Serie Fermi, Maxwell, Pascal: controlador web compatible hasta macOS High Sierra 10.13.x; macOS Big Sur 11.x+ requiere los argumentos de arranque a continuación más el parche OCLP (no es compatible con Metal).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740, etc.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980, etc.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080, etc.\n  GPU NVIDIA no compatibles (Turing, Ampere, Ada Lovelace, Blackwell; no son compatibles con macOS):\n    • Serie 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070, etc.',
      'de': 'Zusammenfassung der NVIDIA GPU-Unterstützung:\n    • Tesla-Serie (8000-300-Serie): Native Unterstützung bis macOS High Sierra 10.13.x (möglicherweise ist ein NVCAP-Fix erforderlich); Höhere Versionen erfordern OCLP (keine Metal-Unterstützung).\n       z.B.: 8600GT, 9600GT, GT210, GT220, GT240 etc. Veraltete Hardware, nicht empfohlen!\n    • Kepler-Serie (600-800-Serie): Native Unterstützung bis macOS Big Sur 11.x; Höhere Versionen erfordern OCLP (unterstützt Metal, volle Beschleunigung).\n       Kepler-Verbraucher: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black usw.\n       Kepler-Workstation: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 usw.\n    • Fermi-, Maxwell- und Pascal-Serie: Web-Treiber unterstützt bis macOS High Sierra 10.13.x; macOS Big Sur 11.x+ erfordert die folgenden Boot-Argumente plus OCLP-Patch (keine Metal-Unterstützung).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 usw.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 usw.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 usw.\n  Nicht unterstützte NVIDIA-GPUs (Turing, Ampere, Ada Lovelace, Blackwell – keine macOS-Unterstützung):\n    • 16xx ~ 50xx-Serie: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 usw.',
      'fr': 'Résumé de la prise en charge des GPU NVIDIA :\n    • Série Tesla (séries 8000 à 300) : prise en charge nativement jusqu\'à macOS High Sierra 10.13.x (peut nécessiter un correctif NVCAP) ; les versions supérieures nécessitent OCLP (pas de support Metal).\n       ex. : 8600GT, 9600GT, GT210, GT220, GT240 etc. Matériel obsolète, déconseillé !\n    • Série Kepler (séries 600 à 800) : prise en charge nativement jusqu\'à macOS Big Sur 11.x ; les versions supérieures nécessitent OCLP (prend en charge Metal, accélération complète).\n       Consommateur Kepler : GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black, etc.\n       Poste de travail Kepler : NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 etc.\n    • Séries Fermi, Maxwell, Pascal : pilote Web pris en charge jusqu\'à macOS High Sierra 10.13.x ; macOS Big Sur 11.x+ nécessite les arguments de démarrage ci-dessous ainsi qu\'un correctif OCLP (pas de prise en charge de Metal).\n       Fermi : GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740, etc.\n       Maxwell : GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980, etc.\n       Pascal : GTX1050, GTX1060, GTX1070, GTX1080 etc.\n  GPU NVIDIA non pris en charge (Turing, Ampere, Ada Lovelace, Blackwell - pas de support macOS) :\n    • Séries 16xx ~ 50xx : GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070, etc.',
      'ru': 'Сводка о поддержке графических процессоров NVIDIA:\n    • Серия Tesla (серии 8000–300): встроенная поддержка до macOS High Sierra 10.13.x (может потребоваться исправление NVCAP); более высокие версии требуют OCLP (без поддержки Metal).\n       например: 8600GT, 9600GT, GT210, GT220, GT240 и т. д. Устаревшее оборудование, не рекомендуется!\n    • Серия Kepler (серии 600–800): встроенная поддержка до macOS Big Sur 11.x; более высокие версии требуют OCLP (поддерживает Metal, полное ускорение).\n       Потребительские модели Kepler: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black и т. д.\n       Рабочая станция Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 и т. д.\n    • Серия Fermi, Maxwell, Pascal: веб-драйвер поддерживается до macOS High Sierra 10.13.x; Для macOS Big Sur 11.x+ требуются аргументы загрузки, указанные ниже, а также патч OCLP (без поддержки Metal).\n       Ферми: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 и т. д.\n       Максвелл: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 и т. д.\n       Паскаль: GTX1050, GTX1060, GTX1070, GTX1080 и т. д.\n  Неподдерживаемые графические процессоры NVIDIA (Turing, Ampere, Ada Lovelace, Blackwell — без поддержки macOS):\n    • Серия 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 и т. д.',
      'ja': 'NVIDIA GPU サポートの概要:\n    • Tesla シリーズ (8000 ～ 300 シリーズ): macOS High Sierra 10.13.x までネイティブでサポートされています (NVCAP 修正が必要な場合があります)。上位バージョンでは OCLP が必要です (メタル サポートなし)。\n       例: 8600GT、9600GT、GT210、GT220、GT240 など。旧式のハードウェアのため推奨されません。\n    • Kepler シリーズ (600 - 800 シリーズ): macOS Big Sur 11.x までネイティブでサポートされています。上位バージョンには OCLP (メタル、フル アクセラレーションをサポート) が必要です。\n       Kepler コンシューマー: GT630、GT635、GT640、GTX650、GTX660、GTX680、GT710、GT720、GT730、GT740、GTX760、GTX Titan Z、GTX Titan Black など。\n       Kepler ワークステーション: NVS 510、Quadro 410、Quadro K420、Quadro K600、Quadro K2000 など。\n    • Fermi、Maxwell、Pascal シリーズ: Web ドライバーは macOS High Sierra 10.13.x までサポートされます。 macOS Big Sur 11.x+ では、以下のブート引数に加えて OCLP パッチが必要です (Metal サポートなし)。\n       フェルミ: GT605、GT610、GT620、GT630、GT705、GT710、GT720、GT730、GT740など。\n       マクスウェル: GTX750、GTX750Ti、GTX950、GTX960、GTX970、GTX980など。\n       パスカル: GTX1050、GTX1060、GTX1070、GTX1080など。\n  サポートされていない NVIDIA GPU (Turing、Ampere、Ada Lovelace、Blackwell - macOS サポートなし):\n    • 16xx ～ 50xx シリーズ: GTX 1650、GTX 1660、RTX 2060、RTX 3060、RTX 4060、RTX 5070 など。',
      'ko': 'NVIDIA GPU 지원 요약:\n    • Tesla 시리즈(8000 - 300 시리즈): macOS High Sierra 10.13.x까지 기본적으로 지원됩니다(NVCAP 수정이 필요할 수 있음). 상위 버전에는 OCLP가 필요합니다(Metal 지원 없음).\n       예: 8600GT, 9600GT, GT210, GT220, GT240 등. 오래된 하드웨어이므로 권장하지 않습니다!\n    • Kepler 시리즈(600 - 800 시리즈): 최대 macOS Big Sur 11.x까지 기본적으로 지원됩니다. 상위 버전에는 OCLP가 필요합니다(Metal, 전체 가속 지원).\n       케플러 소비자: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black 등\n       Kepler 워크스테이션: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 등\n    • Fermi, Maxwell, Pascal 시리즈: 웹 드라이버는 macOS High Sierra 10.13.x까지 지원됩니다. macOS Big Sur 11.x+에는 아래 boot-args와 OCLP 패치(Metal 지원 없음)가 필요합니다.\n       페르미: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 등.\n       맥스웰: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 등.\n       파스칼: GTX1050, GTX1060, GTX1070, GTX1080 등\n  지원되지 않는 NVIDIA GPU(Turing, Ampere, Ada Lovelace, Blackwell - macOS 지원 안 함):\n    • 16xx ~ 50xx 시리즈: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 등.',
      'it': 'Riepilogo del supporto GPU NVIDIA:\n    • Serie Tesla (serie 8000 - 300): supportata nativamente fino a macOS High Sierra 10.13.x (potrebbe richiedere la correzione NVCAP); le versioni superiori richiedono OCLP (nessun supporto Metal).\n       es.: 8600GT, 9600GT, GT210, GT220, GT240 ecc. Hardware obsoleto, sconsigliato!\n    • Serie Kepler (serie 600 - 800): supportata nativamente fino a macOS Big Sur 11.x; le versioni superiori richiedono OCLP (supporta Metal, accelerazione completa).\n       Consumatore Kepler: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black ecc.\n       Workstation Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 ecc.\n    • Serie Fermi, Maxwell, Pascal: driver Web supportato fino a macOS High Sierra 10.13.x; macOS Big Sur 11.x+ richiede gli argomenti di avvio riportati di seguito più la patch OCLP (nessun supporto Metal).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 ecc.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 ecc.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 ecc.\n  GPU NVIDIA non supportate (Turing, Ampere, Ada Lovelace, Blackwell - nessun supporto macOS):\n    • Serie 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 ecc.',
      'tr': 'NVIDIA GPU Desteği Özeti:\n    • Tesla Serisi (8000 - 300 serisi): macOS High Sierra 10.13.x\'e kadar yerel olarak desteklenir (NVCAP düzeltmesi gerektirebilir); daha yüksek sürümler OCLP gerektirir (Metal desteği yoktur).\n       örneğin: 8600GT, 9600GT, GT210, GT220, GT240 vb. Eski donanım, önerilmez!\n    • Kepler Serisi (600 - 800 serisi): macOS Big Sur 11.x\'e kadar yerel olarak desteklenir; daha yüksek sürümler OCLP gerektirir (Metal\'i destekler, tam hızlandırma).\n       Kepler tüketicisi: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black vb.\n       Kepler iş istasyonu: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 vb.\n    • Fermi, Maxwell, Pascal Serisi: Web Sürücüsü, macOS High Sierra 10.13.x\'e kadar desteklenir; macOS Big Sur 11.x+, aşağıdaki önyükleme argümanlarına ek olarak OCLP yamasını gerektirir (Metal desteği yoktur).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 vb.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 vb.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 vb.\n  Desteklenmeyen NVIDIA GPU\'lar (Turing, Ampere, Ada Lovelace, Blackwell - macOS desteği yok):\n    • 16xx ~ 50xx serisi: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 vb.',
      'vi': 'Tóm tắt hỗ trợ GPU NVIDIA:\n    • Dòng Tesla (dòng 8000 - 300): Được hỗ trợ nguyên bản lên tới macOS High Sierra 10.13.x (có thể yêu cầu sửa lỗi NVCAP); phiên bản cao hơn yêu cầu OCLP (không hỗ trợ Metal).\n       ví dụ: 8600GT, 9600GT, GT210, GT220, GT240, v.v. Phần cứng lỗi thời, không được khuyến nghị!\n    • Dòng Kepler (dòng 600 - 800): Được hỗ trợ nguyên bản lên tới macOS Big Sur 11.x; phiên bản cao hơn yêu cầu OCLP (hỗ trợ Metal, tăng tốc tối đa).\n       Người tiêu dùng Kepler: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black, v.v.\n       Máy trạm Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000, v.v.\n    • Dòng Fermi, Maxwell, Pascal: Trình điều khiển Web được hỗ trợ lên tới macOS High Sierra 10.13.x; macOS Big Sur 11.x+ yêu cầu boot-args bên dưới cộng với bản vá OCLP (không hỗ trợ Metal).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740, v.v.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980, v.v.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080, v.v.\n  GPU NVIDIA không được hỗ trợ (Turing, Ampere, Ada Lovelace, Blackwell - không hỗ trợ macOS):\n    • Dòng 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070, v.v.',
      'pl': 'Podsumowanie obsługi procesora graficznego NVIDIA:\n    • Seria Tesla (seria 8000–300): natywnie obsługiwana do wersji macOS High Sierra 10.13.x (może wymagać poprawki NVCAP); wyższe wersje wymagają OCLP (bez obsługi metalu).\n       np.: 8600GT, 9600GT, GT210, GT220, GT240 itp. Przestarzały sprzęt, nie polecam!\n    • Seria Kepler (seria 600–800): obsługiwana natywnie aż do wersji macOS Big Sur 11.x; wyższe wersje wymagają OCLP (obsługuje Metal, pełne przyspieszenie).\n       Konsument Keplera: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black itp.\n       Stacja robocza Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 itp.\n    • Seria Fermi, Maxwell, Pascal: sterownik sieciowy obsługiwany do systemu macOS High Sierra 10.13.x; macOS Big Sur 11.x+ wymaga poniższych argumentów rozruchowych oraz łatki OCLP (bez obsługi Metal).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 itp.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 itp.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 itp.\n  Nieobsługiwane procesory graficzne NVIDIA (Turing, Ampere, Ada Lovelace, Blackwell – brak obsługi systemu macOS):\n    • Seria 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 itp.',
      'uk': 'Огляд підтримки GPU NVIDIA:\n    • Серія Tesla (серії 8000–300): вбудована підтримка до macOS High Sierra 10.13.x (може знадобитися виправлення NVCAP); для вищих версій потрібен OCLP (без підтримки Metal).\n       наприклад: 8600GT, 9600GT, GT210, GT220, GT240 тощо. Застаріле обладнання, не рекомендується!\n    • Серія Kepler (серії 600–800): вбудована підтримка до macOS Big Sur 11.x; для вищих версій потрібен OCLP (підтримується Metal, повне прискорення).\n       Споживач Kepler: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black тощо.\n       Робоча станція Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 тощо.\n    • Серії Fermi, Maxwell, Pascal: веб-драйвер підтримується до macOS High Sierra 10.13.x; Для macOS Big Sur 11.x+ потрібні наведені нижче параметри завантаження та патч OCLP (без підтримки Metal).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 тощо.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 тощо.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 тощо.\n  Непідтримувані графічні процесори NVIDIA (Turing, Ampere, Ada Lovelace, Blackwell - без підтримки macOS):\n    • Серії 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 тощо.',
      'nl': 'NVIDIA GPU-ondersteuningssamenvatting:\n    • Tesla-serie (8000 - 300-serie): native ondersteund tot macOS High Sierra 10.13.x (mogelijk vereist NVCAP-fix); hogere versies vereisen OCLP (geen Metal-ondersteuning).\n       bijv.: 8600GT, 9600GT, GT210, GT220, GT240 etc. Verouderde hardware, niet aanbevolen!\n    • Kepler-serie (600 - 800-serie): native ondersteund tot macOS Big Sur 11.x; hogere versies vereisen OCLP (ondersteunt Metal, volledige acceleratie).\n       Kepler-consument: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black enz.\n       Kepler-werkstation: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 enz.\n    • Fermi, Maxwell, Pascal-serie: webdriver ondersteund tot macOS High Sierra 10.13.x; macOS Big Sur 11.x+ vereist onderstaande boot-args plus OCLP-patch (geen Metal-ondersteuning).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 enz.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 enz.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 enz.\n  Niet-ondersteunde NVIDIA GPU\'s (Turing, Ampere, Ada Lovelace, Blackwell - geen macOS-ondersteuning):\n    • 16xx ~ 50xx-serie: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 enz.',
      'hi': 'NVIDIA GPU समर्थन सारांश:\n    • टेस्ला सीरीज (8000 - 300 सीरीज): मूल रूप से मैकओएस हाई सिएरा 10.13.x तक समर्थित (एनवीसीएपी फिक्स की आवश्यकता हो सकती है); उच्चतर संस्करणों के लिए OCLP (कोई धातु समर्थन नहीं) की आवश्यकता होती है।\n       उदाहरण के लिए: 8600GT, 9600GT, GT210, GT220, GT240 आदि। अप्रचलित हार्डवेयर, अनुशंसित नहीं!\n    • केपलर सीरीज़ (600 - 800 सीरीज़): मूल रूप से macOS बिग सुर 11.x तक समर्थित; उच्चतर संस्करणों के लिए OCLP की आवश्यकता होती है (मेटल, पूर्ण त्वरण का समर्थन करता है)।\n       केप्लर उपभोक्ता: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX टाइटन Z, GTX टाइटन ब्लैक आदि।\n       केपलर वर्कस्टेशन: NVS 510, क्वाड्रो 410, क्वाड्रो K420, क्वाड्रो K600, क्वाड्रो K2000 आदि।\n    • फर्मी, मैक्सवेल, पास्कल सीरीज: वेब ड्राइवर macOS हाई सिएरा 10.13.x तक समर्थित; macOS बिग सुर 11.x+ के लिए नीचे बूट-आर्ग्स प्लस OCLP पैच (कोई मेटल सपोर्ट नहीं) की आवश्यकता होती है।\n       फर्मी: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 आदि।\n       मैक्सवेल: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 आदि।\n       पास्कल: GTX1050, GTX1060, GTX1070, GTX1080 आदि।\n  असमर्थित NVIDIA GPU (ट्यूरिंग, एम्पीयर, एडा लवलेस, ब्लैकवेल - कोई macOS समर्थन नहीं):\n    • 16xx ~ 50xx श्रृंखला: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070 आदि।',
      'ar': 'ملخص دعم NVIDIA GPU:\n    • سلسلة Tesla (السلسلة 8000 - 300): مدعومة أصلاً حتى نظام التشغيل macOS High Sierra 10.13.x (قد يتطلب إصلاح NVCAP)؛ تتطلب الإصدارات الأعلى OCLP (لا يوجد دعم معدني).\n       على سبيل المثال: 8600GT، 9600GT، GT210، GT220، GT240 وما إلى ذلك. الأجهزة القديمة، غير مستحسن!\n    • سلسلة Kepler (السلسلة 600 - 800): مدعومة أصلاً حتى نظام التشغيل macOS Big Sur 11.x؛ تتطلب الإصدارات الأعلى OCLP (يدعم المعدن والتسارع الكامل).\n       مستهلك كيبلر: GT630، GT635، GT640، GTX650، GTX660، GTX680، GT710، GT720، GT730، GT740، GTX760، GTX Titan Z، GTX Titan Black إلخ.\n       محطة عمل كيبلر: NVS 510، Quadro 410، Quadro K420، Quadro K600، Quadro K2000 إلخ.\n    • سلسلة Fermi وMaxwell وPascal: برنامج تشغيل الويب مدعوم حتى macOS High Sierra 10.13.x؛ يتطلب نظام التشغيل macOS Big Sur 11.x+ وسائط التمهيد الموضحة أدناه بالإضافة إلى تصحيح OCLP (لا يوجد دعم معدني).\n       فيرمي: GT605، GT610، GT620، GT630، GT705، GT710، GT720، GT730، GT740 إلخ.\n       ماكسويل: GTX750، GTX750Ti، GTX950، GTX960، GTX970، GTX980 إلخ.\n       باسكال: GTX1050، GTX1060، GTX1070، GTX1080 إلخ.\n  وحدات معالجة الرسومات NVIDIA غير المدعومة (Turing وAmpere وAda Lovelace وBlackwell - لا يوجد دعم لنظام التشغيل macOS):\n    • سلسلة 16xx ~ 50xx: GTX 1650، GTX 1660، RTX 2060، RTX 3060، RTX 4060، RTX 5070 وما إلى ذلك.',
      'id': 'Ringkasan Dukungan GPU NVIDIA:\n    • Tesla Series (seri 8000 - 300): Didukung secara native hingga macOS High Sierra 10.13.x (mungkin memerlukan perbaikan NVCAP); versi yang lebih tinggi memerlukan OCLP (tidak ada dukungan Metal).\n       misalnya: 8600GT, 9600GT, GT210, GT220, GT240 dll. Perangkat keras yang sudah usang, tidak disarankan!\n    • Seri Kepler (seri 600 - 800): Didukung secara asli hingga macOS Big Sur 11.x; versi yang lebih tinggi memerlukan OCLP (mendukung Metal, akselerasi penuh).\n       Konsumen Kepler: GT630, GT635, GT640, GTX650, GTX660, GTX680, GT710, GT720, GT730, GT740, GTX760, GTX Titan Z, GTX Titan Black dll.\n       Stasiun kerja Kepler: NVS 510, Quadro 410, Quadro K420, Quadro K600, Quadro K2000 dll.\n    • Seri Fermi, Maxwell, Pascal: Driver Web didukung hingga macOS High Sierra 10.13.x; macOS Big Sur 11.x+ memerlukan boot-args di bawah ini ditambah patch OCLP (tidak ada dukungan Metal).\n       Fermi: GT605, GT610, GT620, GT630, GT705, GT710, GT720, GT730, GT740 dll.\n       Maxwell: GTX750, GTX750Ti, GTX950, GTX960, GTX970, GTX980 dll.\n       Pascal: GTX1050, GTX1060, GTX1070, GTX1080 dll.\n  GPU NVIDIA yang tidak didukung (Turing, Ampere, Ada Lovelace, Blackwell - tidak ada dukungan macOS):\n    • Seri 16xx ~ 50xx: GTX 1650, GTX 1660, RTX 2060, RTX 3060, RTX 4060, RTX 5070, dll.',
    },
