    'Option 1: AirportItlwm driver. Native Apple Wi-Fi UI for Intel cards (large size). Do NOT use concurrently with Option 2 (itlwm) to avoid kernel panics!': {
      'pt': 'Opção 1: driver AirportItlwm. UI Wi-Fi nativa da Apple para placas Intel (tamanho grande). NÃO use simultaneamente com a Opção 2 (itlwm) para evitar pânico no kernel!',
      'zh': '选项 1：AirportItlwm 驱动程序。适用于 Intel 卡（大尺寸）的本机 Apple Wi-Fi UI。不要与选项 2 (itlwm) 同时使用以避免内核恐慌！',
      'zh_Hant': '選項 1：AirportItlwm 驅動程式。適用於 Intel 卡（大尺寸）的本機 Apple Wi-Fi UI。不要與選項 2 (itlwm) 同時使用以避免內核恐慌！',
      'es': 'Opción 1: Conductor AirportItlwm. Interfaz de usuario Wi-Fi nativa de Apple para tarjetas Intel (tamaño grande). ¡NO lo use simultáneamente con la Opción 2 (itlwm) para evitar pánicos en el kernel!',
      'de': 'Option 1: AirportItlwm-Treiber. Native Apple Wi-Fi-Benutzeroberfläche für Intel-Karten (groß). NICHT gleichzeitig mit Option 2 (itlwm) verwenden, um Kernel-Panik zu vermeiden!',
      'fr': 'Option 1 : pilote AirportItlwm. Interface utilisateur Wi-Fi Apple native pour les cartes Intel (grande taille). Ne PAS utiliser en même temps que l\'option 2 (itlwm) pour éviter les paniques du noyau !',
      'ru': 'Вариант 1: Водитель AirportItlwm. Собственный интерфейс Apple Wi-Fi для карт Intel (большой размер). НЕ используйте одновременно с Вариантом 2 (itlwm), чтобы избежать паники ядра!',
      'ja': 'オプション 1: AirportItlwm ドライバー。 Intel カード用のネイティブ Apple Wi-Fi UI (大きいサイズ)。カーネルパニックを避けるために、オプション 2 (itlwm) と同時に使用しないでください。',
      'ko': '옵션 1: AirportItlwm 드라이버. Intel 카드용 기본 Apple Wi-Fi UI(대형). 커널 패닉을 방지하려면 옵션 2(itlwm)와 동시에 사용하지 마십시오!',
      'it': 'Opzione 1: autista AirportItlwm. Interfaccia utente Wi-Fi nativa Apple per schede Intel (dimensioni grandi). NON utilizzare contemporaneamente all\'Opzione 2 (itlwm) per evitare il panico del kernel!',
      'tr': 'Seçenek 1: AirportItlwm sürücüsü. Intel kartları için yerel Apple Wi-Fi kullanıcı arayüzü (büyük boy). Çekirdek paniklerinden kaçınmak için Seçenek 2 (itlwm) ile aynı anda KULLANMAYIN!',
      'vi': 'Tùy chọn 1: Trình điều khiển AirportItlwm. Giao diện người dùng Wi-Fi gốc của Apple dành cho thẻ Intel (kích thước lớn). KHÔNG sử dụng đồng thời với Tùy chọn 2 (itlwm) để tránh tình trạng hoảng loạn kernel!',
      'pl': 'Opcja 1: Kierowca AirportItlwm. Natywny interfejs Apple Wi-Fi dla kart Intel (duży rozmiar). NIE używaj jednocześnie z Opcją 2 (itlwm), aby uniknąć paniki jądra!',
      'uk': 'Варіант 1: драйвер AirportItlwm. Власний Apple Wi-Fi UI для карт Intel (великий розмір). НЕ використовуйте одночасно з Варіантом 2 (itlwm), щоб уникнути паніки ядра!',
      'nl': 'Optie 1: AirportItlwm-chauffeur. Native Apple Wi-Fi UI voor Intel-kaarten (groot formaat). Gebruik NIET gelijktijdig met Optie 2 (itlwm) om kernelpanics te voorkomen!',
      'hi': 'विकल्प 1: एयरपोर्टआईटीएलडब्ल्यूएम ड्राइवर। इंटेल कार्ड के लिए नेटिव एप्पल वाई-फाई यूआई (बड़े आकार)। कर्नेल पैनिक से बचने के लिए विकल्प 2 (itlwm) के साथ एक साथ उपयोग न करें!',
      'ar': 'الخيار 1: سائق AirportItlwm. واجهة Apple Wi-Fi الأصلية لبطاقات Intel (حجم كبير). لا تستخدم بشكل متزامن مع الخيار 2 (itlwm) لتجنب ذعر النواة!',
      'id': 'Opsi 1: Pengemudi AirportItlwm. UI Wi-Fi Apple asli untuk kartu Intel (ukuran besar). JANGAN gunakan bersamaan dengan Opsi 2 (itlwm) untuk menghindari kepanikan kernel!',
    },
    'Option 2: itlwm driver (requires HeliPort app). Compatible Intel Wi-Fi driver. Do NOT use concurrently with Option 1!': {
      'pt': 'Opção 2: driver itlwm (requer aplicativo HeliPort). Driver Intel Wi-Fi compatível. NÃO use simultaneamente com a Opção 1!',
      'zh': '选项 2：itlwm 驱动程序（需要 HeliPort 应用程序）。兼容的英特尔 Wi-Fi 驱动程序。请勿与选项 1 同时使用！',
      'zh_Hant': '選項 2：itlwm 驅動程式（需要 HeliPort 應用程式）。相容的英特爾 Wi-Fi 驅動程式。請勿與選項 1 同時使用！',
      'es': 'Opción 2: controlador itlwm (requiere la aplicación HeliPort). Controlador Wi-Fi Intel compatible. ¡NO lo use simultáneamente con la Opción 1!',
      'de': 'Option 2: itlwm-Treiber (erfordert HeliPort-App). Kompatibler Intel Wi-Fi-Treiber. NICHT gleichzeitig mit Option 1 verwenden!',
      'fr': 'Option 2 : pilote itlwm (nécessite l\'application HeliPort). Pilote Wi-Fi Intel compatible. Ne PAS utiliser simultanément avec l’option 1 !',
      'ru': 'Вариант 2: драйвер itlwm (требуется приложение HeliPort). Совместимый драйвер Intel Wi-Fi. НЕ используйте одновременно с Вариантом 1!',
      'ja': 'オプション 2: itlwm ドライバー (HeliPort アプリが必要)。互換性のあるインテル Wi-Fi ドライバー。オプション 1 と同時に使用しないでください。',
      'ko': '옵션 2: itlwm 드라이버(HeliPort 앱 필요) 호환되는 Intel Wi-Fi 드라이버. 옵션 1과 동시에 사용하지 마십시오!',
      'it': 'Opzione 2: driver itlwm (richiede l\'app HeliPort). Driver Wi-Fi Intel compatibile. NON utilizzare contemporaneamente all\'Opzione 1!',
      'tr': 'Seçenek 2: itlwm sürücüsü (HeliPort uygulaması gerektirir). Uyumlu Intel Wi-Fi sürücüsü. Seçenek 1 ile aynı anda KULLANMAYIN!',
      'vi': 'Tùy chọn 2: trình điều khiển itlwm (yêu cầu ứng dụng HeliPort). Trình điều khiển Wi-Fi Intel tương thích. KHÔNG sử dụng đồng thời với Phương án 1!',
      'pl': 'Opcja 2: sterownik itlwm (wymaga aplikacji HeliPort). Zgodny sterownik Intel Wi-Fi. NIE stosować jednocześnie z Opcją 1!',
      'uk': 'Варіант 2: драйвер itlwm (потрібна програма HeliPort). Сумісний драйвер Intel Wi-Fi. НЕ використовуйте одночасно з Варіантом 1!',
      'nl': 'Optie 2: itlwm-stuurprogramma (vereist HeliPort-app). Compatibel Intel Wi-Fi-stuurprogramma. NIET gelijktijdig gebruiken met Optie 1!',
      'hi': 'विकल्प 2: itlwm ड्राइवर (हेलीपोर्ट ऐप की आवश्यकता है)। संगत इंटेल वाई-फाई ड्राइवर। विकल्प 1 के साथ एक साथ उपयोग न करें!',
      'ar': 'الخيار 2: برنامج تشغيل itlwm (يتطلب تطبيق HeliPort). برنامج تشغيل Intel Wi-Fi متوافق. لا تستخدم بالتزامن مع الخيار 1!',
      'id': 'Opsi 2: driver itlwm (memerlukan aplikasi HeliPort). Driver Wi-Fi Intel yang kompatibel. JANGAN gunakan bersamaan dengan Opsi 1!',
    },
