    'PS/2 Keyboard, combines VoodooI2C and VoodooRMI advantages for I2C touch devices and Synaptics RMI4 trackpads.': {
      'pt': 'Teclado PS/2, combina vantagens VoodooI2C e VoodooRMI para dispositivos de toque I2C e trackpads Synaptics RMI4.',
      'zh': 'PS/2 键盘，结合了 VoodooI2C 和 VoodooRMI 的优点，适用于 I2C 触摸设备和 Synaptics RMI4 触控板。',
      'zh_Hant': 'PS/2 鍵盤，結合了 VoodooI2C 和 VoodooRMI 的優點，適用於 I2C 觸控裝置和 Synaptics RMI4 觸控板。',
      'es': 'El teclado PS/2 combina las ventajas de VoodooI2C y VoodooRMI para dispositivos táctiles I2C y trackpads Synaptics RMI4.',
      'de': 'PS/2-Tastatur, kombiniert die Vorteile von VoodooI2C und VoodooRMI für I2C-Touch-Geräte und Synaptics RMI4-Trackpads.',
      'fr': 'Le clavier PS/2 combine les avantages VoodooI2C et VoodooRMI pour les appareils tactiles I2C et les trackpads Synaptics RMI4.',
      'ru': 'Клавиатура PS/2 сочетает в себе преимущества VoodooI2C и VoodooRMI для сенсорных устройств I2C и трекпадов Synaptics RMI4.',
      'ja': 'PS/2 キーボードは、I2C タッチ デバイスと Synaptics RMI4 トラックパッド向けの VoodooI2C と VoodooRMI の利点を組み合わせています。',
      'ko': 'PS/2 키보드는 I2C 터치 장치 및 Synaptics RMI4 트랙패드에 대한 VoodooI2C 및 VoodooRMI 장점을 결합합니다.',
      'it': 'Tastiera PS/2, combina i vantaggi VoodooI2C e VoodooRMI per i dispositivi touch I2C e i trackpad Synaptics RMI4.',
      'tr': 'PS/2 Klavye, I2C dokunmatik cihazlar ve Synaptics RMI4 trackpad\'ler için VoodooI2C ve VoodooRMI avantajlarını birleştirir.',
      'vi': 'Bàn phím PS/2, kết hợp các ưu điểm của VoodooI2C và VoodooRMI cho các thiết bị cảm ứng I2C và bàn di chuột Synaptics RMI4.',
      'pl': 'Klawiatura PS/2 łączy zalety VoodooI2C i VoodooRMI dla urządzeń dotykowych I2C i gładzików Synaptics RMI4.',
      'uk': 'Клавіатура PS/2 поєднує в собі переваги VoodooI2C і VoodooRMI для сенсорних пристроїв I2C і трекпадів Synaptics RMI4.',
      'nl': 'PS/2-toetsenbord, combineert VoodooI2C- en VoodooRMI-voordelen voor I2C-aanraakapparaten en Synaptics RMI4-trackpads.',
      'hi': 'PS/2 कीबोर्ड, I2C टच डिवाइस और सिनैप्टिक्स RMI4 ट्रैकपैड के लिए VoodooI2C और VoodooRMI लाभों को जोड़ता है।',
      'ar': 'تجمع لوحة المفاتيح PS/2 بين مزايا VoodooI2C وVoodooRMI لأجهزة اللمس I2C ولوحات التتبع Synaptics RMI4.',
      'id': 'Keyboard PS/2, menggabungkan keunggulan VoodooI2C dan VoodooRMI untuk perangkat sentuh I2C dan trackpad Synaptics RMI4.',
    },
    'PS/2 Keyboard, suitable for I2C bus trackpads, touchscreens, sensors, and input devices. Provides native-like multi-touch gestures.': {
      'pt': 'Teclado PS/2, adequado para trackpads de barramento I2C, telas sensíveis ao toque, sensores e dispositivos de entrada. Fornece gestos multitoque semelhantes aos nativos.',
      'zh': 'PS/2 键盘，适用于 I2C 总线触控板、触摸屏、传感器和输入设备。提供类似原生的多点触控手势。',
      'zh_Hant': 'PS/2 鍵盤，適用於 I2C 匯流排觸控板、觸控螢幕、感應器和輸入裝置。提供類似原生的多點觸控手勢。',
      'es': 'Teclado PS/2, adecuado para trackpads de bus I2C, pantallas táctiles, sensores y dispositivos de entrada. Proporciona gestos multitáctiles nativos.',
      'de': 'PS/2-Tastatur, geeignet für I2C-Bus-Trackpads, Touchscreens, Sensoren und Eingabegeräte. Bietet native Multi-Touch-Gesten.',
      'fr': 'Clavier PS/2, adapté aux trackpads de bus I2C, aux écrans tactiles, aux capteurs et aux périphériques d\'entrée. Fournit des gestes multi-touch de type natif.',
      'ru': 'Клавиатура PS/2, подходящая для трекпадов шины I2C, сенсорных экранов, датчиков и устройств ввода. Обеспечивает реалистичные мультитач-жесты.',
      'ja': 'I2C バス トラックパッド、タッチスクリーン、センサー、入力デバイスに適した PS/2 キーボード。ネイティブのようなマルチタッチ ジェスチャを提供します。',
      'ko': 'I2C 버스 트랙패드, 터치스크린, 센서 및 입력 장치에 적합한 PS/2 키보드. 네이티브와 유사한 멀티 터치 제스처를 제공합니다.',
      'it': 'Tastiera PS/2, adatta per trackpad bus I2C, touchscreen, sensori e dispositivi di input. Fornisce gesti multi-touch di tipo nativo.',
      'tr': 'PS/2 Klavye, I2C veri yolu trackpad\'leri, dokunmatik ekranlar, sensörler ve giriş cihazları için uygundur. Yerel benzeri çoklu dokunma hareketleri sağlar.',
      'vi': 'Bàn phím PS/2, phù hợp với trackpad bus I2C, màn hình cảm ứng, cảm biến và thiết bị đầu vào. Cung cấp cử chỉ đa chạm giống như người bản địa.',
      'pl': 'Klawiatura PS/2, odpowiednia dla gładzików magistrali I2C, ekranów dotykowych, czujników i urządzeń wejściowych. Zapewnia natywne gesty wielodotykowe.',
      'uk': 'Клавіатура PS/2, підходить для трекпадів шини I2C, сенсорних екранів, датчиків і пристроїв введення. Забезпечує жести мультидотику, схожі на нативні.',
      'nl': 'PS/2 toetsenbord, geschikt voor I2C bus trackpads, touchscreens, sensoren en invoerapparaten. Biedt native-achtige multi-touch-bewegingen.',
      'hi': 'PS/2 कीबोर्ड, I2C बस ट्रैकपैड, टचस्क्रीन, सेंसर और इनपुट डिवाइस के लिए उपयुक्त। देशी जैसे मल्टी-टच जेस्चर प्रदान करता है।',
      'ar': 'لوحة مفاتيح PS/2، مناسبة للوحات تتبع ناقل I2C وشاشات اللمس وأجهزة الاستشعار وأجهزة الإدخال. يوفر إيماءات اللمس المتعدد الأصلية.',
      'id': 'Keyboard PS/2, cocok untuk trackpad bus I2C, layar sentuh, sensor, dan perangkat input. Memberikan gerakan multi-sentuh seperti aslinya.',
    },
    'PS/2 Keyboard, suitable for Synaptics trackpads using RMI4 protocol. Delivers smooth multi-touch gestures for Synaptics devices.': {
      'pt': 'Teclado PS/2, adequado para trackpads Synaptics usando protocolo RMI4. Oferece gestos multitoque suaves para dispositivos Synaptics.',
      'zh': 'PS/2 键盘，适用于使用 RMI4 协议的 Synaptics 触控板。为 Synaptics 设备提供流畅的多点触控手势。',
      'zh_Hant': 'PS/2 鍵盤，適用於使用 RMI4 協定的 Synaptics 觸控板。為 Synaptics 裝置提供流暢的多點觸控手勢。',
      'es': 'Teclado PS/2, adecuado para trackpads Synaptics que utilizan el protocolo RMI4. Ofrece gestos multitáctiles fluidos para dispositivos Synaptics.',
      'de': 'PS/2-Tastatur, geeignet für Synaptics-Trackpads mit RMI4-Protokoll. Bietet reibungslose Multi-Touch-Gesten für Synaptics-Geräte.',
      'fr': 'Clavier PS/2, adapté aux trackpads Synaptics utilisant le protocole RMI4. Fournit des gestes multi-touch fluides pour les appareils Synaptics.',
      'ru': 'Клавиатура PS/2, подходит для трекпадов Synaptics, использующих протокол RMI4. Обеспечивает плавные мультитач-жесты для устройств Synaptics.',
      'ja': 'PS/2 キーボード。RMI4 プロトコルを使用する Synaptics トラックパッドに適しています。 Synaptics デバイスにスムーズなマルチタッチ ジェスチャを提供します。',
      'ko': 'RMI4 프로토콜을 사용하는 Synaptics 트랙패드에 적합한 PS/2 키보드. Synaptics 장치에 부드러운 멀티 터치 제스처를 제공합니다.',
      'it': 'Tastiera PS/2, adatta per trackpad Synaptics che utilizzano il protocollo RMI4. Offre gesti multi-touch fluidi per i dispositivi Synaptics.',
      'tr': 'PS/2 Klavye, RMI4 protokolünü kullanan Synaptics trackpad\'lere uygundur. Synaptics cihazları için sorunsuz çoklu dokunma hareketleri sunar.',
      'vi': 'Bàn phím PS/2, phù hợp với trackpad Synaptics sử dụng giao thức RMI4. Cung cấp cử chỉ cảm ứng đa điểm mượt mà cho các thiết bị Synaptics.',
      'pl': 'Klawiatura PS/2, odpowiednia dla gładzików Synaptics korzystających z protokołu RMI4. Zapewnia płynne gesty wielodotykowe dla urządzeń Synaptics.',
      'uk': 'Клавіатура PS/2, підходить для трекпадів Synaptics з використанням протоколу RMI4. Забезпечує плавні мультисенсорні жести для пристроїв Synaptics.',
      'nl': 'PS/2-toetsenbord, geschikt voor Synaptics-trackpads die gebruik maken van het RMI4-protocol. Levert vloeiende multi-touch-bewegingen voor Synaptics-apparaten.',
      'hi': 'PS/2 कीबोर्ड, RMI4 प्रोटोकॉल का उपयोग करने वाले सिनैप्टिक्स ट्रैकपैड के लिए उपयुक्त। सिनैप्टिक्स उपकरणों के लिए सहज मल्टी-टच जेस्चर प्रदान करता है।',
      'ar': 'لوحة مفاتيح PS/2، مناسبة للوحات التتبع Synaptics التي تستخدم بروتوكول RMI4. يوفر إيماءات سلسة متعددة اللمس لأجهزة Synaptics.',
      'id': 'Keyboard PS/2, cocok untuk trackpad Synaptics yang menggunakan protokol RMI4. Memberikan gerakan multi-sentuh yang halus untuk perangkat Synaptics.',
    },
