    'Prevent reboot after sleep to obtain kernel panic logs for sleep troubleshooting': {
      'pt': 'Impedir a reinicialização após suspensão para obter logs de pânico do kernel para solução de problemas de suspensão',
      'zh': '防止睡眠后重新启动以获取内核恐慌日志以进行睡眠故障排除',
      'zh_Hant': '防止睡眠後重新啟動以取得內核恐慌日誌以進行睡眠故障排除',
      'es': 'Evite el reinicio después de la suspensión para obtener registros de pánico del kernel para solucionar problemas de suspensión',
      'de': 'Verhindern Sie einen Neustart nach dem Ruhezustand, um Kernel-Panic-Protokolle zur Fehlerbehebung im Ruhezustand zu erhalten',
      'fr': 'Empêcher le redémarrage après la veille pour obtenir les journaux de panique du noyau pour le dépannage du sommeil',
      'ru': 'Запретите перезагрузку после сна, чтобы получить журналы паники ядра для устранения неполадок сна.',
      'ja': 'スリープ後の再起動を防止して、スリープのトラブルシューティング用のカーネル パニック ログを取得します',
      'ko': '절전 문제 해결을 위한 커널 패닉 로그를 얻기 위해 절전 후 재부팅을 방지합니다.',
      'it': 'Impedisci il riavvio dopo la sospensione per ottenere i registri di panico del kernel per la risoluzione dei problemi di sospensione',
      'tr': 'Uyku sorunlarını gidermeye yönelik çekirdek panik günlüklerini almak için uykudan sonra yeniden başlatmayı önleyin',
      'vi': 'Ngăn chặn khởi động lại sau khi ngủ để lấy nhật ký hoảng loạn kernel để khắc phục sự cố khi ngủ',
      'pl': 'Zapobiegaj ponownemu uruchomieniu po uśpieniu, aby uzyskać dzienniki paniki jądra w celu rozwiązywania problemów ze uśpieniem',
      'uk': 'Запобігайте перезавантаженню після сну, щоб отримати журнали паніки ядра для усунення несправностей сну',
      'nl': 'Voorkom opnieuw opstarten na de slaapstand om kernelpanieklogboeken te verkrijgen voor het oplossen van problemen met de slaapstand',
      'hi': 'नींद की समस्या के निवारण के लिए कर्नेल पैनिक लॉग प्राप्त करने के लिए नींद के बाद रिबूट को रोकें',
      'ar': 'منع إعادة التشغيل بعد النوم للحصول على سجلات ذعر kernel لاستكشاف أخطاء النوم وإصلاحها',
      'id': 'Cegah reboot setelah tidur untuk mendapatkan log panik kernel untuk pemecahan masalah tidur',
    },
    'Prevents automatic reboot on kernel panic to view crash logs (highly recommended for initial debugging)': {
      'pt': 'Impede a reinicialização automática no kernel panic para visualizar logs de falhas (altamente recomendado para depuração inicial)',
      'zh': '防止内核恐慌时自动重新启动以查看崩溃日志（强烈建议用于初始调试）',
      'zh_Hant': '防止內核恐慌時自動重新啟動以查看崩潰日誌（強烈建議用於初始調試）',
      'es': 'Evita el reinicio automático en caso de pánico del kernel para ver los registros de fallas (muy recomendado para la depuración inicial)',
      'de': 'Verhindert den automatischen Neustart bei Kernel-Panic, um Absturzprotokolle anzuzeigen (sehr empfehlenswert für das anfängliche Debuggen)',
      'fr': 'Empêche le redémarrage automatique en cas de panique du noyau pour afficher les journaux de crash (fortement recommandé pour le débogage initial)',
      'ru': 'Предотвращает автоматическую перезагрузку при панике ядра для просмотра журналов сбоев (настоятельно рекомендуется для начальной отладки)',
      'ja': 'カーネル パニック時にクラッシュ ログを表示するために自動再起動が行われないようにします (初期デバッグに強く推奨)',
      'ko': '충돌 로그를 보기 위해 커널 패닉 시 자동 재부팅을 방지합니다(초기 디버깅에 적극 권장됨).',
      'it': 'Impedisce il riavvio automatico in caso di panico del kernel per visualizzare i registri degli arresti anomali (altamente consigliato per il debug iniziale)',
      'tr': 'Kilitlenme günlüklerini görüntülemek için çekirdek paniğinde otomatik yeniden başlatmayı önler (ilk hata ayıklama için şiddetle tavsiye edilir)',
      'vi': 'Ngăn chặn việc tự động khởi động lại trên kernel để xem nhật ký sự cố (rất khuyến khích cho việc gỡ lỗi ban đầu)',
      'pl': 'Zapobiega automatycznemu ponownemu uruchomieniu w przypadku paniki jądra w celu wyświetlenia dzienników awarii (wysoce zalecane do wstępnego debugowania)',
      'uk': 'Запобігає автоматичному перезавантаженню під час паніки ядра для перегляду журналів збоїв (настійно рекомендовано для початкового налагодження)',
      'nl': 'Voorkomt automatisch opnieuw opstarten bij kernelpaniek om crashlogboeken te bekijken (sterk aanbevolen voor initiële foutopsporing)',
      'hi': 'क्रैश लॉग देखने के लिए कर्नेल पैनिक पर स्वचालित रीबूट को रोकता है (प्रारंभिक डिबगिंग के लिए अत्यधिक अनुशंसित)',
      'ar': 'يمنع إعادة التشغيل التلقائي في حالة ذعر kernel لعرض سجلات الأعطال (يوصى به بشدة للتصحيح الأولي)',
      'id': 'Mencegah reboot otomatis pada kepanikan kernel untuk melihat log kerusakan (sangat disarankan untuk debugging awal)',
    },
    'Prints more symbol information during kernel panic. Typically combined with debug=0x100 (highly recommended for initial debugging)': {
      'pt': 'Imprime mais informações sobre símbolos durante o kernel panic. Normalmente combinado com debug=0x100 (altamente recomendado para depuração inicial)',
      'zh': '在内核恐慌期间打印更多符号信息。通常与 debug=0x100 结合使用（强烈建议用于初始调试）',
      'zh_Hant': '在核心恐慌期間列印更多符號資訊。通常與 debug=0x100 結合使用（強烈建議用於初始偵錯）',
      'es': 'Imprime más información de símbolos durante el pánico del kernel. Normalmente se combina con debug=0x100 (muy recomendado para la depuración inicial)',
      'de': 'Gibt während einer Kernel-Panik weitere Symbolinformationen aus. Typischerweise kombiniert mit debug=0x100 (sehr empfehlenswert für das anfängliche Debuggen)',
      'fr': 'Imprime plus d\'informations sur les symboles lors d\'une panique du noyau. Généralement combiné avec debug=0x100 (fortement recommandé pour le débogage initial)',
      'ru': 'Печатает дополнительную информацию о символах во время паники ядра. Обычно в сочетании с debug=0x100 (настоятельно рекомендуется для начальной отладки)',
      'ja': 'カーネルパニック中に、より多くのシンボル情報を出力します。通常、debug=0x100 と組み合わせます (初期デバッグに強く推奨)',
      'ko': '커널 패닉 중에 더 많은 기호 정보를 인쇄합니다. 일반적으로 debug=0x100과 결합됩니다(초기 디버깅에 적극 권장됨).',
      'it': 'Stampa più informazioni sui simboli durante il kernel panico. Tipicamente combinato con debug=0x100 (altamente consigliato per il debug iniziale)',
      'tr': 'Çekirdek paniği sırasında daha fazla sembol bilgisi yazdırır. Tipik olarak hata ayıklama=0x100 ile birleştirilir (ilk hata ayıklama için şiddetle tavsiye edilir)',
      'vi': 'In thêm thông tin biểu tượng trong quá trình hoảng loạn kernel. Thường được kết hợp với debug=0x100 (rất khuyến khích cho lần gỡ lỗi ban đầu)',
      'pl': 'Drukuje więcej informacji o symbolach podczas paniki jądra. Zwykle w połączeniu z debug=0x100 (wysoce zalecane do wstępnego debugowania)',
      'uk': 'Друкує більше інформації про символи під час паніки ядра. Зазвичай поєднується з debug=0x100 (дуже рекомендовано для початкового налагодження)',
      'nl': 'Drukt meer symboolinformatie af tijdens kernelpaniek. Meestal gecombineerd met debug=0x100 (sterk aanbevolen voor initiële foutopsporing)',
      'hi': 'कर्नेल पैनिक के दौरान अधिक प्रतीक जानकारी प्रिंट करता है। आमतौर पर डिबग=0x100 के साथ संयुक्त (प्रारंभिक डिबगिंग के लिए अत्यधिक अनुशंसित)',
      'ar': 'طباعة المزيد من معلومات الرمز أثناء ذعر kernel. يتم دمجه عادةً مع debug=0x100 (يوصى به بشدة للتصحيح الأولي)',
      'id': 'Mencetak lebih banyak informasi simbol selama kepanikan kernel. Biasanya dikombinasikan dengan debug=0x100 (sangat disarankan untuk debugging awal)',
    },
