    'ProtectUefiServices(Protects UEFI services from being overwritten by firmware; typically fixes [EB|#LOG:EXITBS:START] issues caused by DevirtualiseMmio. Recommended for Z390, Z490, and 10th Gen Ice Lake)': {
      'pt': 'ProtectUefiServices (protege os serviços UEFI contra substituição por firmware; normalmente corrige problemas [EB|#LOG:EXITBS:START] causados ​​por DevirtualiseMmio. Recomendado para Z390, Z490 e Ice Lake de 10ª geração)',
      'zh': 'ProtectUefiServices（保护 UEFI 服务不被固件覆盖；通常修复由 DevirtualiseMmio 引起的 [EB|#LOG:EXITBS:START] 问题。推荐用于 Z390、Z490 和第 10 代 Ice Lake）',
      'zh_Hant': 'ProtectUefiServices（保護 UEFI 服務不被韌體覆蓋；通常修復由 DevirtualiseMmio 引起的 [EB|#LOG:EXITBS:START] 問題。建議用於 Z390、Z490 和第 10 代 Ice Lake）',
      'es': 'ProtectUefiServices (Protege los servicios UEFI contra la sobrescritura del firmware; normalmente soluciona [EB|#LOG:EXITBS:START] problemas causados ​​por DevirtualiseMmio. Recomendado para Z390, Z490 y Ice Lake de 10.ª generación)',
      'de': 'ProtectUefiServices (Schützt UEFI-Dienste vor dem Überschreiben durch Firmware; behebt typischerweise [EB|#LOG:EXITBS:START]-Probleme, die durch DevirtualiseMmio verursacht werden. Empfohlen für Z390, Z490 und Ice Lake der 10. Generation)',
      'fr': 'ProtectUefiServices (protège les services UEFI contre l\'écrasement par le micrologiciel ; corrige généralement les problèmes [EB|#LOG:EXITBS:START] causés par DevirtualiseMmio. Recommandé pour les Z390, Z490 et Ice Lake de 10e génération)',
      'ru': 'ProtectUefiServices (защищает службы UEFI от перезаписи прошивкой; обычно устраняет проблемы [EB|#LOG:EXITBS:START], вызванные DevirtualiseMmio. Рекомендуется для Z390, Z490 и Ice Lake 10-го поколения)',
      'ja': 'ProtectUefiServices (UEFI サービスをファームウェアによる上書きから保護します。通常、DevirtualiseMmio によって引き起こされる [EB|#LOG:EXITBS:START] 問題を修正します。Z390、Z490、および第 10 世代 Ice Lake に推奨)',
      'ko': 'ProtectUefiServices(펌웨어가 UEFI 서비스를 덮어쓰지 않도록 보호합니다. 일반적으로 DevirtualiseMmio로 인해 발생하는 [EB|#LOG:EXITBS:START] 문제를 해결합니다. Z390, Z490 및 10세대 Ice Lake에 권장됨)',
      'it': 'ProtectUefiServices (protegge i servizi UEFI dalla sovrascrittura del firmware; in genere risolve i problemi [EB|#LOG:EXITBS:START] causati da DevirtualiseMmio. Consigliato per Z390, Z490 e Ice Lake di decima generazione)',
      'tr': 'KorumaUefiServices(UEFI hizmetlerinin bellenim tarafından üzerine yazılmasını önler; genellikle DevirtualiseMmio\'nun neden olduğu [EB|#LOG:EXITBS:START] sorunlarını düzeltir. Z390, Z490 ve 10. Nesil Ice Lake için önerilir)',
      'vi': 'ProtectUefiServices(Bảo vệ các dịch vụ UEFI khỏi bị ghi đè bởi chương trình cơ sở; thường khắc phục các sự cố [EB|#LOG:EXITBS:START] do DevirtualiseMmio gây ra. Được khuyên dùng cho Z390, Z490 và Ice Lake thế hệ thứ 10)',
      'pl': 'ProtectUefiServices (chroni usługi UEFI przed nadpisaniem przez oprogramowanie sprzętowe; zazwyczaj naprawia problemy [EB|#LOG:EXITBS:START] spowodowane przez DevirtualiseMmio. Zalecane dla Z390, Z490 i Ice Lake 10. generacji)',
      'uk': 'ProtectUefiServices (Захищає служби UEFI від перезапису програмним забезпеченням; зазвичай усуває проблеми [EB|#LOG:EXITBS:START], спричинені DevirtualiseMmio. Рекомендовано для Z390, Z490 і Ice Lake 10-го покоління)',
      'nl': 'ProtectUefiServices(Beschermt UEFI-services tegen overschrijving door firmware; lost doorgaans [EB|#LOG:EXITBS:START]-problemen op die worden veroorzaakt door DevirtualiseMmio. Aanbevolen voor Z390, Z490 en 10e generatie Ice Lake)',
      'hi': 'प्रोटेक्टयूईएफआईसर्विसेज (यूईएफआई सेवाओं को फर्मवेयर द्वारा अधिलेखित होने से बचाता है; आम तौर पर देवीवर्चुअलाइजएममियो के कारण होने वाली [ईबी|#LOG:EXITBS:START] समस्याओं को ठीक करता है। Z390, Z490 और 10वीं पीढ़ी के आइस लेक के लिए अनुशंसित)',
      'ar': 'ProtectUefiServices(يحمي خدمات UEFI من الكتابة فوق البرامج الثابتة؛ عادةً ما يعمل على إصلاح مشكلات [EB|#LOG:EXITBS:START] التي تسببها DevirtualiseMmio. موصى به لـ Z390 وZ490 و10th Gen Ice Lake)',
      'id': 'ProtectUefiServices(Melindungi layanan UEFI agar tidak ditimpa oleh firmware; biasanya memperbaiki masalah [EB|#LOG:EXITBS:START] yang disebabkan oleh DevirtualiseMmio. Direkomendasikan untuk Z390, Z490, dan Ice Lake Generasi ke-10)',
    },
    'ProvideConsoleGop quirk is enabled by default to fix OpenCore boot UI visibility. If boot UI still fails to render, try unchecking this option.': {
      'pt': 'A peculiaridade do ProvideConsoleGop é habilitada por padrão para corrigir a visibilidade da IU de inicialização do OpenCore. Se a interface de inicialização ainda não for renderizada, tente desmarcar esta opção.',
      'zh': '默认情况下启用 ProvideConsoleGop 怪癖以修复 OpenCore 启动 UI 可见性。如果启动 UI 仍然无法呈现，请尝试取消选中此选项。',
      'zh_Hant': '預設啟用 ProvideConsoleGop 怪癖以修復 OpenCore 啟動 UI 可見性。如果啟動 UI 仍然無法呈現，請嘗試取消選取此選項。',
      'es': 'La peculiaridad de ProvideConsoleGop está habilitada de forma predeterminada para corregir la visibilidad de la interfaz de usuario de arranque de OpenCore. Si la interfaz de usuario de inicio aún no se procesa, intente desmarcar esta opción.',
      'de': 'Die ProvideConsoleGop-Eigenart ist standardmäßig aktiviert, um die Sichtbarkeit der OpenCore-Boot-Benutzeroberfläche zu verbessern. Wenn die Boot-Benutzeroberfläche immer noch nicht gerendert werden kann, deaktivieren Sie diese Option.',
      'fr': 'La bizarrerie ProvideConsoleGop est activée par défaut pour corriger la visibilité de l\'interface utilisateur de démarrage OpenCore. Si l’interface utilisateur de démarrage ne parvient toujours pas à s’afficher, essayez de décocher cette option.',
      'ru': 'Функция ProvideConsoleGop включена по умолчанию, чтобы исправить видимость пользовательского интерфейса загрузки OpenCore. Если пользовательский интерфейс загрузки по-прежнему не отображается, попробуйте снять флажок с этой опции.',
      'ja': 'OpenCore ブー​​ト UI の可視性を修正するために、ProvideConsoleGop quirk がデフォルトで有効になっています。それでもブート UI のレンダリングに失敗する場合は、このオプションのチェックを外してみてください。',
      'ko': 'OpenCore 부팅 UI 가시성을 수정하기 위해 ProvideConsoleGop quirk가 기본적으로 활성화되어 있습니다. 부팅 UI가 여전히 렌더링되지 않으면 이 옵션을 선택 취소해 보세요.',
      'it': 'La peculiarità ProvideConsoleGop è abilitata per impostazione predefinita per correggere la visibilità dell\'interfaccia utente di avvio OpenCore. Se il rendering dell\'interfaccia utente di avvio continua a non riuscire, prova a deselezionare questa opzione.',
      'tr': 'ProvideConsoleGop özelliği, OpenCore önyükleme kullanıcı arayüzü görünürlüğünü düzeltmek için varsayılan olarak etkindir. Önyükleme kullanıcı arayüzü hâlâ işlenemiyorsa bu seçeneğin işaretini kaldırmayı deneyin.',
      'vi': 'ProvideConsoleGop quirk được bật theo mặc định để khắc phục khả năng hiển thị UI khởi động OpenCore. Nếu giao diện người dùng khởi động vẫn không hiển thị, hãy thử bỏ chọn tùy chọn này.',
      'pl': 'Funkcja ProvideConsoleGop jest domyślnie włączona, aby naprawić widoczność interfejsu rozruchowego OpenCore. Jeśli interfejs rozruchowy nadal nie jest renderowany, spróbuj odznaczyć tę opcję.',
      'uk': 'Примушка ProvideConsoleGop увімкнена за замовчуванням, щоб виправити видимість завантажувального інтерфейсу OpenCore. Якщо завантажувальний інтерфейс все ще не відображається, спробуйте прибрати цей параметр.',
      'nl': 'ProvideConsoleGop-gril is standaard ingeschakeld om de zichtbaarheid van de OpenCore-opstart-UI te herstellen. Als de opstart-UI nog steeds niet wordt weergegeven, schakel dan deze optie uit.',
      'hi': 'OpenCore बूट UI दृश्यता को ठीक करने के लिए ProvideConsoleGop क्विर्क डिफ़ॉल्ट रूप से सक्षम है। यदि बूट यूआई अभी भी रेंडर करने में विफल रहता है, तो इस विकल्प को अनचेक करने का प्रयास करें।',
      'ar': 'يتم تمكين ميزة ProvideConsoleGop بشكل افتراضي لإصلاح رؤية واجهة مستخدم التمهيد لـ OpenCore. إذا استمر فشل عرض واجهة مستخدم التمهيد، فحاول إلغاء تحديد هذا الخيار.',
      'id': 'Kekhasan ProvideConsoleGop diaktifkan secara default untuk memperbaiki visibilitas UI boot OpenCore. Jika boot UI masih gagal dirender, coba hapus centang opsi ini.',
    },
    'Provided by Laura Müller. OS X 10.6 ~ 10.8 uses IntelSnowMausi': {
      'pt': 'Fornecido por Laura Müller. OS X 10.6 ~ 10.8 usa IntelSnowMausi',
      'zh': '由劳拉·穆勒提供。 OS X 10.6 ~ 10.8 使用 IntelSnowMausi',
      'zh_Hant': '由勞拉·穆勒提供。 OS X 10.6 ~ 10.8 使用 IntelSnowMausi',
      'es': 'Proporcionado por Laura Müller. OS X 10.6 ~ 10.8 usa IntelSnowMausi',
      'de': 'Zur Verfügung gestellt von Laura Müller. OS X 10.6 ~ 10.8 verwendet IntelSnowMausi',
      'fr': 'Fourni par Laura Müller. OS X 10.6 ~ 10.8 utilise IntelSnowMausi',
      'ru': 'Предоставлено Лаурой Мюллер. OS X 10.6 ~ 10.8 использует IntelSnowMausi',
      'ja': 'ローラ・ミュラー提供。 OS X 10.6 ～ 10.8 は IntelSnowMausi を使用します',
      'ko': '로라 뮐러 제공. OS X 10.6 ~ 10.8은 IntelSnowMausi를 사용합니다.',
      'it': 'Fornito da Laura Müller. OS X 10.6 ~ 10.8 utilizza IntelSnowMausi',
      'tr': 'Laura Müller tarafından sağlanmıştır. OS X 10.6 ~ 10.8 IntelSnowMausi\'yi kullanır',
      'vi': 'Được cung cấp bởi Laura Müller. OS X 10.6 ~ 10.8 sử dụng IntelSnowMausi',
      'pl': 'Dostarczone przez Laurę Müller. OS X 10.6 ~ 10.8 korzysta z IntelSnowMausi',
      'uk': 'Надано Лаурою Мюллер. OS X 10.6 ~ 10.8 використовує IntelSnowMausi',
      'nl': 'Geleverd door Laura Müller. OS X 10.6 ~ 10.8 maakt gebruik van IntelSnowMausi',
      'hi': 'लौरा मुलर द्वारा प्रदान किया गया। OS X 10.6 ~ 10.8 IntelSnowMausi का उपयोग करता है',
      'ar': 'مقدمة من لورا مولر. يستخدم OS X 10.6 ~ 10.8 IntelSnowMausi',
      'id': 'Disediakan oleh Laura Müller. OS X 10.6 ~ 10.8 menggunakan IntelSnowMausi',
    },
    'Provides GPU patching and display pipeline management. Highly recommended for most platforms (conflicts with NootRX/NootedRed; do not enable together during install)': {
      'pt': 'Fornece patch de GPU e gerenciamento de pipeline de exibição. Altamente recomendado para a maioria das plataformas (conflita com NootRX/NootedRed; não habilite juntos durante a instalação)',
      'zh': '提供 GPU 修补和显示管道管理。强烈建议大多数平台使用（与 NootRX/NootedRed 冲突；安装过程中不要一起启用）',
      'zh_Hant': '提供 GPU 修補和顯示管路管理。強烈建議大多數平台使用（與 NootRX/NootedRed 衝突；安裝過程中不要一起啟用）',
      'es': 'Proporciona parches de GPU y gestión de canales de visualización. Altamente recomendado para la mayoría de las plataformas (entra en conflicto con NootRX/NootedRed; no los habilite juntos durante la instalación)',
      'de': 'Bietet GPU-Patching und Display-Pipeline-Management. Für die meisten Plattformen dringend empfohlen (Konflikte mit NootRX/NootedRed; während der Installation nicht gleichzeitig aktivieren)',
      'fr': 'Fournit des correctifs GPU et une gestion du pipeline d’affichage. Fortement recommandé pour la plupart des plates-formes (conflits avec NootRX/NootedRed ; ne pas activer ensemble lors de l\'installation)',
      'ru': 'Обеспечивает исправление графического процессора и управление конвейером отображения. Настоятельно рекомендуется для большинства платформ (конфликты с NootRX/NootedRed; не включать вместе во время установки)',
      'ja': 'GPU パッチ適用とディスプレイ パイプライン管理を提供します。ほとんどのプラットフォームで強く推奨されます (NootRX/NootedRed と競合します。インストール中に一緒に有効にしないでください)',
      'ko': 'GPU 패치 및 디스플레이 파이프라인 관리를 제공합니다. 대부분의 플랫폼에 적극 권장됩니다(NootRX/NootedRed와 충돌하므로 설치 중에 함께 활성화하지 마십시오)',
      'it': 'Fornisce patch GPU e gestione della pipeline di visualizzazione. Altamente raccomandato per la maggior parte delle piattaforme (è in conflitto con NootRX/NootedRed; non abilitare insieme durante l\'installazione)',
      'tr': 'GPU düzeltme eki uygulama ve görüntü işlem hattı yönetimi sağlar. Çoğu platform için şiddetle tavsiye edilir (NootRX/NootedRed ile çakışır; kurulum sırasında birlikte etkinleştirmeyin)',
      'vi': 'Cung cấp bản vá GPU và quản lý đường dẫn hiển thị. Rất khuyến khích cho hầu hết các nền tảng (xung đột với NootRX/NootedRed; không kích hoạt cùng nhau trong khi cài đặt)',
      'pl': 'Zapewnia łatanie procesora graficznego i zarządzanie potokiem wyświetlania. Wysoce zalecane dla większości platform (konflikty z NootRX/NootedRed; nie włączaj razem podczas instalacji)',
      'uk': 'Забезпечує виправлення GPU та керування конвеєром відображення. Настійно рекомендовано для більшості платформ (конфліктує з NootRX/NootedRed; не вмикайте разом під час встановлення)',
      'nl': 'Biedt GPU-patching en weergavepijplijnbeheer. Sterk aanbevolen voor de meeste platforms (conflicten met NootRX/NootedRed; niet samen inschakelen tijdens installatie)',
      'hi': 'GPU पैचिंग और डिस्प्ले पाइपलाइन प्रबंधन प्रदान करता है। अधिकांश प्लेटफ़ॉर्म के लिए अत्यधिक अनुशंसित (NootRX/NootedRed के साथ विरोध; इंस्टॉल के दौरान एक साथ सक्षम न करें)',
      'ar': 'يوفر تصحيح GPU وإدارة خطوط العرض. يوصى به بشدة لمعظم الأنظمة الأساسية (يتعارض مع NootRX/NootedRed؛ لا يتم تمكينهما معًا أثناء التثبيت)',
      'id': 'Menyediakan patching GPU dan manajemen saluran tampilan. Sangat direkomendasikan untuk sebagian besar platform (bertentangan dengan NootRX/NootedRed; jangan aktifkan bersamaan saat instalasi)',
    },
    'Provides HDMI and DisplayPort connectivity and digital audio fixes': {
      'pt': 'Fornece conectividade HDMI e DisplayPort e correções de áudio digital',
      'zh': '提供 HDMI 和 DisplayPort 连接以及数字音频修复',
      'zh_Hant': '提供 HDMI 和 DisplayPort 連接以及數位音訊修復',
      'es': 'Proporciona conectividad HDMI y DisplayPort y correcciones de audio digital',
      'de': 'Bietet HDMI- und DisplayPort-Konnektivität sowie digitale Audiokorrekturen',
      'fr': 'Fournit une connectivité HDMI et DisplayPort et des correctifs audio numériques',
      'ru': 'Обеспечивает подключение HDMI и DisplayPort, а также исправления цифрового звука.',
      'ja': 'HDMI および DisplayPort 接続とデジタル オーディオ修正を提供します',
      'ko': 'HDMI 및 DisplayPort 연결과 디지털 오디오 수정 사항 제공',
      'it': 'Fornisce connettività HDMI e DisplayPort e correzioni audio digitale',
      'tr': 'HDMI ve DisplayPort bağlantısı ve dijital ses düzeltmeleri sağlar',
      'vi': 'Cung cấp kết nối HDMI và DisplayPort và sửa lỗi âm thanh kỹ thuật số',
      'pl': 'Zapewnia łączność HDMI i DisplayPort oraz poprawki dźwięku cyfrowego',
      'uk': 'Забезпечує підключення HDMI і DisplayPort і виправлення цифрового аудіо',
      'nl': 'Biedt HDMI- en DisplayPort-connectiviteit en oplossingen voor digitale audio',
      'hi': 'एचडीएमआई और डिस्प्लेपोर्ट कनेक्टिविटी और डिजिटल ऑडियो फिक्स प्रदान करता है',
      'ar': 'يوفر اتصال HDMI وDisplayPort وإصلاحات الصوت الرقمية',
      'id': 'Menyediakan konektivitas HDMI dan DisplayPort serta perbaikan audio digital',
