    'RapidEFI is an open-source, automated OpenCore EFI generator, ACPI/SSDT patcher, and hardware analysis tool built for Hackintosh and macOS enthusiasts.\n\nCreated and maintained with love. Star and fork the project on GitHub to support ongoing development!': {
      'pt': 'RapidEFI é um gerador OpenCore EFI automatizado e de código aberto, patcher ACPI/SSDT e ferramenta de análise de hardware desenvolvido para entusiastas de Hackintosh e macOS.\n\nCriado e mantido com amor. Dê uma estrela e bifurque o projeto no GitHub para apoiar o desenvolvimento contínuo!',
      'zh': 'RapidEFI 是一款开源、自动化的 OpenCore EFI 生成器、ACPI/SSDT 修补程序以及专为 Hackintosh 和 macOS 爱好者构建的硬件分析工具。\n\n用爱创造和维护。在 GitHub 上加星标并分叉该项目以支持持续的开发！',
      'zh_Hant': 'RapidEFI 是一款開源、自動化的 OpenCore EFI 生成器、ACPI/SSDT 修補程式以及專為 Hackintosh 和 macOS 愛好者構建的硬體分析工具。\n\n用愛創造和維護。在 GitHub 上加星標並分叉該專案以支持持續的開發！',
      'es': 'RapidEFI es un generador OpenCore EFI automatizado de código abierto, un parche ACPI/SSDT y una herramienta de análisis de hardware creado para entusiastas de Hackintosh y macOS.\n\nCreado y mantenido con amor. ¡Empiece y bifurque el proyecto en GitHub para respaldar el desarrollo continuo!',
      'de': 'RapidEFI ist ein Open-Source-, automatisierter OpenCore-EFI-Generator, ACPI/SSDT-Patcher und Hardware-Analysetool, das für Hackintosh- und macOS-Enthusiasten entwickelt wurde.\n\nMit Liebe erstellt und gepflegt. Markieren und forken Sie das Projekt auf GitHub, um die weitere Entwicklung zu unterstützen!',
      'fr': 'RapidEFI est un générateur OpenCore EFI automatisé, un correcteur ACPI/SSDT et un outil d\'analyse matérielle open source conçu pour les passionnés de Hackintosh et de macOS.\n\nCréé et entretenu avec amour. Star et forkez le projet sur GitHub pour soutenir le développement en cours !',
      'ru': 'RapidEFI — это автоматизированный генератор EFI OpenCore с открытым исходным кодом, средство исправления ACPI/SSDT и инструмент анализа оборудования, созданный для энтузиастов Hackintosh и macOS.\n\nСоздано и поддерживается с любовью. Поставьте звездочку и создайте форк проекта на GitHub, чтобы поддержать текущую разработку!',
      'ja': 'RapidEFI は、Hackintosh および macOS 愛好家向けに構築された、オープンソースの自動 OpenCore EFI ジェネレーター、ACPI/SSDT パッチャー、およびハードウェア分析ツールです。\n\n愛情を持って作成され、維持されています。進行中の開発をサポートするために、GitHub でプロジェクトにスターを付けてフォークしてください。',
      'ko': 'RapidEFI는 Hackintosh 및 macOS 매니아를 위해 제작된 오픈 소스, 자동화된 OpenCore EFI 생성기, ACPI/SSDT 패처 및 하드웨어 분석 도구입니다.\n\n사랑으로 만들고 유지합니다. 지속적인 개발을 지원하기 위해 GitHub에서 프로젝트를 스타팅하고 포크하세요!',
      'it': 'RapidEFI è un generatore EFI OpenCore automatizzato open source, un patcher ACPI/SSDT e uno strumento di analisi hardware creato per gli appassionati di Hackintosh e macOS.\n\nCreato e mantenuto con amore. Specializza e dividi il progetto su GitHub per supportare lo sviluppo continuo!',
      'tr': 'RapidEFI, Hackintosh ve macOS meraklıları için geliştirilmiş açık kaynaklı, otomatik bir OpenCore EFI oluşturucu, ACPI/SSDT yamalı ve donanım analiz aracıdır.\n\nSevgiyle yaratıldı ve sürdürüldü. Devam eden gelişimi desteklemek için projeyi GitHub\'da yıldızlandırın ve çatallayın!',
      'vi': 'RapidEFI là một trình tạo OpenCore EFI tự động, mã nguồn mở, trình vá ACPI/SSDT và công cụ phân tích phần cứng được xây dựng cho những người đam mê Hackintosh và macOS.\n\nĐược tạo ra và duy trì bằng tình yêu. Gắn dấu sao và phân nhánh dự án trên GitHub để hỗ trợ quá trình phát triển liên tục!',
      'pl': 'RapidEFI to zautomatyzowany generator OpenCore EFI o otwartym kodzie źródłowym, patcher ACPI/SSDT i narzędzie do analizy sprzętu stworzone dla entuzjastów Hackintosha i macOS.\n\nStworzone i utrzymywane z miłością. Oznacz i rozwidl projekt na GitHubie, aby wspierać ciągły rozwój!',
      'uk': 'RapidEFI — це автоматизований генератор OpenCore EFI з відкритим кодом, патчер ACPI/SSDT і інструмент аналізу апаратного забезпечення, створений для ентузіастів Hackintosh і macOS.\n\nСтворено та доглянуто з любов\'ю. Зірка та форк проекту на GitHub для підтримки поточної розробки!',
      'nl': 'RapidEFI is een open-source, geautomatiseerde OpenCore EFI-generator, ACPI/SSDT-patcher en hardware-analysetool gebouwd voor Hackintosh- en macOS-enthousiastelingen.\n\nMet liefde gemaakt en onderhouden. Geef het project een ster en vork op GitHub om de voortdurende ontwikkeling te ondersteunen!',
      'hi': 'रैपिडईएफआई एक ओपन-सोर्स, स्वचालित ओपनकोर ईएफआई जनरेटर, एसीपीआई/एसएसडीटी पैचर और हार्डवेयर विश्लेषण टूल है जो हैकिंटोश और मैकओएस उत्साही लोगों के लिए बनाया गया है।\n\nप्यार से बनाया और बनाए रखा। चल रहे विकास का समर्थन करने के लिए GitHub पर प्रोजेक्ट को स्टार और फोर्क करें!',
      'ar': 'RapidEFI عبارة عن مولد OpenCore EFI آلي مفتوح المصدر، وأداة تصحيح ACPI/SSDT، وأداة تحليل الأجهزة المصممة لعشاق Hackintosh وmacOS.\n\nتم إنشاؤها والحفاظ عليها بالحب. قم بتمييز المشروع وشوكته على GitHub لدعم التطوير المستمر!',
      'id': 'RapidEFI adalah generator EFI OpenCore otomatis sumber terbuka, patcher ACPI/SSDT, dan alat analisis perangkat keras yang dibuat untuk penggemar Hackintosh dan macOS.\n\nDibuat dan dipelihara dengan cinta. Bintangi dan fork proyek ini di GitHub untuk mendukung pengembangan berkelanjutan!',
    },
