    'RebuildAppleMemoryMap(Recommended on firmware with MAT support. Usually paired with SyncRuntimePermissions. Mutually exclusive with EnableWriteUnprotector. Typically for 8th Gen and newer platforms)': {
      'pt': 'RebuildAppleMemoryMap (recomendado em firmware com suporte MAT. Geralmente emparelhado com SyncRuntimePermissions. Mutuamente exclusivo com EnableWriteUnprotector. Normalmente para plataformas de 8ª geração e mais recentes)',
      'zh': 'RebuildAppleMemoryMap（推荐在支持 MAT 的固件上使用。通常与 SyncRuntimePermissions 配对。与 EnableWriteUnprotector 互斥。通常适用于第 8 代及更新的平台）',
      'zh_Hant': 'RebuildAppleMemoryMap（建議在支援 MAT 的韌體上使用。通常與 SyncRuntimePermissions 配對。與 EnableWriteUnprotector 互斥。通常適用於第 8 代及更新的平台）',
      'es': 'RebuildAppleMemoryMap (recomendado en firmware con soporte MAT. Generalmente se combina con SyncRuntimePermissions. Se excluye mutuamente con EnableWriteUnprotector. Normalmente para plataformas de 8.ª generación y más nuevas)',
      'de': 'RebuildAppleMemoryMap (Empfohlen für Firmware mit MAT-Unterstützung. Normalerweise gepaart mit SyncRuntimePermissions. Sich gegenseitig ausschließend mit EnableWriteUnprotector. Typischerweise für Plattformen der 8. Generation und neuer)',
      'fr': 'RebuildAppleMemoryMap (recommandé sur les micrologiciels prenant en charge MAT. Généralement associé à SyncRuntimePermissions. Mutuellement exclusif avec EnableWriteUnprotector. Généralement pour les plates-formes de 8e génération et plus récentes)',
      'ru': 'RebuildAppleMemoryMap (рекомендуется для прошивок с поддержкой MAT. Обычно в сочетании с SyncRuntimePermissions. Взаимоисключающе с EnableWriteUnprotector. Обычно для платформ 8-го поколения и более новых)',
      'ja': 'RebuildAppleMemoryMap (MAT サポートを備えたファームウェアで推奨。通常は SyncRuntimePermissions と組み合わせます。EnableWriteUnprotector とは相互に排他的です。通常は第 8 世代以降のプラットフォームの場合)',
      'ko': 'RebuildAppleMemoryMap(MAT를 지원하는 펌웨어에 권장됩니다. 일반적으로 SyncRuntimePermissions와 쌍을 이룹니다. EnableWriteUnprotector와 상호 배타적입니다. 일반적으로 8세대 및 최신 플랫폼에 해당)',
      'it': 'RebuildAppleMemoryMap (consigliato su firmware con supporto MAT. Solitamente abbinato a SyncRuntimePermissions. Si esclude a vicenda con EnableWriteUnprotector. In genere per piattaforme di ottava generazione e successive)',
      'tr': 'RebuildAppleMemoryMap(MAT destekli donanım yazılımında önerilir. Genellikle SyncRuntimePermissions ile eşleştirilir. EnableWriteUnprotector ile karşılıklı olarak özeldir. Tipik olarak 8. Nesil ve daha yeni platformlar için)',
      'vi': 'RebuildAppleMemoryMap(Được khuyến nghị trên chương trình cơ sở có hỗ trợ MAT. Thường được ghép nối với SyncRuntimePermissions. Loại trừ lẫn nhau với EnableWriteUnprotector. Thường dành cho các nền tảng thế hệ thứ 8 và mới hơn)',
      'pl': 'RebuildAppleMemoryMap (zalecane w przypadku oprogramowania układowego z obsługą MAT. Zwykle w połączeniu z SyncRuntimePermissions. Wzajemnie wykluczające się z EnableWriteUnprotector. Zwykle dla platform 8. generacji i nowszych)',
      'uk': 'RebuildAppleMemoryMap (рекомендується для вбудованого програмного забезпечення з підтримкою MAT. Зазвичай поєднується з SyncRuntimePermissions. Взаємовиключне з EnableWriteUnprotector. Зазвичай для платформ 8-го покоління та новіших)',
      'nl': 'RebuildAppleMemoryMap (aanbevolen op firmware met MAT-ondersteuning. Meestal gecombineerd met SyncRuntimePermissions. Wederzijds exclusief met EnableWriteUnprotector. Meestal voor 8e generatie en nieuwere platforms)',
      'hi': 'RebuildAppleMemoryMap (MAT समर्थन के साथ फर्मवेयर पर अनुशंसित। आमतौर पर SyncRuntimePermissions के साथ जोड़ा जाता है। EnableWriteUnprotector के साथ पारस्परिक रूप से अनन्य। आमतौर पर 8 वीं पीढ़ी और नए प्लेटफार्मों के लिए)',
      'ar': 'RebuildAppleMemoryMap (يوصى به على البرامج الثابتة التي تدعم MAT. عادةً ما يتم إقرانه مع SyncRuntimePermissions. حصريًا بشكل متبادل مع EnableWriteUnprotector. عادةً للجيل الثامن والأنظمة الأساسية الأحدث)',
      'id': 'RebuildAppleMemoryMap (Direkomendasikan pada firmware dengan dukungan MAT. Biasanya dipasangkan dengan SyncRuntimePermissions. Saling eksklusif dengan EnableWriteUnprotector. Biasanya untuk platform Generasi ke-8 dan yang lebih baru)',
    },
