    'SetupVirtualMap(Builds continuous virtual memory for OpenCore mapped to physical memory. Note: Not recommended for 10th Gen Comet Lake ASUS, Gigabyte, and ASRock motherboards)': {
      'pt': 'SetupVirtualMap (Constrói memória virtual contínua para OpenCore mapeada para memória física. Nota: Não recomendado para placas-mãe ASUS, Gigabyte e ASRock de 10ª geração Comet Lake)',
      'zh': 'SetupVirtualMap（为映射到物理内存的 OpenCore 构建连续虚拟内存。注意：不建议用于第 10 代 Comet Lake 华硕、技嘉和华擎主板）',
      'zh_Hant': 'SetupVirtualMap（為映射到實體記憶體的 OpenCore 建立連續虛擬記憶體。注意：不建議用於第 10 代 Comet Lake 華碩、技嘉和華擎主機板）',
      'es': 'SetupVirtualMap (crea memoria virtual continua para OpenCore asignada a la memoria física. Nota: no se recomienda para placas base Comet Lake ASUS, Gigabyte y ASRock de décima generación)',
      'de': 'SetupVirtualMap (Erstellt kontinuierlichen virtuellen Speicher für OpenCore, der dem physischen Speicher zugeordnet ist. Hinweis: Nicht empfohlen für Comet Lake ASUS-, Gigabyte- und ASRock-Motherboards der 10. Generation.)',
      'fr': 'SetupVirtualMap (crée une mémoire virtuelle continue pour OpenCore mappée à la mémoire physique. Remarque : non recommandé pour les cartes mères Comet Lake ASUS, Gigabyte et ASRock de 10e génération)',
      'ru': 'SetupVirtualMap (создает непрерывную виртуальную память для OpenCore, сопоставленную с физической памятью. Примечание. Не рекомендуется для материнских плат Comet Lake 10-го поколения ASUS, Gigabyte и ASRock).',
      'ja': 'SetupVirtualMap (物理メモリにマップされた OpenCore 用の連続仮想メモリを構築します。注: 第 10 世代 Comet Lake ASUS、Gigabyte、および ASRock マザーボードには推奨されません)',
      'ko': 'SetupVirtualMap(물리적 메모리에 매핑된 OpenCore용 연속 가상 메모리를 구축합니다. 참고: 10세대 Comet Lake ASUS, Gigabyte 및 ASRock 마더보드에는 권장되지 않음)',
      'it': 'SetupVirtualMap (crea memoria virtuale continua per OpenCore mappata sulla memoria fisica. Nota: non consigliato per le schede madri Comet Lake ASUS, Gigabyte e ASRock di decima generazione)',
      'tr': 'SetupVirtualMap(Fiziksel belleğe eşlenen OpenCore için sürekli sanal bellek oluşturur. Not: 10. Nesil Comet Lake ASUS, Gigabyte ve ASRock anakartları için önerilmez)',
      'vi': 'SetupVirtualMap(Xây dựng bộ nhớ ảo liên tục cho OpenCore được ánh xạ tới bộ nhớ vật lý. Lưu ý: Không nên dùng cho bo mạch chủ ASUS Comet Lake thế hệ thứ 10, Gigabyte và ASRock)',
      'pl': 'SetupVirtualMap (Buduje ciągłą pamięć wirtualną dla OpenCore mapowaną na pamięć fizyczną. Uwaga: niezalecane dla płyt głównych 10. generacji Comet Lake ASUS, Gigabyte i ASRock)',
      'uk': 'SetupVirtualMap (Створює постійну віртуальну пам’ять для OpenCore, зіставлену з фізичною пам’яттю. Примітка: не рекомендовано для материнських плат ASUS, Gigabyte і ASRock 10-го покоління Comet Lake)',
      'nl': 'SetupVirtualMap (bouwt continu virtueel geheugen voor OpenCore toegewezen aan fysiek geheugen. Opmerking: niet aanbevolen voor 10e generatie Comet Lake ASUS-, Gigabyte- en ASRock-moederborden)',
      'hi': 'SetupVirtualMap (भौतिक मेमोरी में मैप किए गए OpenCore के लिए निरंतर वर्चुअल मेमोरी बनाता है। नोट: 10वीं पीढ़ी के कॉमेट लेक ASUS, गीगाबाइट और ASRock मदरबोर्ड के लिए अनुशंसित नहीं)',
      'ar': 'SetupVirtualMap (يعمل على إنشاء ذاكرة افتراضية مستمرة لـ OpenCore المعينة للذاكرة الفعلية. ملاحظة: لا يُنصح باستخدامه مع اللوحات الأم ASUS وGigabyte وASRock من الجيل العاشر)',
      'id': 'SetupVirtualMap (Membangun memori virtual berkelanjutan untuk OpenCore yang dipetakan ke memori fisik. Catatan: Tidak disarankan untuk motherboard ASUS, Gigabyte, dan ASRock Comet Lake Generasi ke-10)',
    },
    'Skips board-id/SMBIOS model checks during boot to avoid prohibitive sign': {
      'pt': 'Ignora as verificações do modelo board-id/SMBIOS durante a inicialização para evitar sinais proibitivos',
      'zh': '在引导期间跳过板 ID/SMBIOS 模型检查以避免禁止标志',
      'zh_Hant': '在引導期間跳過板 ID/SMBIOS 模型檢查以避免禁止標誌',
      'es': 'Omite las comprobaciones del modelo Board-ID/SMBIOS durante el arranque para evitar señales prohibitivas.',
      'de': 'Überspringt Board-ID-/SMBIOS-Modellprüfungen während des Startvorgangs, um Verbotszeichen zu vermeiden',
      'fr': 'Ignore les vérifications de l\'ID de la carte/du modèle SMBIOS pendant le démarrage pour éviter le signe prohibitif',
      'ru': 'Пропускает проверку идентификатора платы/модели SMBIOS во время загрузки, чтобы избежать запрещающих знаков.',
      'ja': '禁止標識を回避するために、ブート中にボード ID/SMBIOS モデルのチェックをスキップします。',
      'ko': '금지 기호를 피하기 위해 부팅 중에 보드 ID/SMBIOS 모델 검사를 건너뜁니다.',
      'it': 'Salta i controlli del modello board-id/SMBIOS durante l\'avvio per evitare segnali proibitivi',
      'tr': 'Engelleyici işaretlerden kaçınmak için önyükleme sırasında board-id/SMBIOS model kontrollerini atlar',
