    'Suitable for 3rd Gen and newer platforms, PS/2 input devices such as keyboards, mice, trackpads. Provides multi-touch gestures via plugins.': {
      'pt': 'Adequado para plataformas de 3ª geração e mais recentes, dispositivos de entrada PS/2, como teclados, mouses e trackpads. Fornece gestos multitoque por meio de plug-ins.',
      'zh': '适用于第三代及更新的平台、PS/2 输入设备，例如键盘、鼠标、触控板。通过插件提供多点触控手势。',
      'zh_Hant': '適用於第三代及更新的平台、PS/2 輸入設備，例如鍵盤、滑鼠、觸控板。透過插件提供多點觸控手勢。',
      'es': 'Adecuado para plataformas de 3.ª generación y más nuevas, dispositivos de entrada PS/2 como teclados, ratones y trackpads. Proporciona gestos multitáctiles a través de complementos.',
      'de': 'Geeignet für Plattformen der 3. Generation und neuere PS/2-Eingabegeräte wie Tastaturen, Mäuse und Trackpads. Bietet Multi-Touch-Gesten über Plugins.',
      'fr': 'Convient aux plates-formes de 3e génération et plus récentes, aux périphériques d\'entrée PS/2 tels que les claviers, les souris et les trackpads. Fournit des gestes multi-touch via des plugins.',
      'ru': 'Подходит для платформ 3-го поколения и более новых, устройств ввода PS/2, таких как клавиатуры, мыши, трекпады. Обеспечивает мультитач-жесты через плагины.',
      'ja': '第 3 世代以降のプラットフォーム、キーボード、マウス、トラックパッドなどの PS/2 入力デバイスに適しています。プラグイン経由でマルチタッチ ジェスチャを提供します。',
      'ko': '3세대 이상의 플랫폼, 키보드, 마우스, 트랙패드와 같은 PS/2 입력 장치에 적합합니다. 플러그인을 통해 멀티 터치 제스처를 제공합니다.',
      'it': 'Adatto per piattaforme di terza generazione e più recenti, dispositivi di input PS/2 come tastiere, mouse, trackpad. Fornisce gesti multi-touch tramite plugin.',
      'tr': '3. Nesil ve daha yeni platformlar, klavye, fare, trackpad gibi PS/2 giriş cihazları için uygundur. Eklentiler aracılığıyla çoklu dokunma hareketleri sağlar.',
      'vi': 'Thích hợp cho các nền tảng thế hệ thứ 3 và mới hơn, các thiết bị đầu vào PS/2 như bàn phím, chuột, trackpad. Cung cấp cử chỉ cảm ứng đa điểm thông qua plugin.',
      'pl': 'Nadaje się do platform 3. generacji i nowszych, urządzeń wejściowych PS/2, takich jak klawiatury, myszy, gładziki. Zapewnia gesty wielodotykowe za pośrednictwem wtyczek.',
      'uk': 'Підходить для 3-го покоління та нових платформ, пристроїв введення PS/2, таких як клавіатури, миші, трекпади. Забезпечує мультисенсорні жести через плагіни.',
      'nl': 'Geschikt voor 3e generatie en nieuwere platforms, PS/2-invoerapparaten zoals toetsenborden, muizen en trackpads. Biedt multi-touch-bewegingen via plug-ins.',
      'hi': 'तीसरी पीढ़ी और नए प्लेटफ़ॉर्म, PS/2 इनपुट डिवाइस जैसे कीबोर्ड, चूहों, ट्रैकपैड के लिए उपयुक्त। प्लगइन्स के माध्यम से मल्टी-टच जेस्चर प्रदान करता है।',
      'ar': 'مناسب للجيل الثالث والمنصات الأحدث، وأجهزة إدخال PS/2 مثل لوحات المفاتيح والفئران ولوحات التتبع. يوفر إيماءات اللمس المتعدد عبر المكونات الإضافية.',
      'id': 'Cocok untuk platform Generasi ke-3 dan yang lebih baru, perangkat input PS/2 seperti keyboard, mouse, trackpad. Menyediakan gerakan multi-sentuh melalui plugin.',
    },
    'Suitable for 3rd Gen and older platforms, PS/2 input devices such as keyboards, mice, trackpads. Provides basic gesture support.': {
      'pt': 'Adequado para plataformas de 3ª geração e anteriores, dispositivos de entrada PS/2, como teclados, mouses e trackpads. Fornece suporte básico a gestos.',
      'zh': '适用于第三代及更早版本的平台、PS/2 输入设备，例如键盘、鼠标、触控板。提供基本的手势支持。',
      'zh_Hant': '適用於第三代及更早版本的平台、PS/2 輸入設備，例如鍵盤、滑鼠、觸控板。提供基本的手勢支援。',
      'es': 'Adecuado para plataformas de 3.ª generación y anteriores, dispositivos de entrada PS/2 como teclados, ratones y trackpads. Proporciona soporte básico de gestos.',
      'de': 'Geeignet für Plattformen der 3. Generation und älter, PS/2-Eingabegeräte wie Tastaturen, Mäuse, Trackpads. Bietet grundlegende Gestenunterstützung.',
      'fr': 'Convient aux plates-formes de 3e génération et plus anciennes, aux périphériques d\'entrée PS/2 tels que les claviers, les souris et les trackpads. Fournit un support gestuel de base.',
      'ru': 'Подходит для платформ 3-го поколения и более старых, устройств ввода PS/2, таких как клавиатуры, мыши, трекпады. Обеспечивает базовую поддержку жестов.',
      'ja': '第 3 世代以降のプラットフォーム、キーボード、マウス、トラックパッドなどの PS/2 入力デバイスに適しています。基本的なジェスチャのサポートを提供します。',
      'ko': '3세대 및 이전 플랫폼, 키보드, 마우스, 트랙패드와 같은 PS/2 입력 장치에 적합합니다. 기본적인 제스처 지원을 제공합니다.',
      'it': 'Adatto per piattaforme di terza generazione e precedenti, dispositivi di input PS/2 come tastiere, mouse, trackpad. Fornisce supporto gestuale di base.',
      'tr': '3. Nesil ve daha eski platformlar, klavye, fare, trackpad gibi PS/2 giriş cihazları için uygundur. Temel jest desteği sağlar.',
      'vi': 'Thích hợp cho các nền tảng thế hệ thứ 3 trở lên, các thiết bị đầu vào PS/2 như bàn phím, chuột, trackpad. Cung cấp hỗ trợ cử chỉ cơ bản.',
      'pl': 'Nadaje się do platform 3. generacji i starszych, urządzeń wejściowych PS/2, takich jak klawiatury, myszy, gładziki. Zapewnia podstawową obsługę gestów.',
      'uk': 'Підходить для 3-го покоління та старіших платформ, пристроїв введення PS/2, таких як клавіатури, миші, трекпади. Забезпечує базову підтримку жестів.',
      'nl': 'Geschikt voor 3e generatie en oudere platforms, PS/2-invoerapparaten zoals toetsenborden, muizen en trackpads. Biedt basisbewegingsondersteuning.',
      'hi': 'तीसरी पीढ़ी और पुराने प्लेटफ़ॉर्म, PS/2 इनपुट डिवाइस जैसे कीबोर्ड, चूहों, ट्रैकपैड के लिए उपयुक्त। बुनियादी इशारा समर्थन प्रदान करता है।',
      'ar': 'مناسب للجيل الثالث والمنصات الأقدم، وأجهزة إدخال PS/2 مثل لوحات المفاتيح والفئران ولوحات التتبع. يوفر دعمًا أساسيًا للإيماءات.',
      'id': 'Cocok untuk platform Generasi ke-3 dan yang lebih lama, perangkat input PS/2 seperti keyboard, mouse, trackpad. Memberikan dukungan gerakan dasar.',
    },
    'Supported macOS Versions:\n    • Wireless USB Big Sur Adapter V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (Requires OCLP USB root patch)\n    • Wireless USB Big Sur Adapter V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Supported USB Wi-Fi Chipsets:\n    • Primarily Realtek 802.11n and 802.11ac USB Wi-Fi Adapters; see author repository for detailed hardware lists': {
      'pt': 'Versões do macOS suportadas:\n    • Adaptador USB Big Sur sem fio V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (requer patch raiz USB OCLP)\n    • Adaptador USB Big Sur sem fio V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Chipsets Wi-Fi USB suportados:\n    • Principalmente adaptadores Wi-Fi USB Realtek 802.11n e 802.11ac; consulte o repositório do autor para listas detalhadas de hardware',
      'zh': '支持的 macOS 版本：\n    • 无线 USB Big Sur 适配器 V18：macOS Catalina 10.15.x ~ macOS Tahoe 26.x（需要 OCLP USB 根补丁）\n    • 无线 USB Big Sur 适配器 V15：OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  支持的 USB Wi-Fi 芯片组：\n    • 主要是Realtek 802.11n 和802.11ac USB Wi-Fi 适配器；有关详细的硬件列表，请参阅作者存储库',
      'zh_Hant': '支援的 macOS 版本：\n    • 無線 USB Big Sur 轉接器 V18：macOS Catalina 10.15.x ~ macOS Tahoe 26.x（需 OCLP USB 根補丁）\n    • 無線 USB Big Sur 轉接器 V15：OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  支援的 USB Wi-Fi 晶片組：\n    • 主要是Realtek 802.11n 和802.11ac USB Wi-Fi 適配器；有關詳細的硬體列表，請參閱作者存儲庫',
      'es': 'Versiones de macOS compatibles:\n    • Adaptador USB inalámbrico Big Sur V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (requiere parche raíz USB OCLP)\n    • Adaptador USB inalámbrico Big Sur V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Conjuntos de chips Wi-Fi USB compatibles:\n    • Principalmente adaptadores Wi-Fi USB Realtek 802.11n y 802.11ac; consulte el repositorio de autores para obtener listas detalladas de hardware',
      'de': 'Unterstützte macOS-Versionen:\n    • Drahtloser USB-Big-Sur-Adapter V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (erfordert OCLP USB-Root-Patch)\n    • Drahtloser USB-Big-Sur-Adapter V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Unterstützte USB-WLAN-Chipsätze:\n    • Hauptsächlich Realtek 802.11n- und 802.11ac-USB-WLAN-Adapter; Ausführliche Hardwarelisten finden Sie im Autoren-Repository',
      'fr': 'Versions macOS prises en charge :\n    • Adaptateur USB Big Sur sans fil V18 : macOS Catalina 10.15.x ~ macOS Tahoe 26.x (nécessite le correctif racine USB OCLP)\n    • Adaptateur USB Big Sur sans fil V15 : OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Chipsets Wi-Fi USB pris en charge :\n    • Principalement des adaptateurs Wi-Fi USB Realtek 802.11n et 802.11ac ; voir le référentiel de l\'auteur pour des listes détaillées de matériel',
      'ru': 'Поддерживаемые версии MacOS:\n    • Беспроводной USB-адаптер Big Sur V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (требуется корневой патч OCLP USB)\n    • Беспроводной USB-адаптер Big Sur версии 15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Поддерживаемые чипсеты USB Wi-Fi:\n    • В первую очередь USB-адаптеры Wi-Fi Realtek 802.11n и 802.11ac; подробные списки оборудования см. в репозитории автора.',
      'ja': 'サポートされている macOS バージョン:\n    • ワイヤレス USB Big Sur アダプター V18: macOS Catalina 10.15.x ～ macOS Tahoe 26.x (OCLP USB ルート パッチが必要)\n    • ワイヤレス USB Big Sur アダプター V15: OS X Mavericks 10.9 ～ macOS Catalina 10.15.x\n  サポートされている USB Wi-Fi チップセット:\n    • 主に Realtek 802.11n および 802.11ac USB Wi-Fi アダプター。詳細なハードウェア リストについては、作成者リポジトリを参照してください',
      'ko': '지원되는 macOS 버전:\n    • 무선 USB Big Sur 어댑터 V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x(OCLP USB 루트 패치 필요)\n    • 무선 USB Big Sur 어댑터 V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  지원되는 USB Wi-Fi 칩셋:\n    • 주로 Realtek 802.11n 및 802.11ac USB Wi-Fi 어댑터; 자세한 하드웨어 목록은 작성자 저장소를 참조하세요.',
      'it': 'Versioni macOS supportate:\n    • Adattatore wireless USB Big Sur V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (richiede la patch root USB OCLP)\n    • Adattatore USB Big Sur wireless V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Chipset Wi-Fi USB supportati:\n    • Principalmente adattatori Wi-Fi USB Realtek 802.11ne 802.11ac; vedere il repository dell\'autore per elenchi hardware dettagliati',
      'tr': 'Desteklenen macOS Sürümleri:\n    • Kablosuz USB Big Sur Adaptörü V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (OCLP USB root yamasını gerektirir)\n    • Kablosuz USB Big Sur Adaptörü V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Desteklenen USB Wi-Fi Yonga Setleri:\n    • Başta Realtek 802.11n ve 802.11ac USB Wi-Fi Adaptörleri; ayrıntılı donanım listeleri için yazar deposuna bakın',
      'vi': 'Các phiên bản macOS được hỗ trợ:\n    • Bộ chuyển đổi USB Big Sur không dây V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (Yêu cầu bản vá gốc USB OCLP)\n    • Bộ chuyển đổi USB Big Sur không dây V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Chipset USB Wi-Fi được hỗ trợ:\n    • Chủ yếu là Bộ điều hợp Wi-Fi USB Realtek 802.11n và 802.11ac; xem kho tác giả để biết danh sách phần cứng chi tiết',
      'pl': 'Obsługiwane wersje systemu macOS:\n    • Bezprzewodowy adapter USB Big Sur V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (wymaga poprawki root USB OCLP)\n    • Bezprzewodowy adapter USB Big Sur V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Obsługiwane chipsety USB Wi-Fi:\n    • Przede wszystkim adaptery USB Wi-Fi Realtek 802.11n i 802.11ac; szczegółowe listy sprzętu znajdziesz w repozytorium autora',
      'uk': 'Підтримувані версії macOS:\n    • Бездротовий USB-адаптер Big Sur V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (потрібен кореневий патч OCLP USB)\n    • Бездротовий USB-адаптер Big Sur V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Підтримувані набори мікросхем USB Wi-Fi:\n    • Переважно USB-адаптери Wi-Fi Realtek 802.11n і 802.11ac; дивіться репозиторій автора для детального списку обладнання',
      'nl': 'Ondersteunde macOS-versies:\n    • Draadloze USB Big Sur-adapter V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (vereist OCLP USB-rootpatch)\n    • Draadloze USB Big Sur-adapter V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Ondersteunde USB Wi-Fi-chipsets:\n    • Voornamelijk Realtek 802.11n en 802.11ac USB Wi-Fi-adapters; zie auteursrepository voor gedetailleerde hardwarelijsten',
      'hi': 'समर्थित macOS संस्करण:\n    • वायरलेस USB बिग सुर एडाप्टर V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (OCLP USB रूट पैच की आवश्यकता है)\n    • वायरलेस यूएसबी बिग सुर एडाप्टर वी15: ओएस एक्स मावेरिक्स 10.9 ~ मैकओएस कैटालिना 10.15.x\n  समर्थित यूएसबी वाई-फाई चिपसेट:\n    • मुख्य रूप से रियलटेक 802.11एन और 802.11एसी यूएसबी वाई-फाई एडाप्टर; विस्तृत हार्डवेयर सूचियों के लिए लेखक भंडार देखें',
      'ar': 'إصدارات نظام التشغيل Mac المدعومة:\n    • محول USB Big Sur اللاسلكي V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (يتطلب تصحيح جذر OCLP USB)\n    • محول USB Big Sur اللاسلكي V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  شرائح USB Wi-Fi المدعومة:\n    • في المقام الأول محولات Realtek 802.11n و802.11ac USB Wi-Fi؛ راجع مستودع المؤلف للحصول على قوائم الأجهزة التفصيلية',
      'id': 'Versi macOS yang didukung:\n    • Adaptor Big Sur USB Nirkabel V18: macOS Catalina 10.15.x ~ macOS Tahoe 26.x (Memerlukan patch root USB OCLP)\n    • Adaptor USB Big Sur Nirkabel V15: OS X Mavericks 10.9 ~ macOS Catalina 10.15.x\n  Chipset Wi-Fi USB yang didukung:\n    • Terutama Adaptor Wi-Fi USB Realtek 802.11n dan 802.11ac; lihat repositori penulis untuk daftar perangkat keras terperinci',
    },
