    'SyncRuntimePermissions(Fixes runtime memory permissions on newer boards (post-2018). If you cannot boot Windows without this option, enable it. Usually paired with RebuildAppleMemoryMap)': {
      'pt': 'SyncRuntimePermissions(corrige permissões de memória de tempo de execução em placas mais recentes (pós-2018). Se você não conseguir inicializar o Windows sem esta opção, habilite-a. Geralmente emparelhado com RebuildAppleMemoryMap)',
      'zh': 'SyncRuntimePermissions（修复较新主板（2018 年后）上的运行时内存权限。如果没有此选项则无法启动 Windows，请启用它。通常与 RebuildAppleMemoryMap 配对）',
      'zh_Hant': 'SyncRuntimePermissions（修復較新主機板（2018 年後）上的執行時間記憶體權限。如果沒有此選項則無法啟動 Windows，請啟用它。通常與 RebuildAppleMemoryMap 配對）',
      'es': 'SyncRuntimePermissions (Corrige los permisos de memoria de tiempo de ejecución en placas más nuevas (posteriores a 2018). Si no puede iniciar Windows sin esta opción, habilítela. Generalmente se combina con RebuildAppleMemoryMap)',
      'de': 'SyncRuntimePermissions (Korrigiert Laufzeitspeicherberechtigungen auf neueren Boards (nach 2018). Wenn Sie Windows ohne diese Option nicht starten können, aktivieren Sie sie. Normalerweise gepaart mit RebuildAppleMemoryMap.)',
      'fr': 'SyncRuntimePermissions (Corrige les autorisations de mémoire d\'exécution sur les cartes plus récentes (après 2018). Si vous ne pouvez pas démarrer Windows sans cette option, activez-la. Généralement associée à RebuildAppleMemoryMap)',
      'ru': 'SyncRuntimePermissions (исправляет права доступа к памяти во время выполнения на новых платах (после 2018 г.). Если вы не можете загрузить Windows без этой опции, включите ее. Обычно в сочетании с RebuildAppleMemoryMap)',
      'ja': 'SyncRuntimePermissions (新しいボード (2018 年以降) のランタイム メモリ アクセス許可を修正します。このオプションなしで Windows を起動できない場合は、これを有効にしてください。通常は RebuildAppleMemoryMap と組み合わせます)',
      'ko': 'SyncRuntimePermissions(최신 보드(2018년 이후)에서 런타임 메모리 권한을 수정합니다. 이 옵션 없이 Windows를 부팅할 수 없는 경우 활성화합니다. 일반적으로 RebuildAppleMemoryMap과 쌍을 이룹니다.)',
      'it': 'SyncRuntimePermissions (corregge le autorizzazioni di memoria di runtime sulle schede più recenti (post-2018). Se non è possibile avviare Windows senza questa opzione, abilitala. Solitamente abbinato a RebuildAppleMemoryMap)',
      'tr': 'SyncRuntimePermissions(Daha yeni anakartlarda (2018 sonrası) çalışma zamanı bellek izinlerini düzeltir. Windows\'u bu seçenek olmadan önyükleyemiyorsanız etkinleştirin. Genellikle RebuildAppleMemoryMap ile eşleştirilir)',
      'vi': 'SyncRuntimePermissions(Sửa quyền truy cập bộ nhớ thời gian chạy trên các bo mạch mới hơn (sau năm 2018). Nếu bạn không thể khởi động Windows nếu không có tùy chọn này, hãy bật nó. Thường được ghép nối với RebuildAppleMemoryMap)',
      'pl': 'SyncRuntimePermissions (naprawia uprawnienia pamięci wykonawczej na nowszych płytach (po 2018 r.). Jeśli nie możesz uruchomić systemu Windows bez tej opcji, włącz ją. Zwykle w połączeniu z RebuildAppleMemoryMap)',
      'uk': 'SyncRuntimePermissions (Виправляє дозволи пам’яті під час виконання на новіших платах (після 2018). Якщо ви не можете завантажити Windows без цього параметра, увімкніть його. Зазвичай поєднується з RebuildAppleMemoryMap)',
      'nl': 'SyncRuntimePermissions (Repareert runtime-geheugenrechten op nieuwere boards (na 2018). Als u Windows niet kunt opstarten zonder deze optie, schakelt u deze in. Meestal gecombineerd met RebuildAppleMemoryMap)',
      'hi': 'SyncRuntimePermissions (नए बोर्डों पर रनटाइम मेमोरी अनुमतियों को ठीक करता है (2018 के बाद)। यदि आप इस विकल्प के बिना विंडोज को बूट नहीं कर सकते हैं, तो इसे सक्षम करें। आमतौर पर RebuildAppleMemoryMap के साथ जोड़ा जाता है)',
      'ar': 'SyncRuntimePermissions(يصلح أذونات ذاكرة وقت التشغيل على اللوحات الأحدث (ما بعد 2018). إذا لم تتمكن من تشغيل Windows بدون هذا الخيار، فقم بتمكينه. عادةً ما يتم إقرانه مع RebuildAppleMemoryMap)',
      'id': 'SyncRuntimePermissions (Memperbaiki izin memori runtime pada board yang lebih baru (pasca 2018). Jika Anda tidak dapat mem-boot Windows tanpa opsi ini, aktifkan. Biasanya dipasangkan dengan RebuildAppleMemoryMap)',
    },
